css:
.dcf-dispatch {
  --dcf-dispatch-bg: oklch(0.205 0.009 70);
  --dcf-dispatch-ink: oklch(0.95 0.012 90);
  --dcf-dispatch-acc: oklch(0.9 0.19 122);
  --dcf-dispatch-warn: oklch(0.67 0.2 28);
  --dcf-dispatch-enroute: oklch(0.8 0.15 75);
  --dcf-dispatch-onsite: oklch(0.71 0.15 40);
  --dcf-dispatch-free: var(--dcf-dispatch-acc);
  --dcf-dispatch-break: oklch(0.64 0.02 80);
  --dcf-dispatch-panel: color-mix(in oklch, var(--dcf-dispatch-bg) 93%, var(--dcf-dispatch-ink));
  --dcf-dispatch-deep: color-mix(in oklch, var(--dcf-dispatch-bg) 78%, black);
  --dcf-dispatch-line: color-mix(in oklch, var(--dcf-dispatch-ink) 11%, transparent);
  --dcf-dispatch-hair: color-mix(in oklch, var(--dcf-dispatch-ink) 6%, transparent);
  --dcf-dispatch-soft: color-mix(in oklch, var(--dcf-dispatch-ink) 7%, transparent);
  --dcf-dispatch-mute: color-mix(in oklch, var(--dcf-dispatch-ink) 64%, var(--dcf-dispatch-bg));
  --dcf-dispatch-faint: color-mix(in oklch, var(--dcf-dispatch-ink) 40%, var(--dcf-dispatch-bg));
  --dcf-dispatch-land: color-mix(in oklch, var(--dcf-dispatch-bg) 90%, black);
  --dcf-dispatch-block: color-mix(in oklch, var(--dcf-dispatch-bg) 96%, var(--dcf-dispatch-ink));
  --dcf-dispatch-park: color-mix(in oklch, var(--dcf-dispatch-land) 80%, oklch(0.55 0.1 145));
  --dcf-dispatch-water: color-mix(in oklch, var(--dcf-dispatch-land) 72%, oklch(0.55 0.08 235));
  --dcf-dispatch-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dcf-dispatch-out: cubic-bezier(.16, 1, .3, 1);
  --dcf-dispatch-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.077 24.5%, 1.064 27.1%, 1.002 33.9%, .987 37.7%, .983 41.4%, .995 52.6%, 1.001 63.2%, 1);
  width: 100%;
  height: var(--dcf-dispatch-h, 680px);
  container-type: inline-size;
  container-name: dcf-dispatch;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 18px;
  background: var(--dcf-dispatch-bg);
  color: var(--dcf-dispatch-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dcf-dispatch-acc);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dcf-dispatch-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ul, ol, dl, dd, figure) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dcf-dispatch-acc); outline-offset: 2px; border-radius: 8px; }
  & [hidden] { display: none !important; }
}
.dcf-dispatch__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dcf-dispatch__cap { font-size: 10.5px; font-weight: 650; letter-spacing: .14em; text-transform: uppercase; color: var(--dcf-dispatch-faint); }

.dcf-dispatch__shell {
  height: 100%;
  display: grid;
  grid-template-columns: 196px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "rail head" "rail main";
}
.dcf-dispatch__rail {
  grid-area: rail; display: flex; flex-direction: column; gap: 6px; min-height: 0; overflow: auto;
  padding: 18px 12px 14px; border-right: 1px solid var(--dcf-dispatch-line); background: var(--dcf-dispatch-deep);
}
.dcf-dispatch__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 18px;
  & svg { width: 32px; height: 32px; flex: none; padding: 6px; border-radius: 10px; background: var(--dcf-dispatch-acc); fill: none; stroke: var(--dcf-dispatch-deep); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 760; letter-spacing: -.02em; }
  & small { display: block; font-size: 11px; color: var(--dcf-dispatch-mute); }
}
.dcf-dispatch__nav {
  display: grid; gap: 2px;
  & button {
    position: relative; display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px;
    color: var(--dcf-dispatch-mute); font-weight: 560; transition: background-color .2s, color .2s;
    &:hover { background: var(--dcf-dispatch-soft); color: var(--dcf-dispatch-ink); }
    &[aria-current="page"] { background: var(--dcf-dispatch-panel); color: var(--dcf-dispatch-ink); font-weight: 650; box-shadow: inset 0 0 0 1px var(--dcf-dispatch-line); }
    &[aria-current="page"] .dcf-dispatch__ic { color: var(--dcf-dispatch-acc); }
  }
}
.dcf-dispatch__badge {
  margin-left: auto; min-width: 20px; padding: 1px 6px; border-radius: 99px; font: 650 11px/1.4 var(--dcf-dispatch-mono); font-style: normal; text-align: center;
  background: color-mix(in oklch, var(--dcf-dispatch-warn) 24%, transparent); color: color-mix(in oklch, var(--dcf-dispatch-warn) 55%, var(--dcf-dispatch-ink));
}
.dcf-dispatch__shift {
  margin-top: auto; display: grid; gap: 6px; padding: 14px 8px 2px; border-top: 1px solid var(--dcf-dispatch-line);
}
.dcf-dispatch__clock { font: 650 30px/1 var(--dcf-dispatch-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; transition: opacity .3s; }
.dcf-dispatch__shell:has([data-live][aria-pressed="false"]) .dcf-dispatch__clock { opacity: .45; }
.dcf-dispatch__live {
  display: inline-flex; align-items: center; gap: 8px; width: fit-content; padding: 5px 11px 5px 9px; border-radius: 99px;
  font-size: 12px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--dcf-dispatch-line); transition: background-color .2s;
  &:hover { background: var(--dcf-dispatch-soft); }
  & i { width: 8px; height: 8px; border-radius: 50%; background: var(--dcf-dispatch-acc); box-shadow: 0 0 0 0 color-mix(in oklch, var(--dcf-dispatch-acc) 60%, transparent); animation: dcf-dispatch-beat 1.8s cubic-bezier(.3, 0, .2, 1) infinite; }
  &[aria-pressed="false"] i { background: var(--dcf-dispatch-break); animation: none; border-radius: 2px; }
}

.dcf-dispatch__head {
  grid-area: head; display: flex; align-items: end; justify-content: space-between; gap: 12px 24px; flex-wrap: wrap; padding: 18px 20px 14px;
  & h2 { margin-top: 2px; font-size: clamp(20px, 2.3cqi, 27px); font-weight: 760; letter-spacing: -.035em; line-height: 1.1; text-wrap: balance; }
}
.dcf-dispatch__kpis {
  display: flex; gap: 6px; flex-wrap: wrap;
  & div { min-width: 86px; padding: 7px 12px 8px; border-radius: 12px; background: var(--dcf-dispatch-panel); box-shadow: inset 0 0 0 1px var(--dcf-dispatch-hair); animation: dcf-dispatch-rise .6s var(--dcf-dispatch-out) both; animation-delay: calc(var(--i, 0) * 50ms); }
  & dt { font-size: 10.5px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--dcf-dispatch-faint); white-space: nowrap; }
  & dd { font: 680 20px/1.15 var(--dcf-dispatch-mono); letter-spacing: -.03em; font-variant-numeric: tabular-nums; }
  & dd.bump { animation: dcf-dispatch-bump .5s var(--dcf-dispatch-spring); }
  & .warn dd { color: color-mix(in oklch, var(--dcf-dispatch-warn) 70%, var(--dcf-dispatch-ink)); }
  & .good dd { color: var(--dcf-dispatch-acc); }
}

.dcf-dispatch__main { grid-area: main; min-height: 0; min-width: 0; padding: 0 20px 18px; }
.dcf-dispatch__view { height: 100%; min-height: 0; }
.dcf-dispatch__mapview { display: grid; grid-template-columns: 272px minmax(0, 1fr); gap: 12px; }
.dcf-dispatch__panel {
  position: relative; min-width: 0; min-height: 0; border-radius: 16px; background: var(--dcf-dispatch-panel);
  box-shadow: inset 0 0 0 1px var(--dcf-dispatch-hair), 0 24px 40px -34px black;
  animation: dcf-dispatch-rise .7s var(--dcf-dispatch-out) both; animation-delay: calc(var(--i, 0) * 70ms);
}
.dcf-dispatch__crews { display: flex; flex-direction: column; padding: 12px 10px 8px; }
.dcf-dispatch__ph {
  display: flex; align-items: baseline; justify-content: space-between; padding: 0 6px 10px;
  & h3 { font-size: 14px; font-weight: 700; letter-spacing: -.01em; }
}
.dcf-dispatch__count { font: 12px var(--dcf-dispatch-mono); color: var(--dcf-dispatch-mute); }
.dcf-dispatch__seg {
  display: grid; grid-template-columns: repeat(4, auto); gap: 2px; padding: 3px; margin: 0 2px 8px; border-radius: 11px; background: var(--dcf-dispatch-deep);
  & button { padding: 5px 4px; border-radius: 8px; font-size: 11.5px; font-weight: 620; text-align: center; color: var(--dcf-dispatch-mute); transition: color .2s, background-color .2s; }
  & button:hover { color: var(--dcf-dispatch-ink); }
  & button[aria-checked="true"] { background: var(--dcf-dispatch-panel); color: var(--dcf-dispatch-ink); box-shadow: inset 0 0 0 1px var(--dcf-dispatch-line); }
}
.dcf-dispatch__list {
  flex: 1; min-height: 0; overflow: auto; display: grid; align-content: start; gap: 2px; padding: 2px;
  & li {
    --c: var(--dcf-dispatch-break);
    display: grid; grid-template-columns: 34px minmax(0, 1fr) auto; align-items: center; gap: 2px 10px; padding: 8px; border-radius: 11px; cursor: pointer;
    transition: background-color .2s, opacity .3s, filter .3s;
    &:hover { background: var(--dcf-dispatch-soft); }
    &[aria-selected="true"] { background: color-mix(in oklch, var(--c) 13%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 40%, transparent); }
    &.dim { opacity: .32; filter: saturate(.3); }
    &.s-enroute { --c: var(--dcf-dispatch-enroute); } &.s-onsite { --c: var(--dcf-dispatch-onsite); } &.s-free { --c: var(--dcf-dispatch-free); }
  }
  & .av { grid-row: span 2; display: grid; place-items: center; width: 34px; height: 34px; border-radius: 10px; font: 700 12px var(--dcf-dispatch-mono); color: var(--dcf-dispatch-deep); background: var(--c); }
  & .nm { font-weight: 650; letter-spacing: -.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .sk { display: flex; gap: 3px; color: var(--dcf-dispatch-faint); & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; } }
  & .sub { grid-column: 2 / 4; font-size: 11.5px; color: var(--dcf-dispatch-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; }
  & .hold { margin-left: 6px; padding: 0 5px; border-radius: 4px; font-size: 9.5px; font-weight: 700; letter-spacing: .06em; color: var(--dcf-dispatch-deep); background: var(--dcf-dispatch-warn); vertical-align: 1px; }
}

.dcf-dispatch__mapwrap { overflow: hidden; background: var(--dcf-dispatch-land); }
.dcf-dispatch__map {
  position: absolute; inset: 0; width: 100%; height: 100%; display: block;
  & .blk { fill: var(--dcf-dispatch-block); animation: dcf-dispatch-fade .8s ease-out both; animation-delay: calc(var(--i) * 12ms); }
  & .park { fill: var(--dcf-dispatch-park); }
  & .river { fill: none; stroke: var(--dcf-dispatch-water); stroke-width: 58; stroke-linecap: round; }
  & .st { fill: none; stroke: color-mix(in oklch, var(--dcf-dispatch-ink) 13%, var(--dcf-dispatch-land)); stroke-width: 7; stroke-linecap: round; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dcf-dispatch-draw 1.1s var(--dcf-dispatch-out) forwards; animation-delay: calc(var(--i) * 40ms); }
  & .st.major { stroke-width: 10; stroke: color-mix(in oklch, var(--dcf-dispatch-ink) 19%, var(--dcf-dispatch-land)); }
  & .bridge { fill: none; stroke: color-mix(in oklch, var(--dcf-dispatch-ink) 30%, var(--dcf-dispatch-land)); stroke-width: 16; }
  & .dl { font: 700 15px system-ui, sans-serif; letter-spacing: .26em; fill: color-mix(in oklch, var(--dcf-dispatch-ink) 30%, var(--dcf-dispatch-land)); text-transform: uppercase; }
  & .sn { font: 500 12px var(--dcf-dispatch-mono); fill: color-mix(in oklch, var(--dcf-dispatch-ink) 34%, var(--dcf-dispatch-land)); }
  & .rt { fill: none; stroke: var(--dcf-dispatch-enroute); stroke-width: 4; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 2 9; opacity: .85; animation: dcf-dispatch-march 1.4s linear infinite; }
  & .rt.sel { stroke-width: 6; opacity: 1; }
  & .rtd { fill: none; stroke: var(--dcf-dispatch-enroute); stroke-width: 4; stroke-dasharray: 1; stroke-dashoffset: 1; opacity: .9; animation: dcf-dispatch-draw .9s var(--dcf-dispatch-out) forwards; }
}
.dcf-dispatch__mapwrap:has([data-layer="routes"][aria-pressed="false"]) :is(.rt, .rtd) { display: none; }
.dcf-dispatch__pin {
  cursor: pointer; outline: none;
  & .in { transform-box: fill-box; transform-origin: center; animation: dcf-dispatch-pop .7s var(--dcf-dispatch-spring) both; animation-delay: calc(400ms + var(--i) * 45ms); transition: transform .3s var(--dcf-dispatch-spring), opacity .4s; }
  & .hit { fill: transparent; }
  & .trk { fill: none; stroke: color-mix(in oklch, var(--dcf-dispatch-ink) 12%, transparent); stroke-width: 4.5; }
  & .sla { fill: none; stroke: var(--dcf-dispatch-mute); stroke-width: 4.5; stroke-linecap: round; transition: stroke-dasharray .8s var(--dcf-dispatch-out), stroke .4s; }
  & .core { fill: var(--dcf-dispatch-deep); stroke: color-mix(in oklch, var(--dcf-dispatch-ink) 55%, transparent); stroke-width: 1.6; transition: fill .3s, stroke .3s; }
  & .gl { fill: none; stroke: var(--dcf-dispatch-ink); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
  & .p1 { fill: var(--dcf-dispatch-warn); stroke: var(--dcf-dispatch-land); stroke-width: 2; }
  &.risk .sla { stroke: var(--dcf-dispatch-enroute); }
  &.late .sla { stroke: var(--dcf-dispatch-warn); }
  &.assigned .core { stroke: var(--dcf-dispatch-enroute); stroke-dasharray: 4 3; }
  &.inprog .core { fill: color-mix(in oklch, var(--dcf-dispatch-onsite) 60%, var(--dcf-dispatch-deep)); stroke: var(--dcf-dispatch-onsite); }
  &.inprog .sla { stroke: var(--dcf-dispatch-onsite); }
  &.done .in { opacity: 0; transform: scale(.3); }
  &:hover .in, &:focus-visible .in { transform: scale(1.14); }
  &:focus-visible .core { stroke: var(--dcf-dispatch-acc); stroke-width: 3; }
  &.sel .core { stroke: var(--dcf-dispatch-acc); stroke-width: 3; stroke-dasharray: none; }
  &.sel .hit { fill: color-mix(in oklch, var(--dcf-dispatch-acc) 14%, transparent); }
}
.dcf-dispatch__van {
  cursor: pointer; outline: none;
  --c: var(--dcf-dispatch-break);
  &.s-enroute { --c: var(--dcf-dispatch-enroute); } &.s-onsite { --c: var(--dcf-dispatch-onsite); } &.s-free { --c: var(--dcf-dispatch-free); }
  & .in { transform-box: fill-box; transform-origin: center; animation: dcf-dispatch-pop .6s var(--dcf-dispatch-spring) both; animation-delay: calc(700ms + var(--i) * 60ms); transition: opacity .3s, filter .3s; }
  & .halo { fill: none; stroke: var(--c); stroke-width: 2; opacity: 0; transform-box: fill-box; transform-origin: center; }
  & rect { fill: var(--c); stroke: var(--dcf-dispatch-land); stroke-width: 2.5; transition: fill .4s; }
  & .ini { font: 750 14px var(--dcf-dispatch-mono); fill: var(--dcf-dispatch-deep); text-anchor: middle; pointer-events: none; }
  & .nm { font: 650 15px system-ui, sans-serif; fill: var(--dcf-dispatch-ink); paint-order: stroke; stroke: var(--dcf-dispatch-land); stroke-width: 5; stroke-linejoin: round; opacity: 0; transition: opacity .3s; pointer-events: none; }
  &.dim .in { opacity: .25; filter: saturate(.2); }
  &.sel .halo, &:focus-visible .halo { opacity: 1; animation: dcf-dispatch-halo 1.6s cubic-bezier(.2, .6, .3, 1) infinite; }
  &.sel .nm, &:hover .nm, &:focus-visible .nm { opacity: 1; }
}
.dcf-dispatch__mapwrap:has([data-layer="names"][aria-pressed="true"]) .dcf-dispatch__van .nm { opacity: 1; }
.dcf-dispatch__tools {
  position: absolute; top: 12px; left: 12px; display: flex; gap: 6px;
  & button {
    display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px 6px 8px; border-radius: 10px; font-size: 12px; font-weight: 620;
    background: color-mix(in oklch, var(--dcf-dispatch-deep) 82%, transparent); backdrop-filter: blur(6px); box-shadow: inset 0 0 0 1px var(--dcf-dispatch-line); color: var(--dcf-dispatch-mute);
    transition: color .2s, background-color .2s;
    &:hover { color: var(--dcf-dispatch-ink); }
    &[aria-pressed="true"] { color: var(--dcf-dispatch-ink); & .dcf-dispatch__ic { color: var(--dcf-dispatch-acc); } }
    & .dcf-dispatch__ic { width: 16px; height: 16px; }
  }
}
.dcf-dispatch__legend {
  position: absolute; left: 12px; bottom: 10px; display: flex; flex-wrap: wrap; gap: 4px 12px; padding: 6px 10px; border-radius: 10px;
  font-size: 11px; color: var(--dcf-dispatch-mute); background: color-mix(in oklch, var(--dcf-dispatch-deep) 82%, transparent); pointer-events: none;
  & li { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 12px; height: 9px; border-radius: 3px; background: var(--c); }
  & b { width: 12px; height: 12px; border-radius: 50%; border: 2.5px solid var(--dcf-dispatch-mute); border-right-color: transparent; transform: rotate(45deg); }
}
.dcf-dispatch__legend--inline { position: static; background: none; padding: 0; }

.dcf-dispatch__drawer {
  position: absolute; top: 10px; right: 10px; bottom: 10px; width: min(284px, calc(100% - 20px)); z-index: 5; overflow: auto;
  padding: 16px; border-radius: 14px; background: color-mix(in oklch, var(--dcf-dispatch-bg) 92%, black);
  box-shadow: inset 0 0 0 1px var(--dcf-dispatch-line), 0 24px 48px -16px black;
  transform: translateX(calc(100% + 20px)); visibility: hidden;
  transition: transform .5s var(--dcf-dispatch-out), visibility 0s linear .5s;
  &.on { transform: none; visibility: visible; transition: transform .55s var(--dcf-dispatch-spring), visibility 0s; }
  & h4 { margin: 4px 0 2px; font-size: 16px; font-weight: 720; letter-spacing: -.02em; line-height: 1.25; text-wrap: balance; }
  & p { margin: 0; color: var(--dcf-dispatch-mute); text-wrap: pretty; }
  & .x { position: absolute; top: 10px; right: 10px; display: grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; color: var(--dcf-dispatch-mute); &:hover { background: var(--dcf-dispatch-soft); color: var(--dcf-dispatch-ink); } }
  & .tags { display: flex; gap: 6px; flex-wrap: wrap; padding-right: 30px; }
  & .tag { padding: 2px 7px; border-radius: 6px; font-size: 10.5px; font-weight: 700; letter-spacing: .05em; text-transform: uppercase; background: var(--dcf-dispatch-soft); color: var(--dcf-dispatch-mute); }
  & .tag.p1 { background: color-mix(in oklch, var(--dcf-dispatch-warn) 25%, transparent); color: color-mix(in oklch, var(--dcf-dispatch-warn) 50%, var(--dcf-dispatch-ink)); }
  & .sla { margin: 14px 0 4px; display: grid; gap: 6px; font-size: 12px; color: var(--dcf-dispatch-mute); font-variant-numeric: tabular-nums; }
  & .sla b { color: var(--dcf-dispatch-ink); font-family: var(--dcf-dispatch-mono); }
  & .bar { height: 6px; border-radius: 3px; background: var(--dcf-dispatch-soft); overflow: hidden; }
  & .bar i { display: block; height: 100%; width: 100%; border-radius: 3px; background: var(--c, var(--dcf-dispatch-mute)); transform-origin: left; transform: scaleX(var(--p)); transition: transform .8s var(--dcf-dispatch-out); }
  & .stat { margin-top: 12px; padding: 10px 12px; border-radius: 10px; background: var(--dcf-dispatch-soft); font-size: 12.5px; }
  & h5 { margin: 16px 0 6px; font-size: 10.5px; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; color: var(--dcf-dispatch-faint); }
  & .rec { display: grid; gap: 4px; }
  & .rc {
    display: grid; grid-template-columns: 30px minmax(0, 1fr) auto; align-items: center; gap: 0 10px; padding: 8px; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--dcf-dispatch-hair);
    animation: dcf-dispatch-rise .5s var(--dcf-dispatch-out) both; animation-delay: calc(var(--i) * 60ms);
    & .av { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; font: 700 11px var(--dcf-dispatch-mono); color: var(--dcf-dispatch-deep); background: var(--c); }
    & b { display: block; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & small { display: block; font-size: 11px; color: var(--dcf-dispatch-mute); font-variant-numeric: tabular-nums; }
  }
  & .btn {
    padding: 6px 11px; border-radius: 9px; font-size: 12px; font-weight: 700; background: var(--dcf-dispatch-acc); color: var(--dcf-dispatch-deep);
    transition: filter .2s, transform .2s var(--dcf-dispatch-spring);
    &:hover { filter: brightness(1.08); } &:active { transform: scale(.96); }
    &[aria-disabled="true"] { background: var(--dcf-dispatch-soft); color: var(--dcf-dispatch-faint); cursor: not-allowed; }
    &.ghost { background: transparent; color: var(--dcf-dispatch-ink); box-shadow: inset 0 0 0 1px var(--dcf-dispatch-line); }
    &.ghost[aria-pressed="true"] { background: color-mix(in oklch, var(--dcf-dispatch-warn) 22%, transparent); box-shadow: inset 0 0 0 1px var(--dcf-dispatch-warn); }
  }
  &[data-quiet] .rc { animation: none; }
  & .acts { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
  & .facts { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin-top: 12px; }
  & .facts div { padding: 8px; border-radius: 10px; background: var(--dcf-dispatch-soft); }
  & .facts dt { font-size: 10px; color: var(--dcf-dispatch-faint); text-transform: uppercase; letter-spacing: .06em; }
