const RM = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => Array.from((el || root).querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const hm = (m) => { m = Math.floor(m); return String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0'); };
const dur = (m) => { const s = m < 0 ? '−' : ''; m = Math.abs(Math.round(m)); return s + (m >= 60 ? Math.floor(m / 60) + 'h ' + String(m % 60).padStart(2, '0') + 'm' : m + ' min'); };
const T = (h, m) => h * 60 + m;

/* ------------------------------------------------------------------ city + data
   Streets are a grid; every job sits on a north–south street and every parked van on an
   east–west one, so a route is at most three straight legs that never leave the roads. */
const SPEED = 0.5;                 /* simulated minutes per real second */
const VX = [70, 190, 310, 430, 550, 670, 790, 910];
const HY = [60, 165, 270, 375, 480];
const MIN_PER_UNIT = 0.015;        /* 1 map unit is ~6 m; vans average ~24 km/h in town */
const TRADE = { hvac: 'HVAC', plumb: 'Plumbing', elec: 'Electrical', refr: 'Refrigeration' };
const GLYPH = {
  hvac: 'M10 4a2 2 0 0 1 4 0v9.5a4 4 0 1 1-4 0z',
  plumb: 'M12 3.5c3.2 4.2 5.5 7.3 5.5 10.2a5.5 5.5 0 0 1-11 0c0-2.9 2.3-6 5.5-10.2z',
