const WINDOW = { 1: 240, 2: 480, 3: 1440 };
const JOBS = [
  ['J-4102', 'Greyfriars Bakery', 'Walk-in cooler not holding 4 °C', 'refr', 1, 190, 120, 'Old Quay', T(9, 38), 90],
  ['J-4105', 'Kestrel Court Apartments', 'No hot water in block B', 'plumb', 2, 670, 225, 'Northfield', T(8, 12), 60],
  ['J-4108', 'Merrow Dental Studio', 'Surgery AC trips its breaker', 'hvac', 2, 430, 330, 'Calder Heights', T(9, 55), 50],
  ['J-4111', 'Albion Cold Store', 'Burst pipe in the plant room', 'plumb', 1, 910, 430, 'Riverside', T(10, 52), 75],
  ['J-4114', "St Brennan's Primary School", 'Boiler in lockout, classrooms cold', 'hvac', 1, 310, 220, 'Old Quay', T(9, 10), 60],
  ['J-4115', 'Harrow & Finch Opticians', 'Lighting circuit trips the RCD', 'elec', 2, 550, 110, 'Northfield', T(7, 55), 45],
  ['J-4117', 'Calder Heights Leisure Centre', 'Pool plant pump grinding', 'plumb', 3, 790, 330, 'Calder Heights', T(10, 20), 90],
  ['J-4118', 'Northfield Medical Practice', 'Server room AC high-temperature alarm', 'hvac', 1, 670, 110, 'Northfield', T(8, 50), 45],
  ['J-4120', 'The Tin Kettle Café', 'Kitchen extractor fan dead', 'elec', 3, 70, 420, 'Old Quay', T(11, 2), 40],
