].map((r, i) => ({ id: r[0], cust: r[1], issue: r[2], trade: r[3], pri: r[4], x: r[5], y: r[6], dist: r[7], logged: r[8], est: r[9], due: r[8] + WINDOW[r[4]], status: 'open', crew: null, n: i }));
const J = Object.fromEntries(JOBS.map((j) => [j.id, j]));
const B = (a, b, kind, label, live) => ({ a, b, kind, label, live: !!live });
const CREWS = [
  { id: 'C1', name: 'Dana Whitlock', skills: ['hvac', 'refr'], status: 'onsite', x: 190, y: 120, job: 'J-4102', startAt: T(11, 5),
    log: [B(T(7, 35), T(9, 5), 'job', 'J-4088 Fenwick Arms · cellar cooling'), B(T(9, 5), T(9, 22), 'travel'), B(T(9, 22), T(10, 40), 'job', 'J-4094 Quayside Fishmongers · display chiller'), B(T(10, 40), T(11, 5), 'travel')] },
  { id: 'C2', name: 'Marco Ilves', skills: ['plumb'], status: 'enroute', x: 320, y: 375, job: 'J-4111', depart: T(11, 35),
    log: [B(T(7, 40), T(8, 55), 'job', 'J-4089 Linden Terrace · stopcock'), B(T(8, 55), T(9, 15), 'travel'), B(T(9, 15), T(11, 20), 'job', 'J-4096 Harbour Gym · shower mixers')] },
  { id: 'C3', name: 'Priya Nandakumar', skills: ['elec'], status: 'free', x: 480, y: 165,
    log: [B(T(8, 0), T(10, 15), 'job', 'J-4090 Calder Library · emergency lighting'), B(T(10, 15), T(10, 35), 'travel'), B(T(10, 35), T(11, 30), 'job', 'J-4099 Pell Street Bakery · oven isolator')] },
  { id: 'C4', name: 'Tom Okafor', skills: ['hvac'], status: 'enroute', x: 110, y: 270, job: 'J-4108', depart: T(11, 40),
    log: [B(T(7, 30), T(9, 45), 'job', 'J-4087 Northfield Clinic · AHU belt'), B(T(9, 45), T(10, 5), 'travel'), B(T(10, 5), T(11, 15), 'job', 'J-4097 Brick Lane Studios · split unit')] },
