    log: [B(T(7, 45), T(10, 50), 'job', 'J-4091 Kestrel Court · riser valve'), B(T(10, 50), T(11, 20), 'travel')] },
  { id: 'C6', name: 'Luis Carvalho', skills: ['hvac', 'refr'], status: 'free', x: 780, y: 270,
    log: [B(T(8, 15), T(11, 0), 'job', 'J-4092 Albion Cold Store · condenser fan')] },
  { id: 'C7', name: 'Aiyana Redcloud', skills: ['elec'], status: 'break', x: 290, y: 375, until: T(12, 15), breakFrom: T(11, 45),
