];
CREWS.forEach((c, i) => { c.n = i; c.ini = c.name.split(' ').map((w) => w[0]).join(''); c.hold = false; });
const C = Object.fromEntries(CREWS.map((c) => [c.id, c]));

function route(ax, ay, bx, by) {
  const pts = [[ax, ay]]; let x = ax, y = ay;
  if (!HY.includes(y)) {
    if (x === bx) { pts.push([bx, by]); return pts; }
    y = HY.reduce((a, b) => (Math.abs(b - ay) < Math.abs(a - ay) ? b : a));
    pts.push([x, y]);
  }
  if (x !== bx) { x = bx; pts.push([x, y]); }
  if (y !== by) pts.push([bx, by]);
  return pts;
}
const plen = (p) => p.reduce((t, q, i) => (i ? t + Math.abs(q[0] - p[i - 1][0]) + Math.abs(q[1] - p[i - 1][1]) : 0), 0);
function along(p, d) {
  for (let i = 1; i < p.length; i++) {
    const l = Math.abs(p[i][0] - p[i - 1][0]) + Math.abs(p[i][1] - p[i - 1][1]);
    if (d <= l) { const k = l ? d / l : 0; return [p[i - 1][0] + (p[i][0] - p[i - 1][0]) * k, p[i - 1][1] + (p[i][1] - p[i - 1][1]) * k]; }
    d -= l;
  }
  return p[p.length - 1];
