const travel = (c, j) => 2 + plen(route(c.x, c.y, j.x, j.y)) * MIN_PER_UNIT;
function dispatch(c, j, at) {
  c.pts = route(c.x, c.y, j.x, j.y); c.len = plen(c.pts); c.depart = at; c.eta = 2 + c.len * MIN_PER_UNIT;
  c.status = 'enroute'; c.job = j.id; j.status = 'assigned'; j.crew = c.id;
}
CREWS.forEach((c) => {
  if (c.status === 'enroute') dispatch(c, J[c.job], c.depart);
  if (c.status === 'onsite') { J[c.job].status = 'inprog'; J[c.job].crew = c.id; }
});

/* ------------------------------------------------------------------ state */
let now = T(11, 42), live = true, onScreen = true, raf = 0, last = 0, lastMin = -1;
let view = 'map', filter = 'all', selJob = null, selCrew = null, done = 12;
let sortKey = 'left', sortDir = 1;
const svgMap = $('[data-map]'), gBase = $('[data-base]'), gRoutes = $('[data-routes]'), gPins = $('[data-pins]'), gVans = $('[data-vans]');
const drawer = $('[data-drawer]'), tip = $('[data-tip]'), toastEl = $('[data-toast]');

const left = (j) => j.due - now;
const slaState = (j) => (j.status === 'inprog' ? 'ok' : left(j) < 0 ? 'late' : left(j) < 90 ? 'risk' : 'ok');
const statusTxt = { open: 'Unassigned', assigned: 'Crew en route', inprog: 'In progress', done: 'Completed' };
const crewStat = { enroute: 'En route', onsite: 'On site', free: 'Free', break: 'Break' };
const finishAt = (c) => c.startAt + J[c.job].est;

/* ------------------------------------------------------------------ base map */
(function drawBase() {
