css:
.dcf-critical {
  --dcf-critical-paper: oklch(0.975 0.011 85);
  --dcf-critical-ink: oklch(0.27 0.022 60);
  --dcf-critical-crit: oklch(0.6 0.2 31);
  --dcf-critical-near: oklch(0.73 0.14 74);
  --dcf-critical-card: color-mix(in oklch, var(--dcf-critical-paper) 55%, white);
  --dcf-critical-sunk: color-mix(in oklch, var(--dcf-critical-paper) 93%, var(--dcf-critical-ink));
  --dcf-critical-bar: color-mix(in oklch, var(--dcf-critical-ink) 46%, var(--dcf-critical-paper));
  --dcf-critical-line: color-mix(in oklch, var(--dcf-critical-ink) 14%, transparent);
  --dcf-critical-hair: color-mix(in oklch, var(--dcf-critical-ink) 7%, transparent);
  --dcf-critical-soft: color-mix(in oklch, var(--dcf-critical-ink) 5%, transparent);
  --dcf-critical-mute: color-mix(in oklch, var(--dcf-critical-ink) 64%, var(--dcf-critical-paper));
  --dcf-critical-faint: color-mix(in oklch, var(--dcf-critical-ink) 42%, var(--dcf-critical-paper));
  --dcf-critical-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dcf-critical-out: cubic-bezier(.2, .9, .25, 1);
  --dcf-critical-spring: linear(0, .008, .031 2.2%, .126 4.6%, .667 13.8%, .89 18.6%, 1.006 23.5%, 1.051 27.3%, 1.064 30.6%, 1.059 34%, 1.017 43.2%, .998 51.6%, .994 58.6%, 1.001 79.8%, 1);
  --dcf-critical-row: 30px;
  width: 100%;
  height: var(--dcf-critical-h, 680px);
  container-type: inline-size;
  container-name: dcf-critical;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 18px;
  background: var(--dcf-critical-paper);
  color: var(--dcf-critical-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dcf-critical-crit);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dcf-critical-ink) 24%, transparent) transparent;
  box-shadow: inset 0 0 0 1px var(--dcf-critical-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, ol, dl, dd) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dcf-critical-crit); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
}
.dcf-critical__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dcf-critical__cap { font-size: 10.5px; font-weight: 650; letter-spacing: .14em; text-transform: uppercase; color: var(--dcf-critical-faint); }

.dcf-critical__shell {
  height: 100%;
  display: grid;
  grid-template-columns: 184px minmax(0, 1fr) 270px;
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "rail head head" "rail tools insp" "rail main insp";
}
.dcf-critical__rail {
  grid-area: rail; display: flex; flex-direction: column; gap: 6px; padding: 18px 12px 14px; min-height: 0; overflow: auto;
  border-right: 1px solid var(--dcf-critical-line);
  background: repeating-linear-gradient(0deg, var(--dcf-critical-hair) 0 1px, transparent 1px 16px), var(--dcf-critical-sunk);
}
.dcf-critical__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 18px;
  & svg { width: 32px; height: 32px; flex: none; padding: 6px; border-radius: 9px; background: var(--dcf-critical-ink); fill: none; stroke: var(--dcf-critical-paper); stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 14px; font-weight: 760; letter-spacing: -.02em; line-height: 1.2; }
  & small { display: block; font-size: 11px; color: var(--dcf-critical-mute); }
}
.dcf-critical__nav {
  display: grid; gap: 2px;
  & button {
    display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 9px; color: var(--dcf-critical-mute); font-weight: 560; transition: background-color .2s, color .2s;
    &:hover { background: var(--dcf-critical-soft); color: var(--dcf-critical-ink); }
    &[aria-current="page"] { background: var(--dcf-critical-card); color: var(--dcf-critical-ink); font-weight: 680; box-shadow: inset 0 0 0 1px var(--dcf-critical-line), 0 2px 0 var(--dcf-critical-hair); }
    &[aria-current="page"] .dcf-critical__ic { color: var(--dcf-critical-crit); }
  }
}
.dcf-critical__foot {
  margin-top: auto; display: grid; gap: 10px; padding: 12px 8px 0; border-top: 1px solid var(--dcf-critical-line); font-size: 11.5px; color: var(--dcf-critical-mute); text-wrap: pretty;
  & b { display: block; color: var(--dcf-critical-ink); font-weight: 650; }
}

.dcf-critical__head {
  grid-area: head; display: flex; align-items: end; justify-content: space-between; flex-wrap: wrap; gap: 12px 20px; padding: 18px 20px 12px;
  & h2 { margin-top: 2px; font-size: clamp(20px, 2.3cqi, 27px); font-weight: 780; letter-spacing: -.035em; line-height: 1.1; text-wrap: balance; }
}
.dcf-critical__kpis {
  display: flex; flex-wrap: wrap; gap: 0;
  & div { position: relative; padding: 2px 16px 2px 16px; border-left: 1px solid var(--dcf-critical-line); animation: dcf-critical-rise .6s var(--dcf-critical-out) both; animation-delay: calc(var(--i) * 60ms); }
  & dt { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dcf-critical-faint); white-space: nowrap; }
  & dd { display: flex; align-items: baseline; gap: 6px; font: 680 19px/1.2 var(--dcf-critical-mono); letter-spacing: -.035em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & dd small { font: 700 11px var(--dcf-critical-mono); letter-spacing: 0; padding: 1px 6px; border-radius: 6px; background: var(--dcf-critical-soft); color: var(--dcf-critical-mute); }
  & dd small.late { background: color-mix(in oklch, var(--dcf-critical-crit) 16%, transparent); color: var(--dcf-critical-crit); }
  & dd small.early { background: color-mix(in oklch, oklch(0.6 0.13 150) 18%, transparent); color: oklch(0.45 0.12 150); }
  & dd.bad { color: var(--dcf-critical-crit); }
  & dd.flash { animation: dcf-critical-flash .7s var(--dcf-critical-out); }
}

.dcf-critical__tools {
  grid-area: tools; display: flex; align-items: center; flex-wrap: wrap; gap: 8px 10px; padding: 0 20px 10px;
}
.dcf-critical__seg {
  display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dcf-critical-sunk); box-shadow: inset 0 0 0 1px var(--dcf-critical-hair);
  & button { padding: 4px 11px; border-radius: 7px; font-size: 12px; font-weight: 620; color: var(--dcf-critical-mute); transition: color .2s, background-color .2s; }
  & button:hover { color: var(--dcf-critical-ink); }
  & button[aria-checked="true"] { background: var(--dcf-critical-card); color: var(--dcf-critical-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dcf-critical-ink) 20%, transparent); }
  &[aria-disabled="true"] { opacity: .45; & button { cursor: not-allowed; } }
}
.dcf-critical__key {
  display: flex; flex-wrap: wrap; gap: 4px 12px; margin-left: auto; font-size: 11.5px; color: var(--dcf-critical-mute);
  & li { display: inline-flex; align-items: center; gap: 6px; }
  & i { width: 16px; height: 8px; border-radius: 2px; }
  & .k-crit { background: var(--dcf-critical-crit); } & .k-near { background: var(--dcf-critical-near); } & .k-bar { background: var(--dcf-critical-bar); }
  & .k-fl { height: 4px; background: repeating-linear-gradient(90deg, var(--dcf-critical-bar) 0 3px, transparent 3px 5px); }
}

.dcf-critical__main { grid-area: main; min-width: 0; min-height: 0; padding: 0 12px 16px 20px; }
.dcf-critical__view { height: 100%; min-height: 0; border-radius: 14px; background: var(--dcf-critical-card); box-shadow: inset 0 0 0 1px var(--dcf-critical-line), 0 18px 34px -30px color-mix(in oklch, var(--dcf-critical-ink) 60%, transparent); overflow: hidden; animation: dcf-critical-rise .7s var(--dcf-critical-out) both .1s; }

/* ---------- gantt: one grid; every row is a subgrid of it so the header, table cells and timeline share tracks */
.dcf-critical__gantt {
  --tw: minmax(340px, 1fr);
  height: 100%; overflow: auto; position: relative;
  &.zoom { --tw: calc(var(--n) * 15px); }
  & .g { display: grid; grid-template-columns: 34px minmax(110px, 176px) 44px 40px var(--tw); min-width: 100%; width: max-content; }
  &:not(.zoom) .g { width: 100%; }
  & .hd { position: sticky; top: 0; z-index: 4; grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; height: 44px; background: var(--dcf-critical-card); border-bottom: 1px solid var(--dcf-critical-line); }
  & .lc { position: sticky; left: 0; z-index: 2; grid-column: 1 / 5; display: grid; grid-template-columns: subgrid; align-items: center; background: inherit; border-right: 1px solid var(--dcf-critical-line); }
  & .hd .lc { align-items: end; padding-bottom: 7px; font-size: 10px; font-weight: 680; letter-spacing: .1em; text-transform: uppercase; color: var(--dcf-critical-faint); }
  & .lc > span { padding: 0 6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .lc > span:nth-child(n + 3) { text-align: right; font-family: var(--dcf-critical-mono); font-variant-numeric: tabular-nums; }
  & .th { position: relative; overflow: hidden; }
  & .th .mo { position: absolute; top: 6px; font-size: 11px; font-weight: 700; padding-left: 5px; border-left: 1px solid var(--dcf-critical-line); height: 34px; white-space: nowrap; }
  & .th .wk { position: absolute; bottom: 5px; font: 9.5px var(--dcf-critical-mono); color: var(--dcf-critical-faint); translate: 3px 0; }
  & .bd { position: relative; grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; }
  & .ov { grid-column: 5; position: relative; pointer-events: none;
          background-image: repeating-linear-gradient(90deg, var(--dcf-critical-hair) 0 1px, transparent 1px calc(100% * 5 / var(--n))); }
  & .hol { position: absolute; top: 0; bottom: 0; left: calc(var(--a) * 1%); width: calc(var(--w) * 1%); background: repeating-linear-gradient(135deg, color-mix(in oklch, var(--dcf-critical-ink) 9%, transparent) 0 2px, transparent 2px 6px); }
  & .hol span { position: absolute; top: 4px; left: 50%; translate: -50% 0; writing-mode: vertical-rl; font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: var(--dcf-critical-faint); }
  & .ctr { position: absolute; top: 0; bottom: 0; left: calc(var(--x) * 1%); width: 0; border-left: 2px dashed var(--dcf-critical-crit); transition: left .7s var(--dcf-critical-spring); }
  & .ctr span { position: absolute; bottom: 6px; left: 6px; padding: 2px 6px; border-radius: 5px; font-size: 10.5px; font-weight: 700; white-space: nowrap; color: var(--dcf-critical-crit); background: var(--dcf-critical-card); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dcf-critical-crit) 40%, transparent); }
  & .xh { position: absolute; top: 0; bottom: 0; width: 0; border-left: 1px solid var(--dcf-critical-ink); opacity: 0; transition: opacity .15s; }
  & .ov.hov .xh { opacity: .5; }
  & .links { position: absolute; left: 0; top: 0; overflow: visible; z-index: 1; pointer-events: none; }
  & .links path { fill: none; stroke: color-mix(in oklch, var(--dcf-critical-ink) 32%, transparent); stroke-width: 1.2; transition: d .7s var(--dcf-critical-spring), stroke .3s, opacity .3s; }
  & .links path.c { stroke: var(--dcf-critical-crit); stroke-width: 1.6; }
  & .links path.ah { fill: color-mix(in oklch, var(--dcf-critical-ink) 40%, transparent); stroke: none; }
  & .links path.ah.c { fill: var(--dcf-critical-crit); }
  & .links path.hi { stroke-width: 2.4; }
  & .links path.dim { opacity: .12; }
  & .links.resizing path { transition: none; }
}
.dcf-critical__row {
  grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; height: var(--dcf-critical-row); cursor: pointer;
  background: var(--dcf-critical-card); box-shadow: inset 0 -1px 0 var(--dcf-critical-hair);
  animation: dcf-critical-fade .5s ease-out backwards; animation-delay: calc(var(--i) * 28ms);
  & .lc { font-size: 12.5px; }
  & .id { font: 700 11.5px var(--dcf-critical-mono); color: var(--dcf-critical-mute); }
  & .nm { font-weight: 560; }
  & .du.chg { color: var(--dcf-critical-crit); font-weight: 700; }
  & .tf.z { color: var(--dcf-critical-crit); font-weight: 700; }
  & .tk { position: relative; grid-column: 5; z-index: 1; }
  & .bar {
    --c: var(--dcf-critical-bar);
    position: absolute; inset: 8px 0; background: var(--c); border-radius: 3px;
    clip-path: inset(0 calc(100% - var(--e) * 1%) 0 calc(var(--s) * 1%) round 3px);
    transition: clip-path .7s var(--dcf-critical-spring), background-color .4s;
  }
  & .fl {
    position: absolute; left: 0; right: 0; top: 13px; height: 4px;
    background: repeating-linear-gradient(90deg, var(--dcf-critical-bar) 0 3px, transparent 3px 5px);
    clip-path: inset(0 calc(100% - var(--lf) * 1%) 0 calc(var(--e) * 1%));
    transition: clip-path .7s var(--dcf-critical-spring);
  }
  &.crit .bar { --c: var(--dcf-critical-crit); }
  &.near .bar { --c: var(--dcf-critical-near); }
  &:hover { background: color-mix(in oklch, var(--dcf-critical-card) 92%, var(--dcf-critical-ink)); }
  &[aria-selected="true"] { background: color-mix(in oklch, var(--dcf-critical-crit) 8%, var(--dcf-critical-card)); & .lc { box-shadow: inset 3px 0 0 var(--dcf-critical-crit); } & .bar { filter: saturate(1.2) brightness(.95); } }
  & .lc, & .tk { transition: opacity .3s; }
  &.dim .lc, &.dim .tk { opacity: .28; }
  &:focus-visible { outline-offset: -2px; }
}

/* ---------- network */
.dcf-critical__net {
  height: 100%; overflow: auto;
  & svg { display: block; }
  &.fit svg { width: 100%; height: 100%; }
  & .ed { fill: none; stroke: color-mix(in oklch, var(--dcf-critical-ink) 30%, transparent); stroke-width: 1.4; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dcf-critical-draw .9s var(--dcf-critical-out) forwards; animation-delay: calc(200ms + var(--i) * 25ms); }
  & .ed.c { stroke: var(--dcf-critical-crit); stroke-width: 2.6; }
  & .ed.hi { stroke-width: 3.4; }
  & .nd { cursor: pointer; outline: none; }
  &[data-quiet] .nd .in { animation: none; }
  &[data-quiet] .ed { animation: none; stroke-dashoffset: 0; }
  & .nd .in { transform-box: fill-box; transform-origin: center; animation: dcf-critical-pop .6s var(--dcf-critical-spring) both; animation-delay: calc(var(--i) * 35ms); }
  & .nd rect.box { fill: var(--dcf-critical-card); stroke: color-mix(in oklch, var(--dcf-critical-ink) 40%, transparent); stroke-width: 1.2; transition: stroke .3s, fill .3s; }
  & .nd.crit rect.box { stroke: var(--dcf-critical-crit); stroke-width: 2; }
  & .nd.near rect.box { stroke: var(--dcf-critical-near); stroke-width: 2; }
  & .nd .sep { stroke: var(--dcf-critical-line); stroke-width: 1; }
  & .nd text { font: 600 11px var(--dcf-critical-mono); fill: var(--dcf-critical-ink); text-anchor: middle; font-variant-numeric: tabular-nums; }
  & .nd text.nm { font: 650 11.5px system-ui, sans-serif; }
  & .nd text.lab { font: 9px var(--dcf-critical-mono); fill: var(--dcf-critical-faint); }
  & .nd.crit text.tf { fill: var(--dcf-critical-crit); font-weight: 800; }
  & .nd:hover rect.box, & .nd:focus-visible rect.box { fill: color-mix(in oklch, var(--dcf-critical-crit) 6%, var(--dcf-critical-card)); }
  & .nd.sel rect.box { fill: color-mix(in oklch, var(--dcf-critical-crit) 12%, var(--dcf-critical-card)); stroke-width: 3; }
  & .nd:focus-visible rect.box { stroke: var(--dcf-critical-ink); stroke-width: 2.5; }
}

/* ---------- register */
.dcf-critical__reg { height: 100%; overflow: auto; }
.dcf-critical__table {
  width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; padding: 0; text-align: left; background: var(--dcf-critical-card); border-bottom: 1px solid var(--dcf-critical-line); }
  & th button { display: flex; align-items: center; gap: 4px; width: 100%; padding: 11px 10px 9px; font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dcf-critical-faint); white-space: nowrap; }
  & th button:hover, & th[aria-sort="ascending"] button, & th[aria-sort="descending"] button { color: var(--dcf-critical-ink); }
  & th button::after { content: ""; width: 0; height: 0; border: 4px solid transparent; border-top-color: currentColor; margin-top: 4px; opacity: 0; transition: rotate .3s var(--dcf-critical-spring), opacity .2s; }
  & th[aria-sort="ascending"] button::after { opacity: 1; rotate: 180deg; margin-top: -4px; }
  & th[aria-sort="descending"] button::after { opacity: 1; }
  & td { padding: 8px 10px; border-bottom: 1px solid var(--dcf-critical-hair); white-space: nowrap; }
  & td.num { font-family: var(--dcf-critical-mono); font-size: 12px; text-align: right; }
