const RM = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => Array.from((el || root).querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

/* ------------------------------------------------------------------ calendar
   Time on the chart runs in weekdays. Working days skip the Christmas shutdown, so an
   activity that spans it is drawn longer than its duration — exactly as on site. */
const DAY = 86400000, START = Date.UTC(2026, 9, 5), HOL0 = Date.UTC(2026, 11, 21), HOL1 = Date.UTC(2027, 0, 1);
const W = [];
for (let t = START; W.length < 260; t += DAY) { const d = new Date(t).getUTCDay(); if (d !== 0 && d !== 6) W.push(t); }
const WD = []; W.forEach((t, i) => { if (t < HOL0 || t > HOL1) WD.push(i); });
const HW = W.map((t, i) => (t >= HOL0 && t <= HOL1 ? i : -1)).filter((i) => i >= 0);
const fmt = (t, o) => new Date(t).toLocaleDateString('en-GB', Object.assign({ timeZone: 'UTC', day: 'numeric', month: 'short' }, o || {}));
const dStart = (k) => W[WD[k]];           /* calendar date of working day k */
const dFin = (k) => W[WD[k - 1]];         /* an activity with EF = k finishes at the end of working day k-1 */
const CONTRACT = 158;                     /* contract completion: end of working day 157 */
const LD = 6500;                          /* liquidated damages, £ per calendar day */

/* ------------------------------------------------------------------ activities (topological order) */
const ACTS = [
  ['A', 'Site set-up & hoarding', 'Preliminaries', 5, []],
  ['B', 'Bulk excavation & shoring', 'Groundworks', 12, ['A']],
  ['C', 'CFA piling, 64 piles', 'Piling', 10, ['B']],
  ['D', 'Below-ground drainage', 'Groundworks', 8, ['B']],
  ['E', 'Pile caps & ground beams', 'Concrete', 9, ['C']],
  ['F', 'Ground-floor slab', 'Concrete', 6, ['D', 'E']],
  ['G', 'Lift & stair cores', 'Concrete', 15, ['E']],
  ['H', 'Steel frame L1–L3', 'Steelwork', 14, ['F', 'G']],
  ['I', 'Steel frame L4–L6 & roof', 'Steelwork', 12, ['H']],
  ['J', 'Metal deck & topping', 'Concrete', 10, ['I']],
  ['K', 'Roof finishes', 'Roofing', 7, ['I']],
  ['L', 'Façade cassettes', 'Envelope', 18, ['J']],
  ['M', 'MEP first fix', 'MEP', 20, ['J']],
  ['N', 'Lift installation', 'Lifts', 16, ['G', 'J']],
  ['O', 'Drylining & ceilings', 'Interiors', 22, ['M', 'L']],
  ['P', 'MEP second fix', 'MEP', 12, ['O']],
  ['Q', 'Testing & commissioning', 'MEP', 8, ['P', 'N', 'K']],
  ['R', 'Snagging & handover', 'Preliminaries', 5, ['Q']]
].map((r, i) => ({ id: r[0], name: r[1], trade: r[2], d0: r[3], d: r[3], pre: r[4], suc: [], ord: i }));
const A = Object.fromEntries(ACTS.map((a) => [a.id, a]));
ACTS.forEach((a) => a.pre.forEach((p) => A[p].suc.push(a.id)));
const NEAR = 5;

let finish = 0, finish0 = 0;
function cpm() {
  ACTS.forEach((a) => { a.es = a.pre.length ? Math.max(...a.pre.map((p) => A[p].ef)) : 0; a.ef = a.es + a.d; });
  finish = Math.max(...ACTS.map((a) => a.ef));
  for (let i = ACTS.length - 1; i >= 0; i--) {
    const a = ACTS[i];
    a.lf = a.suc.length ? Math.min(...a.suc.map((s) => A[s].ls)) : finish;
    a.ls = a.lf - a.d; a.tf = a.ls - a.es;
    a.ff = (a.suc.length ? Math.min(...a.suc.map((s) => A[s].es)) : finish) - a.ef;
    a.cls = a.tf === 0 ? 'crit' : a.tf <= NEAR ? 'near' : '';
  }
}
cpm(); finish0 = finish;
const rank = {};
ACTS.forEach((a) => { rank[a.id] = a.pre.length ? Math.max(...a.pre.map((p) => rank[p] + 1)) : 0; });

/* ------------------------------------------------------------------ state */
let view = 'gantt', filter = 'all', scaleG = 'fit', scaleN = 'zoom', sel = 'L', sortKey = 'ord', sortDir = 1;
const gantt = $('[data-gantt]'), net = $('[data-net]'), insp = $('[data-insp]'), tip = $('[data-tip]'), toastEl = $('[data-toast]');
const span = () => Math.max(WD[finish - 1] + 1, WD[CONTRACT - 1] + 1) + 6;
let N = span();
const pc = (wk) => (wk / N * 100).toFixed(3);
const visible = (a) => filter === 'all' || (filter === 'crit' ? a.tf === 0 : a.tf <= NEAR);

/* ------------------------------------------------------------------ gantt */
function buildGantt() {
  N = span();
  gantt.style.setProperty('--n', N);
  let h = '<div class="g"><div class="hd"><div class="lc"><span>ID</span><span>Activity</span><span>Dur</span><span>TF</span></div><div class="th" data-th></div></div><div class="bd" data-bd>';
  h += '<div class="ov" data-ov style="grid-row:1 / span ' + ACTS.length + '"><div class="hol" data-hol></div><div class="ctr" data-ctr><span>Contract completion</span></div><div class="xh" data-xh></div><svg class="links" data-links aria-hidden="true"></svg></div>';
  ACTS.forEach((a, i) => {
    h += '<div class="dcf-critical__row" role="row" tabindex="-1" data-a="' + a.id + '" style="--i:' + i + ';grid-row:' + (i + 1) + '" aria-selected="false">' +
      '<div class="lc" role="presentation"><span class="id" role="gridcell">' + a.id + '</span><span class="nm" role="gridcell">' + esc(a.name) + '</span><span class="du" role="gridcell"></span><span class="tf" role="gridcell"></span></div>' +
      '<div class="tk" role="gridcell"><i class="fl"></i><i class="bar"></i></div></div>';
  });
  h += '</div></div>';
  gantt.innerHTML = h;
  gantt.querySelector('.g').setAttribute('role', 'grid');
  gantt.querySelector('.g').setAttribute('aria-label', 'Activities on a working-day timeline');
  paintAxis(); paintGantt(true);
}
function paintAxis() {
  N = span(); gantt.style.setProperty('--n', N);
  let th = '', lastM = -1;
  for (let i = 0; i < N; i++) {
    const d = new Date(W[i]);
    if (d.getUTCMonth() !== lastM) { lastM = d.getUTCMonth(); th += '<span class="mo" style="left:' + pc(i) + '%">' + fmt(W[i], { day: undefined, month: 'short', year: d.getUTCMonth() === 0 || i === 0 ? '2-digit' : undefined }) + '</span>'; }
    else if (i % 5 === 0 && (scaleG === 'zoom' || i % 10 === 0)) th += '<span class="wk" style="left:' + pc(i) + '%">' + d.getUTCDate() + '</span>';
  }
  $('[data-th]', gantt).innerHTML = th;
  const hol = $('[data-hol]', gantt);
  hol.style.setProperty('--a', pc(HW[0])); hol.style.setProperty('--w', pc(HW.length)); hol.innerHTML = '<span>Shutdown</span>';
}
function paintGantt(first) {
  const n0 = N; paintAxis();
  $('[data-ctr]', gantt).style.setProperty('--x', pc(WD[CONTRACT - 1] + 1));
  ACTS.forEach((a) => {
    const r = gantt.querySelector('[data-a="' + a.id + '"]');
    r.className = 'dcf-critical__row ' + a.cls + (visible(a) ? '' : ' dim');
    r.setAttribute('aria-selected', a.id === sel);
    r.tabIndex = a.id === sel ? 0 : -1;
    const du = r.querySelector('.du'); du.textContent = a.d + 'd'; du.classList.toggle('chg', a.d !== a.d0);
    const tf = r.querySelector('.tf'); tf.textContent = a.tf; tf.classList.toggle('z', a.tf === 0);
    const bar = r.querySelector('.bar'), fl = r.querySelector('.fl');
    const s = WD[a.es], e = WD[a.ef - 1] + 1, lf = WD[a.lf - 1] + 1;
    if (first && !RM) { bar.style.setProperty('--s', pc(s)); bar.style.setProperty('--e', pc(s)); fl.style.setProperty('--e', pc(e)); fl.style.setProperty('--lf', pc(e)); }
    const go = () => { bar.style.setProperty('--s', pc(s)); bar.style.setProperty('--e', pc(e)); fl.style.setProperty('--e', pc(e)); fl.style.setProperty('--lf', pc(lf)); };
    if (first && !RM) setTimeout(() => { if (root.isConnected) go(); }, 160 + a.ord * 40); else go();
  });
