}
function drawLinks(first) {
  const svg = $('[data-links]', gantt), ov = $('[data-ov]', gantt); if (!svg || !ov) return;
  const w = ov.clientWidth, rh = ov.clientHeight / ACTS.length;
  if (!w || !rh) return;
  svg.setAttribute('width', w); svg.setAttribute('height', ov.clientHeight);
  const x = (wk) => wk / N * w;
  if (!svg.childElementCount) {
    let s = '';
    ACTS.forEach((a) => a.pre.forEach((p) => { s += '<path class="ln" data-l="' + p + '>' + a.id + '"/><path class="ah" data-h="' + p + '>' + a.id + '"/>'; }));
    svg.innerHTML = s;
  }
  ACTS.forEach((a) => a.pre.forEach((pid) => {
    const p = A[pid], xs = x(WD[a.es]), xe = x(WD[p.ef - 1] + 1), yp = (p.ord + .5) * rh, ys = a.ord * rh + 7;
    const d = 'M' + xe.toFixed(1) + ' ' + yp.toFixed(1) + 'H' + Math.max(xe, xs).toFixed(1) + 'V' + (ys - 4).toFixed(1);
    const ah = 'M' + (xs - 3.5).toFixed(1) + ' ' + (ys - 5).toFixed(1) + 'L' + (xs + 3.5).toFixed(1) + ' ' + (ys - 5).toFixed(1) + 'L' + xs.toFixed(1) + ' ' + (ys + .5).toFixed(1) + 'Z';
    const crit = p.tf === 0 && a.tf === 0 && p.ef === a.es;
    const hi = sel === a.id || sel === p.id, dim = !(visible(a) && visible(p));
    [[svg.querySelector('[data-l="' + pid + '>' + a.id + '"]'), d], [svg.querySelector('[data-h="' + pid + '>' + a.id + '"]'), ah]].forEach(([el, dd], k) => {
      el.setAttribute('class', (k ? 'ah' : 'ln') + (crit ? ' c' : '') + (hi && !k ? ' hi' : '') + (dim ? ' dim' : ''));
      if (first || RM) { el.style.transition = 'none'; el.style.d = 'path("' + dd + '")'; el.setAttribute('d', dd); requestAnimationFrame(() => { if (!root.isConnected) return; el.style.transition = ''; }); }
      else { el.style.d = 'path("' + dd + '")'; el.setAttribute('d', dd); }
    });
  }));
  if (first && !RM) { svg.style.opacity = 0; svg.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 500, delay: 900, fill: 'forwards', easing: 'ease-out' }); }
}

/* ------------------------------------------------------------------ network */
const NW = 150, NH = 78, GX = 40, GY = 26;
function buildNet(quiet) {
  net.toggleAttribute('data-quiet', !!quiet);
  const cols = {}; ACTS.forEach((a) => { (cols[rank[a.id]] = cols[rank[a.id]] || []).push(a); });
  const maxR = Math.max(...Object.values(cols).map((c) => c.length));
  const H = maxR * (NH + GY) - GY + 40, Wd = (Object.keys(cols).length) * (NW + GX) - GX + 40;
  const pos = {};
  Object.entries(cols).forEach(([r, list]) => { const off = (H - (list.length * (NH + GY) - GY)) / 2; list.forEach((a, i) => { pos[a.id] = [20 + r * (NW + GX), off + i * (NH + GY)]; }); });
  let s = '<svg viewBox="0 0 ' + Wd + ' ' + H + '" width="' + Wd + '" height="' + H + '" role="group" aria-label="Activity-on-node network">';
  let k = 0;
  ACTS.forEach((a) => a.pre.forEach((p) => {
    const [x1, y1] = pos[p], [x2, y2] = pos[a.id], ax = x1 + NW, ay = y1 + NH / 2, bx = x2, by = y2 + NH / 2, mx = (ax + bx) / 2;
    const crit = A[p].tf === 0 && a.tf === 0 && A[p].ef === a.es, hi = sel === a.id || sel === p;
    s += '<path class="ed' + (crit ? ' c' : '') + (hi ? ' hi' : '') + '" pathLength="1" style="--i:' + (k++) + '" d="M' + ax + ' ' + ay + 'C' + mx + ' ' + ay + ' ' + mx + ' ' + by + ' ' + (bx - 2) + ' ' + by + '"/>';
  }));
