    const [x, y] = pos[a.id], c3 = NW / 3, nmax = 19;
    const nm = a.name.length > nmax ? a.name.slice(0, nmax - 1) + '…' : a.name;
    s += '<g class="nd ' + a.cls + (sel === a.id ? ' sel' : '') + '" data-a="' + a.id + '" role="button" tabindex="0" aria-label="' + esc(a.id + ' ' + a.name + ', ' + a.d + ' days, total float ' + a.tf) + '" transform="translate(' + x + ' ' + y + ')" opacity="' + (visible(a) ? 1 : .3) + '">' +
      '<g class="in" style="--i:' + a.ord + '"><rect class="box" width="' + NW + '" height="' + NH + '" rx="6"/>' +
      '<path class="sep" d="M0 22H' + NW + 'M0 56H' + NW + 'M' + c3 + ' 0V22M' + 2 * c3 + ' 0V22M' + c3 + ' 56V' + NH + 'M' + 2 * c3 + ' 56V' + NH + '"/>' +
      '<text x="' + c3 / 2 + '" y="15">' + a.es + '</text><text x="' + 1.5 * c3 + '" y="15">' + a.d + 'd</text><text x="' + 2.5 * c3 + '" y="15">' + a.ef + '</text>' +
      '<text class="nm" x="' + NW / 2 + '" y="36">' + a.id + ' · ' + esc(nm) + '</text><text class="lab" x="' + NW / 2 + '" y="50">' + esc(a.trade) + '</text>' +
      '<text x="' + c3 / 2 + '" y="71">' + a.ls + '</text><text class="tf" x="' + 1.5 * c3 + '" y="71">TF ' + a.tf + '</text><text x="' + 2.5 * c3 + '" y="71">' + a.lf + '</text></g></g>';
  });
