}

/* ------------------------------------------------------------------ register */
function buildReg() {
  const rows = ACTS.slice().sort((a, b) => { const x = a[sortKey], y = b[sortKey]; return (x > y ? 1 : x < y ? -1 : a.ord - b.ord) * sortDir; });
  $('[data-reg]').innerHTML = rows.map((a) => '<tr tabindex="' + (a.id === sel ? 0 : -1) + '" data-a="' + a.id + '" class="' + a.cls + '" aria-selected="' + (a.id === sel) + '">' +
    '<td class="id">' + a.id + '</td><td>' + esc(a.name) + '</td><td class="num">' + a.d + 'd</td><td class="num">' + fmt(dStart(a.es), { weekday: 'short' }) + '</td><td class="num">' + fmt(dFin(a.ef), { weekday: 'short' }) + '</td>' +
    '<td class="num">' + fmt(dFin(a.lf), { weekday: 'short' }) + '</td><td class="num tf">' + a.tf + 'd</td><td class="num">' + a.ff + 'd</td></tr>').join('');
  $$('[data-sorthead] th').forEach((th) => { const k = th.querySelector('button').dataset.sort; th.setAttribute('aria-sort', k === sortKey ? (sortDir > 0 ? 'ascending' : 'descending') : 'none'); });
}

/* ------------------------------------------------------------------ KPIs + inspector */
const prevK = {};
function renderKpis() {
  const fin = dFin(finish), con = dFin(CONTRACT), lateDays = Math.round((fin - con) / DAY), slip = finish - finish0;
  const buf = WD[CONTRACT - 1] - WD[finish - 1];
  const crit = ACTS.filter((a) => a.tf === 0).length;
  const k = [
    ['fin', 'Handover', fmt(fin, { weekday: 'short', year: 'numeric' }) + (slip ? ' <small class="' + (slip > 0 ? 'late' : 'early') + '">' + (slip > 0 ? '+' : '−') + Math.abs(slip) + ' wd</small>' : ''), ''],
    ['buf', 'Float to contract', (buf >= 0 ? buf + ' wd' : '−' + -buf + ' wd'), buf < 0 ? 'bad' : ''],
    ['crit', 'Critical', crit + ' / ' + ACTS.length, ''],
    ['ld', 'LD exposure', lateDays > 0 ? '£' + (lateDays * LD).toLocaleString('en-GB') : '£0', lateDays > 0 ? 'bad' : '']
  ];
  const dl = $('[data-kpis]');
  if (!dl.children.length) dl.innerHTML = k.map((x, i) => '<div style="--i:' + i + '"><dt>' + x[1] + '</dt><dd data-k="' + x[0] + '"></dd></div>').join('');
  k.forEach((x) => {
    const dd = dl.querySelector('[data-k="' + x[0] + '"]');
    if (dd.innerHTML !== x[2]) { dd.innerHTML = x[2]; if (prevK[x[0]] !== undefined && !RM) { dd.classList.remove('flash'); void dd.offsetWidth; dd.classList.add('flash'); } }
    dd.className = x[3] + (dd.classList.contains('flash') ? ' flash' : '');
    prevK[x[0]] = x[2];
  });
}
const changed = () => ACTS.filter((a) => a.d !== a.d0);
function renderInsp(focusKey) {
  const a = A[sel];
  const why = a.tf === 0 ? 'On the <b>critical path</b>: every working day added here moves handover by a day.'
    : 'Has <b>' + a.tf + ' working day' + (a.tf === 1 ? '' : 's') + '</b> of total float — it can slip that far before handover moves' + (a.ff < a.tf ? ', but only <b>' + a.ff + 'd</b> before it delays ' + a.suc.join(', ') + '.' : '.');
  const chips = (ids) => ids.length ? ids.map((id) => '<button type="button" data-pick="' + id + '" class="' + (A[id].tf === 0 ? 'crit' : '') + '" title="' + esc(A[id].name) + '">' + id + ' · ' + esc(A[id].name) + '</button>').join('') : '<em>none</em>';
  const ch = changed();
  insp.innerHTML = '<span class="badge ' + a.cls + '">' + a.id + ' · ' + (a.tf === 0 ? 'Critical' : a.tf <= NEAR ? 'Near-critical' : 'Float ' + a.tf + 'd') + '</span>' +
    '<h3>' + esc(a.name) + '</h3><p class="sub">' + esc(a.trade) + '</p>' +
    '<div class="step" role="group" aria-label="Duration"><button type="button" data-dur="-1" aria-label="One day shorter"' + (a.d <= 1 ? ' aria-disabled="true" title="An activity needs at least one day"' : '') + '><svg class="dcf-critical__ic" viewBox="0 0 24 24"><path d="M6 12h12"/></svg></button>' +
    '<output aria-live="polite">' + a.d + ' d<small>' + (a.d === a.d0 ? 'baseline duration' : 'baseline ' + a.d0 + ' d (' + (a.d > a.d0 ? '+' : '') + (a.d - a.d0) + ')') + '</small></output>' +
    '<button type="button" data-dur="1" aria-label="One day longer"' + (a.d >= a.d0 * 3 ? ' aria-disabled="true" title="Capped at three times the baseline"' : '') + '><svg class="dcf-critical__ic" viewBox="0 0 24 24"><path d="M6 12h12M12 6v12"/></svg></button></div>' +
    '<p class="why">' + why + '</p>' +
    '<dl><div><dt>Early start</dt><dd>' + fmt(dStart(a.es), { weekday: 'short' }) + '</dd></div><div><dt>Early finish</dt><dd>' + fmt(dFin(a.ef), { weekday: 'short' }) + '</dd></div>' +
    '<div><dt>Late start</dt><dd>' + fmt(dStart(a.ls), { weekday: 'short' }) + '</dd></div><div><dt>Late finish</dt><dd>' + fmt(dFin(a.lf), { weekday: 'short' }) + '</dd></div>' +
    '<div><dt>Total float</dt><dd class="' + (a.tf ? '' : 'z') + '">' + a.tf + ' d</dd></div><div><dt>Free float</dt><dd>' + a.ff + ' d</dd></div></dl>' +
    '<h4>Predecessors</h4><div class="chips">' + chips(a.pre) + '</div><h4>Successors</h4><div class="chips">' + chips(a.suc) + '</div>' +
    '<h4>What-if changes</h4>' + (ch.length ? '<ul class="log">' + ch.map((c) => '<li><span>' + c.id + ' ' + esc(c.name) + '</span><b>' + (c.d > c.d0 ? '+' : '') + (c.d - c.d0) + 'd</b></li>').join('') + '</ul>' : '<p class="sub">None yet — step a duration to test the schedule.</p>') +
    '<button type="button" class="reset" data-reset' + (ch.length ? '' : ' aria-disabled="true" title="No durations have been changed"') + '>Reset to baseline</button>';
  if (focusKey) { const b = insp.querySelector(focusKey); if (b) b.focus(); }
}

/* ------------------------------------------------------------------ actions */
function toast(m) { toastEl.textContent = m; toastEl.classList.add('on'); clearTimeout(toast.t); toast.t = setTimeout(() => { if (root.isConnected) toastEl.classList.remove('on'); }, 3600); }
function refresh(focusKey) {
  if (view === 'gantt') paintGantt(false);
  if (view === 'net') buildNet(true);
  if (view === 'reg') buildReg();
  renderKpis(); renderInsp(focusKey);
}
function select(id, focus) {
  sel = id; refresh();
  if (focus) {
    const el = view === 'gantt' ? gantt.querySelector('[data-a="' + id + '"]') : view === 'net' ? net.querySelector('[data-a="' + id + '"]') : $('[data-reg] [data-a="' + id + '"]');
    if (el) { el.focus({ preventScroll: true }); el.scrollIntoView({ block: 'nearest', inline: 'nearest' }); }
  }
}
function step(delta) {
  const a = A[sel], beforeFin = finish, wasCrit = a.tf === 0;
  const nd = Math.max(1, Math.min(a.d0 * 3, a.d + delta)); if (nd === a.d) return;
  a.d = nd; cpm(); refresh('[data-dur="' + delta + '"]');
  const moved = finish - beforeFin;
  if (!wasCrit && a.tf === 0 && delta > 0) toast(a.id + ' ' + a.name + ' has used up its float and is now critical' + (moved ? ' — handover moves ' + moved + ' wd to ' + fmt(dFin(finish), { weekday: 'short' }) : '') + '.');
  else if (moved) toast('Handover ' + (moved > 0 ? 'slips ' : 'improves ') + Math.abs(moved) + ' wd to ' + fmt(dFin(finish), { weekday: 'short', year: 'numeric' }) + '.');
  else if (delta > 0) toast(a.id + ' absorbed the day in its float — ' + a.tf + 'd left.');
}
function go(v) {
  view = v; tip.classList.remove('on');
  $$('[data-go]').forEach((b) => { if (b.dataset.go === v) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $$('.dcf-critical__view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  const sc = $('[data-scale]');
  if (v === 'reg') { sc.setAttribute('aria-disabled', 'true'); sc.title = 'Scale applies to the Gantt and network views'; } else { sc.removeAttribute('aria-disabled'); sc.removeAttribute('title'); }
  const cur = v === 'net' ? scaleN : scaleG;
  $$('button', sc).forEach((b) => { if (v === 'reg') b.setAttribute('aria-disabled', 'true'); else b.removeAttribute('aria-disabled'); b.setAttribute('aria-checked', b.dataset.v === cur); });
  if (v === 'gantt') { paintGantt(false); }
  if (v === 'net') buildNet();
  if (v === 'reg') buildReg();
}
function radio(group, b) { $$('button', group).forEach((x) => x.setAttribute('aria-checked', x === b)); }

root.addEventListener('click', (e) => {
  const t = e.target;
  const nv = t.closest('[data-go]'); if (nv) { go(nv.dataset.go); return; }
  const fb = t.closest('[data-filter] button');
  if (fb) { filter = fb.dataset.v; radio(fb.parentElement, fb); refresh(); return; }
  const sb = t.closest('[data-scale] button');
  if (sb) {
    if (sb.getAttribute('aria-disabled') === 'true') { toast('Scale applies to the Gantt and network views.'); return; }
    radio(sb.parentElement, sb);
    if (view === 'net') { scaleN = sb.dataset.v; buildNet(true); toast(scaleN === 'fit' ? 'Network scaled to fit the panel.' : 'Network at full size — scroll to pan.'); }
    if (view === 'gantt') { scaleG = sb.dataset.v; gantt.classList.toggle('zoom', scaleG === 'zoom'); paintAxis(); requestAnimationFrame(() => { if (!root.isConnected) return; drawLinks(true); if (scaleG === 'zoom') gantt.scrollLeft = Math.max(0, WD[A[sel].es] * 15 - 120); }); }
    return;
  }
  const row = t.closest('.dcf-critical__row, [data-reg] tr, .nd'); if (row) { select(row.dataset.a, true); return; }
  const pk = t.closest('[data-pick]'); if (pk) { select(pk.dataset.pick, false); const b = insp.querySelector('.step button'); if (b) b.focus(); return; }
  const du = t.closest('[data-dur]');
  if (du) { if (du.getAttribute('aria-disabled') === 'true') { toast(du.title); return; } step(+du.dataset.dur); return; }
  if (t.closest('[data-reset]')) {
    const rb = t.closest('[data-reset]'); if (rb.getAttribute('aria-disabled') === 'true') { toast('Nothing to reset — the schedule matches baseline rev. C.'); return; }
    ACTS.forEach((a) => { a.d = a.d0; }); cpm(); refresh('[data-reset]'); toast('Schedule reset to baseline rev. C.'); return;
  }
  const so = t.closest('[data-sort]');
  if (so) { const k = so.dataset.sort; if (k === sortKey) sortDir = -sortDir; else { sortKey = k; sortDir = 1; } buildReg(); }
});
root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (e.key === 'Escape') { tip.classList.remove('on'); toastEl.classList.remove('on'); return; }
  const isRow = t.matches('.dcf-critical__row, [data-reg] tr, .nd');
  if (isRow && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); const b = insp.querySelector('.step button[data-dur="1"]'); if (b) b.focus(); return; }
  if (isRow && /^Arrow(Up|Down|Left|Right)$/.test(e.key)) {
    e.preventDefault();
    let list = view === 'reg' ? $$('[data-reg] tr').map((r) => r.dataset.a) : ACTS.map((a) => a.id);
    const i = list.indexOf(t.dataset.a), dir = (e.key === 'ArrowDown' || e.key === 'ArrowRight') ? 1 : -1;
    const n = list[Math.max(0, Math.min(list.length - 1, i + dir))]; if (n !== sel) select(n, true);
    return;
  }
  if (t.closest('[role="radiogroup"]') && /^Arrow(Left|Right)$/.test(e.key)) {
    e.preventDefault(); const bs = $$('button', t.closest('[role="radiogroup"]')), i = bs.indexOf(t), n = bs[(i + (e.key === 'ArrowRight' ? 1 : -1) + bs.length) % bs.length]; n.click(); n.focus();
  }
  if (t.closest('.dcf-critical__nav') && /^Arrow(Up|Down)$/.test(e.key)) { e.preventDefault(); const bs = $$('[data-go]'), i = bs.indexOf(t); bs[(i + (e.key === 'ArrowDown' ? 1 : -1) + bs.length) % bs.length].focus(); }
});

/* crosshair + tooltips */
function showTip(html, cx, cy) {
  const r = root.getBoundingClientRect(); tip.innerHTML = html; tip.classList.add('on');
  let x = cx - r.left + 14, y = cy - r.top + 16; const w = tip.offsetWidth, h = tip.offsetHeight;
  if (x + w > r.width - 8) x = cx - r.left - w - 14; if (y + h > r.height - 8) y = cy - r.top - h - 12;
  tip.style.transform = 'translate(' + Math.max(6, x) + 'px,' + Math.max(6, y) + 'px)';
}
root.addEventListener('pointermove', (e) => {
  const ov = $('[data-ov]', gantt), tk = e.target.closest('.tk'), nd = e.target.closest('.nd');
  if (view === 'gantt' && ov && tk) {
    const r = ov.getBoundingClientRect(), f = (e.clientX - r.left) / r.width, wk = Math.max(0, Math.min(N - 1, Math.floor(f * N)));
    ov.classList.add('hov'); $('[data-xh]', gantt).style.transform = 'translateX(' + (e.clientX - r.left).toFixed(1) + 'px)';
    const a = A[tk.parentElement.dataset.a], on = wk >= WD[a.es] && wk <= WD[a.ef - 1], hol = HW.includes(wk);
    showTip('<b>' + fmt(W[wk], { weekday: 'long', year: 'numeric' }) + '</b><span>' + (hol ? 'Christmas shutdown' : 'Working day ' + (WD.indexOf(wk) + 1)) + '</span><span>' + a.id + ' ' + esc(a.name) + ': ' + fmt(dStart(a.es)) + ' → ' + fmt(dFin(a.ef)) + ' · ' + a.d + 'd · TF ' + a.tf + 'd' + (on ? '' : '') + '</span>', e.clientX, e.clientY);
    return;
  }
  if (ov) ov.classList.remove('hov');
  if (nd) { const a = A[nd.dataset.a]; showTip('<b>' + a.id + ' ' + esc(a.name) + '</b><span>' + fmt(dStart(a.es), { weekday: 'short' }) + ' → ' + fmt(dFin(a.ef), { weekday: 'short' }) + ' · ' + a.d + 'd</span><span>Total float ' + a.tf + 'd · free float ' + a.ff + 'd</span>', e.clientX, e.clientY); return; }
  tip.classList.remove('on');
});
root.addEventListener('pointerleave', () => { tip.classList.remove('on'); const ov = $('[data-ov]', gantt); if (ov) ov.classList.remove('hov'); });

/* ------------------------------------------------------------------ mount */
buildGantt(); renderKpis(); renderInsp();
if (window.ResizeObserver) {
  let last = '', tm = 0;
  const ro = new ResizeObserver(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    const ov = $('[data-ov]', gantt); if (!ov || view !== 'gantt') return;
    const k = ov.clientWidth + 'x' + ov.clientHeight; if (k === last) return; last = k;
    const svg = $('[data-links]', gantt); svg.classList.add('resizing'); drawLinks(false);
    clearTimeout(tm); tm = setTimeout(() => { if (root.isConnected) svg.classList.remove('resizing'); }, 120);
  });
  ro.observe(gantt);
}

css:
.dcf-fleet {
  --dcf-fleet-bg: oklch(0.955 0.006 85);
  --dcf-fleet-ink: oklch(0.25 0.012 75);
  --dcf-fleet-acc: oklch(0.85 0.165 89);
  --dcf-fleet-idle: oklch(0.66 0.15 47);
  --dcf-fleet-down: oklch(0.56 0.19 27);
  --dcf-fleet-card: color-mix(in oklch, var(--dcf-fleet-bg) 35%, white);
  --dcf-fleet-sunk: color-mix(in oklch, var(--dcf-fleet-bg) 92%, var(--dcf-fleet-ink));
  --dcf-fleet-line: color-mix(in oklch, var(--dcf-fleet-ink) 13%, transparent);
  --dcf-fleet-hair: color-mix(in oklch, var(--dcf-fleet-ink) 7%, transparent);
  --dcf-fleet-soft: color-mix(in oklch, var(--dcf-fleet-ink) 5%, transparent);
  --dcf-fleet-mute: color-mix(in oklch, var(--dcf-fleet-ink) 64%, var(--dcf-fleet-bg));
  --dcf-fleet-faint: color-mix(in oklch, var(--dcf-fleet-ink) 42%, var(--dcf-fleet-bg));
  --dcf-fleet-night: color-mix(in oklch, var(--dcf-fleet-ink) 5%, transparent);
  --dcf-fleet-accd: color-mix(in oklch, var(--dcf-fleet-acc) 62%, var(--dcf-fleet-ink));
  --dcf-fleet-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dcf-fleet-out: cubic-bezier(.22, 1, .36, 1);
  --dcf-fleet-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.077 24.5%, 1.064 27.1%, 1.002 33.9%, .987 37.7%, .983 41.4%, .995 52.6%, 1.001 63.2%, 1);
  --dcf-fleet-lab: 206px;
  --dcf-fleet-rh: 38px;
  width: 100%;
  height: var(--dcf-fleet-h, 680px);
  container-type: inline-size;
  container-name: dcf-fleet;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  border-radius: 18px;
  background: var(--dcf-fleet-bg);
  color: var(--dcf-fleet-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dcf-fleet-accd);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dcf-fleet-ink) 22%, transparent) transparent;
  box-shadow: inset 0 0 0 1px var(--dcf-fleet-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, h4, p, ul, ol, dl, dd) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dcf-fleet-ink); outline-offset: 2px; border-radius: 8px; }
  & [hidden] { display: none !important; }
}
.dcf-fleet__ic { width: 17px; height: 17px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
.dcf-fleet__cap { font-size: 10.5px; font-weight: 680; letter-spacing: .13em; text-transform: uppercase; color: var(--dcf-fleet-faint); }

.dcf-fleet__top {
  display: flex; align-items: center; gap: 10px 18px; flex-wrap: wrap; padding: 14px 18px 12px;
  border-bottom: 1px solid var(--dcf-fleet-line); background: var(--dcf-fleet-card);
}
.dcf-fleet__brand {
  display: flex; align-items: center; gap: 10px; margin-right: auto; min-width: 0;
  & svg { width: 34px; height: 34px; flex: none; padding: 6px; border-radius: 9px; background: var(--dcf-fleet-acc); fill: none; stroke: var(--dcf-fleet-ink); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 780; letter-spacing: -.025em; line-height: 1.2; text-wrap: balance; }
  & small { display: block; font-size: 11.5px; color: var(--dcf-fleet-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dcf-fleet__tabs {
  display: flex; gap: 2px; padding: 3px; border-radius: 11px; background: var(--dcf-fleet-sunk);
  & button { display: inline-flex; align-items: center; gap: 7px; padding: 6px 12px; border-radius: 8px; font-weight: 620; color: var(--dcf-fleet-mute); white-space: nowrap; transition: color .2s, background-color .2s, box-shadow .2s; }
  & button:hover { color: var(--dcf-fleet-ink); }
  & button[aria-selected="true"] { background: var(--dcf-fleet-card); color: var(--dcf-fleet-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dcf-fleet-ink) 18%, transparent), inset 0 0 0 1px var(--dcf-fleet-hair); }
  & button[aria-selected="true"] .dcf-fleet__ic { color: var(--dcf-fleet-idle); }
}
.dcf-fleet__seg, .dcf-fleet__sort, .dcf-fleet__chips {
  display: flex; align-items: center; gap: 2px;
  & button { padding: 5px 11px; border-radius: 8px; font-size: 12px; font-weight: 620; color: var(--dcf-fleet-mute); white-space: nowrap; transition: color .2s, background-color .2s; }
  & button:hover { color: var(--dcf-fleet-ink); background: var(--dcf-fleet-soft); }
  & button[aria-checked="true"] { background: var(--dcf-fleet-ink); color: var(--dcf-fleet-bg); }
  &[aria-disabled="true"] { opacity: .45; & button { cursor: not-allowed; } }
}
.dcf-fleet__seg { padding: 3px; border-radius: 11px; box-shadow: inset 0 0 0 1px var(--dcf-fleet-line); }
.dcf-fleet__sort .dcf-fleet__cap { margin-right: 6px; }
.dcf-fleet__chips button { & em { font-style: normal; margin-left: 5px; font: 600 10.5px var(--dcf-fleet-mono); opacity: .7; } }

.dcf-fleet__kpis {
  display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0; margin: 12px 18px 0;
  border-radius: 14px; background: var(--dcf-fleet-card); box-shadow: inset 0 0 0 1px var(--dcf-fleet-line);
  & > div { position: relative; padding: 10px 14px 11px; min-width: 0; animation: dcf-fleet-rise .6s var(--dcf-fleet-out) both; animation-delay: calc(var(--i) * 55ms); }
  & > div + div::before { content: ""; position: absolute; left: 0; top: 12px; bottom: 12px; width: 1px; background: var(--dcf-fleet-line); }
  & dt { font-size: 10.5px; font-weight: 680; letter-spacing: .09em; text-transform: uppercase; color: var(--dcf-fleet-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font: 700 clamp(18px, 2.1cqi, 24px)/1.15 var(--dcf-fleet-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & dd small { display: block; font: 500 11.5px/1.35 system-ui, sans-serif; letter-spacing: 0; color: var(--dcf-fleet-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .hot dd b { color: var(--dcf-fleet-down); }
  & .meter { position: absolute; left: 14px; right: 14px; bottom: 0; height: 3px; border-radius: 3px 3px 0 0; background: var(--dcf-fleet-hair); overflow: hidden; }
  & .meter i { display: block; height: 100%; background: var(--dcf-fleet-acc); transform-origin: left; transform: scaleX(var(--p, 0)); transition: transform .9s var(--dcf-fleet-out); }
}

.dcf-fleet__scrollall { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dcf-fleet__body {
  display: grid; grid-template-columns: minmax(0, 1fr) 292px; gap: 12px; min-height: 0; padding: 12px 18px 16px;
}
.dcf-fleet__main {
