  --dcf-safety-sunk: color-mix(in oklch, var(--dcf-safety-bg) 93%, var(--dcf-safety-ink));
  --dcf-safety-line: color-mix(in oklch, var(--dcf-safety-ink) 13%, transparent);
  --dcf-safety-hair: color-mix(in oklch, var(--dcf-safety-ink) 7%, transparent);
  --dcf-safety-soft: color-mix(in oklch, var(--dcf-safety-ink) 5%, transparent);
  --dcf-safety-mute: color-mix(in oklch, var(--dcf-safety-ink) 64%, var(--dcf-safety-bg));
  --dcf-safety-faint: color-mix(in oklch, var(--dcf-safety-ink) 42%, var(--dcf-safety-bg));
  --dcf-safety-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dcf-safety-out: cubic-bezier(.2, .9, .3, 1);
  --dcf-safety-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.077 24.5%, 1.064 27.1%, 1.002 33.9%, .987 37.7%, .983 41.4%, .995 52.6%, 1.001 63.2%, 1);
  --dcf-safety-cell: 46px;
  width: 100%;
  height: var(--dcf-safety-h, 680px);
  container-type: inline-size;
  container-name: dcf-safety;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  border-radius: 18px;
  background: var(--dcf-safety-bg);
  color: var(--dcf-safety-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dcf-safety-acc);
  scrollbar-width: thin;
