}

.dcf-safety__kpis {
  display: grid; grid-template-columns: 1.35fr repeat(4, minmax(0, 1fr)); gap: 8px; padding: 12px 18px 0;
  & > div { position: relative; padding: 10px 14px; border-radius: 14px; background: var(--dcf-safety-card); box-shadow: inset 0 0 0 1px var(--dcf-safety-hair); min-width: 0; animation: dcf-safety-rise .6s var(--dcf-safety-out) both; animation-delay: calc(var(--i) * 60ms); }
  & dt { font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--dcf-safety-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font: 720 clamp(18px, 2cqi, 23px)/1.2 var(--dcf-safety-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & dd small { display: block; font: 500 11.5px/1.35 system-ui, sans-serif; letter-spacing: 0; color: var(--dcf-safety-mute); overflow: hidden; text-overflow: ellipsis; }
  & .up { color: var(--dcf-safety-lti); } & .down { color: var(--dcf-safety-acc); }
}
.dcf-safety__lti {
  background: var(--dcf-safety-ink) !important; color: var(--dcf-safety-bg);
  & dt { color: color-mix(in oklch, var(--dcf-safety-bg) 60%, transparent) !important; }
  & dd { display: flex; align-items: baseline; gap: 12px; }
  & dd small { color: color-mix(in oklch, var(--dcf-safety-bg) 72%, transparent) !important; white-space: normal; }
}
.dcf-safety__count {
  --dcf-safety-days: 0;
  counter-reset: dcf-safety-d var(--dcf-safety-days);
  font: 800 clamp(30px, 3.6cqi, 40px)/1 var(--dcf-safety-mono); letter-spacing: -.06em; color: var(--dcf-safety-ok);
  transition: --dcf-safety-days 1.6s cubic-bezier(.16, 1, .3, 1);
  &::after { content: counter(dcf-safety-d); }
  &.on { --dcf-safety-days: var(--dcf-safety-target); }
}

.dcf-safety__scroll { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dcf-safety__body { display: grid; grid-template-columns: minmax(0, 1fr) 292px; gap: 12px; min-height: 0; padding: 12px 18px 16px; }
.dcf-safety__main { min-width: 0; min-height: 0; }
.dcf-safety__view { height: 100%; min-height: 0; }
.dcf-safety__cv { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 12px; }
.dcf-safety__card {
  position: relative; min-width: 0; min-height: 0; border-radius: 16px; background: var(--dcf-safety-card); box-shadow: inset 0 0 0 1px var(--dcf-safety-line);
  animation: dcf-safety-rise .7s var(--dcf-safety-out) both; animation-delay: calc(var(--i, 0) * 70ms + 80ms);
}
.dcf-safety__ch {
  display: flex; align-items: baseline; justify-content: space-between; flex-wrap: wrap; gap: 2px 10px; padding: 12px 14px 8px;
  & h3 { font-size: 14px; font-weight: 750; letter-spacing: -.015em; text-wrap: balance; }
  & span { font-size: 11.5px; color: var(--dcf-safety-mute); }
}
.dcf-safety__crosscard { display: flex; flex-direction: column; padding-bottom: 10px; overflow: auto; }
.dcf-safety__cross {
  display: grid; grid-template-columns: repeat(7, var(--dcf-safety-cell)); grid-auto-rows: var(--dcf-safety-cell); gap: 4px; padding: 4px 14px 10px; justify-content: center;
  & button {
    --c: var(--dcf-safety-ok);
    position: relative; display: grid; place-items: center; border-radius: 9px; background: var(--c); color: color-mix(in oklch, var(--c) 25%, black);
    font: 700 clamp(12px, 1.25cqi, 14px) var(--dcf-safety-mono); font-variant-numeric: tabular-nums;
    animation: dcf-safety-pop .55s var(--dcf-safety-spring) both; animation-delay: calc(var(--i) * 14ms);
    transition: transform .25s var(--dcf-safety-spring), box-shadow .2s, filter .2s;
    &:hover { transform: scale(1.08); z-index: 1; box-shadow: 0 6px 14px -6px color-mix(in oklch, var(--dcf-safety-ink) 50%, transparent); }
    &[aria-current="date"] { box-shadow: 0 0 0 2px var(--dcf-safety-card), 0 0 0 4px var(--dcf-safety-ink); z-index: 2; }
    &.fa { --c: var(--dcf-safety-fa); }
    &.rec { --c: var(--dcf-safety-rec); color: white; }
    &.lti { --c: var(--dcf-safety-lti); color: white; }
    &.shut { --c: var(--dcf-safety-sunk); color: var(--dcf-safety-faint); background: repeating-linear-gradient(135deg, var(--dcf-safety-sunk) 0 3px, var(--dcf-safety-card) 3px 6px); }
    &.fut { --c: transparent; color: var(--dcf-safety-faint); box-shadow: inset 0 0 0 1.5px var(--dcf-safety-line); cursor: default; }
    &.fut:hover { transform: none; box-shadow: inset 0 0 0 1.5px var(--dcf-safety-line); }
    &.today { box-shadow: inset 0 0 0 2px var(--dcf-safety-ink); }
    & i { position: absolute; top: 3px; right: 3px; min-width: 14px; height: 14px; padding: 0 3px; border-radius: 7px; font: 700 9px/14px var(--dcf-safety-mono); font-style: normal; color: white; background: var(--dcf-safety-nm); box-shadow: 0 0 0 1.5px var(--dcf-safety-card); }
  }
  &[data-quiet] button { animation: none; }
  & .gap { visibility: hidden; }
}
.dcf-safety__types {
  display: flex; flex-wrap: wrap; justify-content: center; gap: 4px; padding: 2px 10px 0; margin-top: auto;
  & button { display: inline-flex; align-items: center; gap: 6px; padding: 4px 9px 4px 6px; border-radius: 99px; font-size: 11.5px; font-weight: 620; color: var(--dcf-safety-mute); box-shadow: inset 0 0 0 1px var(--dcf-safety-line); transition: background-color .2s, color .2s, opacity .2s; }
  & button i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); transition: transform .3s var(--dcf-safety-spring); }
  & button[aria-pressed="true"] { color: var(--dcf-safety-ink); background: color-mix(in oklch, var(--c) 14%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 55%, transparent); }
  & button[aria-pressed="false"] { opacity: .55; text-decoration: line-through; }
  & button[aria-pressed="false"] i { transform: scale(.5); }
  & .ok { display: inline-flex; align-items: center; gap: 6px; padding: 4px 6px; font-size: 11.5px; color: var(--dcf-safety-mute); }
  & .ok i { width: 10px; height: 10px; border-radius: 3px; background: var(--dcf-safety-ok); }
}

.dcf-safety__trend { display: flex; flex-direction: column; overflow: hidden; }
.dcf-safety__chart {
  flex: 1 1 200px; min-height: 170px; position: relative; padding: 0 8px;
  & svg { position: absolute; inset: 0 8px; width: calc(100% - 16px); height: 100%; overflow: visible; }
  & .gl { stroke: var(--dcf-safety-hair); }
  & .ax { font: 10px var(--dcf-safety-mono); fill: var(--dcf-safety-faint); }
  & .ax.r { fill: color-mix(in oklch, var(--dcf-safety-ink) 60%, var(--dcf-safety-bg)); }
  & .mo { cursor: pointer; outline: none; }
  & .mo .band { fill: transparent; transition: fill .2s; }
  & .mo:hover .band { fill: var(--dcf-safety-soft); }
  & .mo[aria-current="true"] .band { fill: color-mix(in oklch, var(--dcf-safety-acc) 12%, transparent); }
  & .mo[aria-current="true"] .ml { fill: var(--dcf-safety-ink); font-weight: 800; }
  & .mo:focus-visible .band { stroke: var(--dcf-safety-ink); stroke-width: 1.5; }
  & .ml { font: 600 10.5px var(--dcf-safety-mono); fill: var(--dcf-safety-mute); text-anchor: middle; }
  & .stack { transform-box: fill-box; transform-origin: bottom; animation: dcf-safety-grow .7s var(--dcf-safety-out) both; animation-delay: calc(200ms + var(--i) * 35ms); }
  & .b-nm { fill: color-mix(in oklch, var(--dcf-safety-nm) 70%, var(--dcf-safety-card)); }
  & .b-fa { fill: var(--dcf-safety-fa); } & .b-rec { fill: var(--dcf-safety-rec); } & .b-lti { fill: var(--dcf-safety-lti); }
  & .trir { fill: none; stroke: var(--dcf-safety-ink); stroke-width: 2; stroke-linejoin: round; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dcf-safety-draw 1.2s var(--dcf-safety-out) .5s forwards; }
  & .dot { fill: var(--dcf-safety-card); stroke: var(--dcf-safety-ink); stroke-width: 2; }
  & .xh { stroke: var(--dcf-safety-ink); stroke-dasharray: 3 3; opacity: 0; pointer-events: none; }
  & .xh.on { opacity: .45; }
  &[data-quiet] :is(.stack, .trir) { animation: none; stroke-dashoffset: 0; }
}
.dcf-safety__areas {
  padding: 4px 14px 12px; border-top: 1px solid var(--dcf-safety-hair);
  & h4 { margin: 8px 0 6px; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dcf-safety-faint); display: flex; justify-content: space-between; }
  & h4 span { letter-spacing: 0; text-transform: none; font-weight: 500; }
  & ul { display: grid; gap: 4px; }
  & li { display: grid; grid-template-columns: minmax(90px, 160px) minmax(0, 1fr) 24px; align-items: center; gap: 8px; font-size: 12px; }
  & li > span:first-child { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--dcf-safety-mute); }
  & .bar { display: flex; height: 9px; border-radius: 3px; overflow: hidden; background: var(--dcf-safety-hair); }
  & .bar i { height: 100%; flex: none; width: calc(var(--w) * 1%); background: var(--c); transform-origin: left; animation: dcf-safety-growx .6s var(--dcf-safety-out) both; }
  & b { font: 700 11.5px var(--dcf-safety-mono); text-align: right; }
}

.dcf-safety__logcard { height: 100%; overflow: auto; }
.dcf-safety__table {
  width: 100%; border-collapse: separate; border-spacing: 0; font-variant-numeric: tabular-nums;
  & th { position: sticky; top: 0; z-index: 1; padding: 0; text-align: left; background: var(--dcf-safety-card); border-bottom: 1px solid var(--dcf-safety-line); font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dcf-safety-faint); }
  & th:not(:has(button)) { padding: 11px 10px 9px; }
  & th button { display: flex; align-items: center; gap: 4px; width: 100%; padding: 11px 10px 9px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; }
  & th button:hover, & th[aria-sort="ascending"] button, & th[aria-sort="descending"] button { color: var(--dcf-safety-ink); }
  & th button::after { content: ""; border: 4px solid transparent; border-top-color: currentColor; margin-top: 4px; opacity: 0; transition: rotate .3s var(--dcf-safety-spring), opacity .2s; }
  & th[aria-sort="ascending"] button::after { opacity: 1; rotate: 180deg; margin-top: -4px; }
  & th[aria-sort="descending"] button::after { opacity: 1; }
  & td { padding: 9px 10px; border-bottom: 1px solid var(--dcf-safety-hair); vertical-align: top; font-size: 12.5px; }
  & td.d { white-space: nowrap; font-family: var(--dcf-safety-mono); font-size: 12px; }
  & td.d small { display: block; color: var(--dcf-safety-faint); }
  & td.w { color: var(--dcf-safety-mute); text-wrap: pretty; min-width: 180px; }
  & tbody tr { cursor: pointer; transition: background-color .2s; }
  & tbody tr:hover { background: var(--dcf-safety-soft); }
  & tbody tr[aria-selected="true"] { background: color-mix(in oklch, var(--dcf-safety-acc) 10%, transparent); }
  & tbody tr:focus-visible { outline-offset: -2px; }
}
@supports (animation-timeline: view()) {
  .dcf-safety__table tbody tr { animation: dcf-safety-reveal linear both; animation-timeline: view(); animation-range: entry 0% entry 70%; }
}
.dcf-safety__chip {
  --c: var(--dcf-safety-nm);
  display: inline-flex; align-items: center; gap: 5px; padding: 1px 7px 1px 5px; border-radius: 6px; font-size: 11px; font-weight: 700; white-space: nowrap;
  background: color-mix(in oklch, var(--c) 15%, transparent); color: color-mix(in oklch, var(--c) 60%, var(--dcf-safety-ink));
  & i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  &.fa { --c: var(--dcf-safety-fa); color: color-mix(in oklch, var(--dcf-safety-fa) 35%, var(--dcf-safety-ink)); }
  &.rec { --c: var(--dcf-safety-rec); } &.lti { --c: var(--dcf-safety-lti); } &.uc { --c: color-mix(in oklch, var(--dcf-safety-nm) 60%, var(--dcf-safety-ink)); }
}
.dcf-safety__st { font-size: 11.5px; font-weight: 650; white-space: nowrap; &.open { color: var(--dcf-safety-rec); } &.closed { color: var(--dcf-safety-mute); } }
.dcf-safety__empty { padding: 30px; text-align: center; color: var(--dcf-safety-mute); }

.dcf-safety__side {
  position: relative; min-height: 0; display: flex; flex-direction: column; border-radius: 16px; background: var(--dcf-safety-card); box-shadow: inset 0 0 0 1px var(--dcf-safety-line); overflow: hidden;
  animation: dcf-safety-rise .7s var(--dcf-safety-out) both .25s;
}
.dcf-safety__day {
  flex: 1; min-height: 0; overflow: auto; padding: 14px;
  & .k { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dcf-safety-faint); }
  & h3 { margin: 4px 0 2px; font-size: 18px; font-weight: 780; letter-spacing: -.03em; line-height: 1.15; text-wrap: balance; }
  & .sub { font-size: 12px; color: var(--dcf-safety-mute); font-variant-numeric: tabular-nums; }
  & .back { display: inline-flex; align-items: center; gap: 4px; margin: -4px 0 6px -6px; padding: 3px 8px 3px 4px; border-radius: 7px; font-size: 12px; font-weight: 650; color: var(--dcf-safety-mute); }
  & .back:hover { background: var(--dcf-safety-soft); color: var(--dcf-safety-ink); }
  & .back .dcf-safety__ic { width: 15px; height: 15px; }
  & .evs { display: grid; gap: 8px; margin-top: 12px; }
  & .ev { padding: 10px 11px; border-radius: 12px; background: var(--dcf-safety-bg); box-shadow: inset 0 0 0 1px var(--dcf-safety-hair); animation: dcf-safety-rise .45s var(--dcf-safety-out) both; animation-delay: calc(var(--i) * 50ms); }
  & .ev.hi { box-shadow: inset 0 0 0 2px var(--dcf-safety-ink); }
  & .ev .eh { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
  & .ev .ref { font: 650 11px var(--dcf-safety-mono); color: var(--dcf-safety-faint); }
  & .ev p { margin-top: 6px; font-size: 12.5px; text-wrap: pretty; }
  & .ev .meta { margin-top: 6px; display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 8px; font-size: 11.5px; color: var(--dcf-safety-mute); }
  & .ev .close { padding: 3px 9px; border-radius: 7px; font-size: 11.5px; font-weight: 700; box-shadow: inset 0 0 0 1px var(--dcf-safety-line); transition: background-color .2s; }
  & .ev .close:hover { background: var(--dcf-safety-soft); }
  & .none { margin-top: 14px; padding: 14px; border-radius: 12px; background: color-mix(in oklch, var(--dcf-safety-ok) 14%, var(--dcf-safety-card)); font-size: 12.5px; text-wrap: pretty; }
  & .pyr { display: grid; gap: 3px; margin-top: 14px; justify-items: center; }
  & .pyr div { --c: var(--dcf-safety-nm); display: flex; align-items: center; justify-content: space-between; gap: 8px; height: 30px; padding: 0 12px; width: calc(38% + var(--k) * 15.5%); border-radius: 6px; background: color-mix(in oklch, var(--c) 22%, var(--dcf-safety-card)); box-shadow: inset 3px 0 0 var(--c); font-size: 12px; transform-origin: center; animation: dcf-safety-growx .6s var(--dcf-safety-out) both; animation-delay: calc((3 - var(--k)) * 70ms); }
  & .pyr b { font: 750 14px var(--dcf-safety-mono); }
  & .pyr span { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .pyr .fa { --c: var(--dcf-safety-fa); } & .pyr .rec { --c: var(--dcf-safety-rec); } & .pyr .lti { --c: var(--dcf-safety-lti); }
  & .txt { margin-top: 12px; font-size: 12.5px; color: var(--dcf-safety-mute); text-wrap: pretty; }
  & .txt b { color: var(--dcf-safety-ink); }
  & .open { margin-top: 14px; }
  & .open h4 { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dcf-safety-faint); margin-bottom: 6px; }
  & .open li { display: grid; gap: 1px; padding: 6px 0; border-top: 1px solid var(--dcf-safety-hair); font-size: 12px; }
  & .open li span { font-size: 11.5px; color: var(--dcf-safety-mute); }
  & .open li button { font-weight: 650; text-align: left; text-decoration: underline; text-decoration-color: var(--dcf-safety-line); text-underline-offset: 3px; }
  & .open li button:hover { text-decoration-color: currentColor; }
}
.dcf-safety__foot { padding: 10px 14px 14px; border-top: 1px solid var(--dcf-safety-hair); }
.dcf-safety__btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px; width: 100%; padding: 9px 14px; border-radius: 11px; font-weight: 700; font-size: 13px;
  background: var(--dcf-safety-ink); color: var(--dcf-safety-bg); transition: transform .25s var(--dcf-safety-spring), filter .2s;
  &:hover { filter: brightness(1.3); }
  &:active { transform: scale(.97); }
  &.ghost { background: transparent; color: var(--dcf-safety-ink); box-shadow: inset 0 0 0 1px var(--dcf-safety-line); }
  &.ghost:hover { background: var(--dcf-safety-soft); filter: none; }
}
.dcf-safety__sheet {
  position: absolute; inset: 0; z-index: 5; display: flex; flex-direction: column; gap: 12px; padding: 14px; overflow: auto; background: var(--dcf-safety-card);
  transition: transform .45s var(--dcf-safety-spring), opacity .25s;
  @starting-style { transform: translateY(24px); opacity: 0; }
  & h3 { font-size: 16px; font-weight: 780; letter-spacing: -.02em; }
  & legend { padding: 0; margin-bottom: 6px; font-size: 12px; font-weight: 650; }
}
.dcf-safety__sh { display: flex; align-items: center; justify-content: space-between; }
.dcf-safety__x { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; color: var(--dcf-safety-mute); &:hover { background: var(--dcf-safety-soft); color: var(--dcf-safety-ink); } }
.dcf-safety__kind {
  display: grid; grid-template-columns: 1fr 1fr; gap: 6px;
  & legend { grid-column: 1 / -1; }
  & label { display: flex; align-items: center; gap: 7px; padding: 8px 10px; border-radius: 10px; font-size: 12.5px; font-weight: 600; box-shadow: inset 0 0 0 1px var(--dcf-safety-line); cursor: pointer; transition: background-color .2s, box-shadow .2s; }
  & label:has(:checked) { background: color-mix(in oklch, var(--dcf-safety-nm) 10%, transparent); box-shadow: inset 0 0 0 1.5px var(--dcf-safety-nm); }
}
.dcf-safety__field {
  display: grid; gap: 5px; font-size: 12px; font-weight: 650;
  & :is(select, textarea) { width: 100%; padding: 8px 10px; border-radius: 10px; border: 1px solid var(--dcf-safety-line); background: var(--dcf-safety-bg); color: inherit; font: 500 13px/1.4 system-ui, sans-serif; resize: vertical; }
  & :is(select, textarea):focus-visible { outline: 2px solid var(--dcf-safety-acc); outline-offset: 0; border-color: transparent; }
  & em { font-style: normal; font-weight: 600; font-size: 11.5px; color: var(--dcf-safety-lti); }
  &:has(em:not([hidden])) :is(select, textarea) { border-color: var(--dcf-safety-lti); }
}
.dcf-safety__chk { display: flex; align-items: center; gap: 8px; font-size: 12.5px; cursor: pointer; }
.dcf-safety__fbtns { display: grid; grid-template-columns: 1fr 1.4fr; gap: 8px; margin-top: auto; }

.dcf-safety__tip {
  position: absolute; z-index: 30; top: 0; left: 0; max-width: 250px; padding: 8px 11px; border-radius: 10px; pointer-events: none;
  background: var(--dcf-safety-ink); color: var(--dcf-safety-bg); font-size: 12px; line-height: 1.45;
  box-shadow: 0 14px 30px -12px color-mix(in oklch, var(--dcf-safety-ink) 70%, transparent); opacity: 0; transition: opacity .12s;
  & b { display: block; } & span { display: block; opacity: .8; font-variant-numeric: tabular-nums; }
  & i { display: inline-block; width: 8px; height: 8px; margin-right: 6px; border-radius: 2px; background: var(--c); }
  &.on { opacity: 1; }
}
.dcf-safety__toast {
  position: absolute; z-index: 40; left: 50%; bottom: 18px; width: max-content; max-width: min(440px, calc(100% - 32px)); padding: 10px 16px; border-radius: 12px; pointer-events: none;
  background: var(--dcf-safety-acc); color: white; font-size: 12.5px; font-weight: 650; text-wrap: pretty;
  box-shadow: 0 18px 36px -14px color-mix(in oklch, var(--dcf-safety-ink) 70%, transparent);
  translate: -50% 0; opacity: 0; transform: translateY(12px); transition: opacity .25s, transform .5s var(--dcf-safety-spring);
  &.on { opacity: 1; transform: none; }
}

@keyframes dcf-safety-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dcf-safety-pop { from { opacity: 0; transform: scale(.4); } }
@keyframes dcf-safety-grow { from { transform: scaleY(0); } }
@keyframes dcf-safety-growx { from { transform: scaleX(0); } }
@keyframes dcf-safety-draw { to { stroke-dashoffset: 0; } }
@keyframes dcf-safety-reveal { from { opacity: 0; transform: translateY(10px); } }

@container dcf-safety (width < 960px) {
