const iso = (t) => new Date(t).toISOString().slice(0, 10);
const AREAS = ['Basement car park', 'Ground-floor slab', 'Gate 2 / logistics', 'Material laydown', 'Tower crane base', 'Level 2 slab', 'Scaffold, east elevation', 'Hoist landing, L5', 'Level 4, plot 4.07', 'Level 6, plot 6.03', 'Roof plant deck', 'Site welfare'];
const WHO = ['K. Adeyemi', 'T. Walsh', 'M. Szymański', 'R. Doyle', 'P. Okonjo', 'L. Fairbairn', 'S. Haddad', 'J. Kowalczyk', 'D. Mbeki', 'A. Rourke'];
const NM_T = ['Edge-protection board left unsecured', 'Load swung close to the gang during a tower-crane lift', 'Pallet of blocks stacked above 1.5 m', 'Telehandler reversed without a banksman', 'Toe board missing on a working platform', 'Trailing 110 V lead across the main walkway', 'Spanner dropped from height, exclusion zone held', 'Unguarded riser opening found', 'Hoist gate left open between lifts', 'Rebar caps missing on starter bars'];
