const SLOTS = []; [[2, 4], [2, 4], [0, 6], [0, 6], [0, 6], [2, 4], [2, 4]].forEach((rw, y) => { for (let x = rw[0]; x <= rw[1]; x++) SLOTS.push([x, y]); });
