        : (d.open ? '<p class="none">Nothing reported on this shift' + (Object.values(shown).every(Boolean) ? '' : ' for the event types shown') + '. The gang worked ' + num(d.hours) + ' hours injury-free.</p>' : ''));
    return;
  }
  const c = counts(monthEvents(mi)), tr = trir(mi), openEvs = EVENTS.filter((e) => e.open && vis(e)).slice(-4).reverse();
  el.innerHTML = '<p class="k">' + MN[M.m] + ' ' + M.y + '</p><h3>Accident triangle</h3><p class="sub">Every serious injury sits on a base of minor ones and near misses.</p>' +
    '<div class="pyr" role="img" aria-label="' + c.lti + ' lost time, ' + c.rec + ' recordable, ' + c.fa + ' first aid, ' + c.nm + ' near misses">' +
    [['lti', 'Lost time', c.lti, 0], ['rec', 'Recordable', c.rec, 1], ['fa', 'First aid', c.fa, 2], ['nm', 'Near misses', c.nm, 3]].map((x) => '<div class="' + x[0] + '" style="--k:' + x[3] + '"><span>' + x[1] + '</span><b>' + (shown[x[0]] ? x[2] : '–') + '</b></div>').join('') + '</div>' +
    '<p class="txt">TRIR is <b>' + tr.v.toFixed(2) + '</b> over the ' + (tr.months === 12 ? 'last 12 months' : tr.months + ' months since start') + ': ' + tr.n + ' recordable injur' + (tr.n === 1 ? 'y' : 'ies') + ' in ' + num(tr.h) + ' hours, × 200,000. Pick a day on the cross for its reports.</p>' +
    (openEvs.length ? '<div class="open"><h4>Open actions</h4><ul>' + openEvs.map((e) => '<li><button type="button" data-jump="' + e.ref + '">' + e.ref + ' · ' + esc(e.text) + '</button><span>' + TNAME[e.type] + ' · ' + fmtDay(e.day.t) + ' · owner ' + esc(e.owner) + '</span></li>').join('') + '</ul></div>' : '');
}

/* ------------------------------------------------------------------ orchestration */
function renderAll(quiet) {
  const M = MONTHS[mi];
  $('[data-mlabel]').textContent = MN[M.m] + ' ' + M.y;
  const pv = $('[data-mo="-1"]'), nx = $('[data-mo="1"]');
  if (mi === 0) { pv.setAttribute('aria-disabled', 'true'); pv.title = 'Records start in October 2025'; } else { pv.removeAttribute('aria-disabled'); pv.removeAttribute('title'); }
  if (mi === MONTHS.length - 1) { nx.setAttribute('aria-disabled', 'true'); nx.title = 'October 2026 is the current month'; } else { nx.removeAttribute('aria-disabled'); nx.removeAttribute('title'); }
  renderKpis(); renderCross(quiet); renderTypes();
  if (tab === 'cross') renderTrend(quiet); else renderLog();
  renderSide();
}
function toast(m) { toastEl.textContent = m; toastEl.classList.add('on'); clearTimeout(toast.t); toast.t = setTimeout(() => { if (root.isConnected) toastEl.classList.remove('on'); }, 3400); }
const toastEl = $('[data-toast]'), tip = $('[data-tip]'), sheet = $('[data-sheet]');
function gotoMonth(m) { mi = Math.max(0, Math.min(MONTHS.length - 1, m)); selDay = null; selEv = null; renderAll(); }
function pickDay(d, focus) {
  selDay = d; selEv = null; renderCross(true); renderSide();
  if (focus) { const b = $('[data-cross] [data-d="' + d + '"]'); if (b) b.focus(); }
}
function jumpTo(ref) {
  const e = EVENTS.find((x) => x.ref === ref); if (!e) return;
  mi = e.day.mi; selDay = e.day.d; selEv = ref; renderAll(true);
  const card = $('[data-day] [data-ev="' + ref + '"]'); if (card) card.scrollIntoView({ block: 'nearest' });
}
function setTab(t, focus) {
  tab = t;
  $$('[data-tab]').forEach((b) => { const on = b.dataset.tab === t; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  $$('[data-view]').forEach((v) => { v.hidden = v.dataset.view !== t; });
