}
function openSheet() {
  const sel = $('[data-area]');
  if (sel.options.length < 2) sel.insertAdjacentHTML('beforeend', AREAS.map((a) => '<option>' + esc(a) + '</option>').join(''));
  sheet.hidden = false; $$('[data-err]', sheet).forEach((x) => { x.hidden = true; });
  const f = sheet.querySelector('input[type=radio]:checked'); if (f) f.focus();
}
function closeSheet(back) { sheet.hidden = true; sheet.reset(); if (back !== false) { const b = $('[data-report]'); if (b) b.focus(); } }

root.addEventListener('click', (e) => {
  const t = e.target;
  const mo = t.closest('[data-mo]');
  if (mo) { if (mo.getAttribute('aria-disabled') === 'true') { toast(mo.title + '.'); return; } gotoMonth(mi + +mo.dataset.mo); return; }
  const tb = t.closest('[data-tab]'); if (tb) { setTab(tb.dataset.tab); return; }
  const ty = t.closest('[data-type]');
  if (ty) { shown[ty.dataset.type] = !shown[ty.dataset.type]; renderAll(true); const b = $('[data-type="' + ty.dataset.type + '"]'); if (b) b.focus(); return; }
  const cell = t.closest('[data-cross] button');
  if (cell) { if (cell.classList.contains('fut')) { toast(cell.title + ' — the log runs to today, Fri 2 Oct.'); return; } pickDay(+cell.dataset.d); return; }
  const mb = t.closest('[data-trend] .mo'); if (mb) { gotoMonth(+mb.dataset.m); const g = $('[data-trend] .mo[data-m="' + mi + '"]'); if (g) g.focus(); return; }
  if (t.closest('[data-back]')) { selDay = null; selEv = null; renderCross(true); renderSide(); return; }
  const cl = t.closest('[data-close]');
  if (cl) { const ev = EVENTS.find((x) => x.ref === cl.dataset.close); ev.open = false; renderSide(); if (tab === 'log') renderLog(); toast(ev.ref + ' closed out — action complete.'); return; }
  const jp = t.closest('[data-jump]'); if (jp) { jumpTo(jp.dataset.jump); return; }
  const so = t.closest('[data-sort]'); if (so) { const k = so.dataset.sort; if (k === sortKey) sortDir = -sortDir; else { sortKey = k; sortDir = k === 't' || k === 'sev' ? -1 : 1; } renderLog(); return; }
  const tr = t.closest('[data-log] tr'); if (tr) { const ev = EVENTS.find((x) => x.ref === tr.dataset.ref); selDay = ev.day.d; selEv = ev.ref; renderCross(true); renderSide(); $$('[data-log] tr').forEach((x) => x.setAttribute('aria-selected', x === tr)); return; }
  if (t.closest('[data-report]')) { openSheet(); return; }
  if (t.closest('[data-cancel]')) { closeSheet(); return; }
});
sheet.addEventListener('submit', (e) => {
  e.preventDefault();
  const fd = new FormData(sheet), area = fd.get('area'), desc = String(fd.get('desc') || '').trim(), kind = fd.get('dcf-safety-kind');
  const ea = sheet.querySelector('[data-err="area"]'), ed = sheet.querySelector('[data-err="desc"]');
  ea.hidden = !!area; ed.hidden = desc.length >= 15;
  if (!area || desc.length < 15) { (area ? sheet.querySelector('textarea') : sheet.querySelector('select')).focus(); return; }
  const day = DAYS[DAYS.length - 1], ev = { day, type: kind === 'uc' ? 'uc' : 'nm', area, trade: '', text: desc + (fd.get('made') ? ' Made safe at the time.' : ''), who: 'You', at: 14 * 60 + 5, open: true, owner: 'HSE advisor' };
  ev.ref = 'GH-' + (1001 + EVENTS.length); day.ev.push(ev); EVENTS.push(ev);
  closeSheet(false); shown.nm = true; mi = MONTHS.length - 1; selDay = day.d; selEv = ev.ref; renderAll(true);
  toast(ev.ref + ' logged against today — thank you for reporting it.');
  const b = $('[data-cross] [data-d="' + day.d + '"]'); if (b) b.focus();
});

root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (e.key === 'Escape') { tip.classList.remove('on'); if (!sheet.hidden) { closeSheet(); e.stopPropagation(); } return; }
  if (t.matches('[data-cross] button') && /^Arrow/.test(e.key)) {
    e.preventDefault();
    const days = monthDays(mi), cur = +t.dataset.d, k = cur - 1, [x, y] = SLOTS[k];
    let next = null;
    if (e.key === 'ArrowRight') next = cur + 1; else if (e.key === 'ArrowLeft') next = cur - 1;
    else { const dy = e.key === 'ArrowDown' ? 1 : -1, cand = SLOTS.map((s, i) => [s, i]).filter(([s, i]) => s[1] === y + dy && i < days.length); if (cand.length) next = cand.reduce((a, b) => (Math.abs(b[0][0] - x) < Math.abs(a[0][0] - x) ? b : a))[1] + 1; }
    if (next && days.some((d) => d.d === next)) pickDay(next, true);
    return;
  }
  if (t.matches('[data-log] tr') && /^Arrow(Up|Down)$/.test(e.key)) { e.preventDefault(); const n = e.key === 'ArrowDown' ? t.nextElementSibling : t.previousElementSibling; if (n) n.focus(); return; }
