  if (t.matches('[data-trend] .mo') && /^Arrow(Left|Right)$/.test(e.key)) { e.preventDefault(); gotoMonth(mi + (e.key === 'ArrowRight' ? 1 : -1)); const g = $('[data-trend] .mo[data-m="' + mi + '"]'); if (g) g.focus(); return; }
  const tl = t.closest('[role="tablist"]');
  if (tl && /^Arrow(Left|Right)$/.test(e.key)) { e.preventDefault(); setTab(tab === 'cross' ? 'log' : 'cross', true); }
});

/* hover */
function showTip(html, cx, cy) {
  const rr = root.getBoundingClientRect(); tip.innerHTML = html; tip.classList.add('on');
  let x = cx - rr.left + 14, y = cy - rr.top + 16; const w = tip.offsetWidth, h = tip.offsetHeight;
  if (x + w > rr.width - 8) x = cx - rr.left - w - 14; if (y + h > rr.height - 8) y = cy - rr.top - h - 12;
  tip.style.transform = 'translate(' + Math.max(6, x) + 'px,' + Math.max(6, y) + 'px)';
}
root.addEventListener('pointermove', (e) => {
  const mo = e.target.closest('[data-trend] .mo'), box = $('[data-trend]'), xh = $('[data-xh]');
  if (mo && box._data) {
    const m = +mo.dataset.m, d = box._data[m], g = box._geom, x = g.pl + m * g.bw + g.bw / 2;
    if (xh) { xh.setAttribute('x1', x); xh.setAttribute('x2', x); xh.classList.add('on'); }
    showTip('<b>' + MN[MONTHS[m].m] + ' ' + MONTHS[m].y + (m === MONTHS.length - 1 ? ' (to date)' : '') + '</b><span><i style="--c:var(--dcf-safety-nm)"></i>' + d.c.nm + ' near misses</span><span><i style="--c:var(--dcf-safety-fa)"></i>' + d.c.fa + ' first aid</span><span><i style="--c:var(--dcf-safety-rec)"></i>' + d.c.rec + ' recordable · <i style="--c:var(--dcf-safety-lti)"></i>' + d.c.lti + ' lost time</span><span>' + (m < 3 ? 'TRIR not plotted until 3 months of hours' : 'TRIR ' + d.tr.v.toFixed(2)) + ' · ' + num(hoursIn(m)) + ' h worked</span>', e.clientX, e.clientY);
    return;
  }
  if (xh) xh.classList.remove('on');
  const c = e.target.closest('[data-cross] button[data-d]');
  if (c) { const d = monthDays(mi).find((q) => q.d === +c.dataset.d), evs = d.ev.filter(vis), cc = counts(evs); showTip('<b>' + fmtDay(d.t, { weekday: 'long', month: 'long' }) + '</b>' + (d.open ? '<span>' + d.head + ' on site · ' + num(d.hours) + ' h</span><span>' + (evs.length ? [['nm', 'near miss'], ['fa', 'first aid'], ['rec', 'recordable'], ['lti', 'lost time']].filter((x) => cc[x[0]]).map((x) => cc[x[0]] + ' ' + x[1]).join(' · ') : 'Nothing reported') + '</span>' : '<span>Site closed</span>'), e.clientX, e.clientY); return; }
  tip.classList.remove('on');
