root.addEventListener('pointerleave', () => { tip.classList.remove('on'); const xh = $('[data-xh]'); if (xh) xh.classList.remove('on'); });

/* mount */
renderAll(false);
const ct = $('[data-days]');
if (RM) ct.classList.add('on'); else requestAnimationFrame(() => { if (!root.isConnected) return; requestAnimationFrame(() => { if (!root.isConnected) return; ct.classList.add('on'); }); });
