css:
.dcf-materials {
  --dcf-materials-bg: oklch(0.2 0.006 255);
  --dcf-materials-ink: oklch(0.95 0.004 255);
  --dcf-materials-acc: oklch(0.75 0.13 58);
  --dcf-materials-late: oklch(0.68 0.19 25);
  --dcf-materials-tight: oklch(0.84 0.14 88);
  --dcf-materials-ok: oklch(0.79 0.12 162);
  --dcf-materials-panel: color-mix(in oklch, var(--dcf-materials-bg) 94%, var(--dcf-materials-ink));
  --dcf-materials-deep: color-mix(in oklch, var(--dcf-materials-bg) 80%, black);
  --dcf-materials-line: color-mix(in oklch, var(--dcf-materials-ink) 12%, transparent);
  --dcf-materials-hair: color-mix(in oklch, var(--dcf-materials-ink) 6.5%, transparent);
  --dcf-materials-soft: color-mix(in oklch, var(--dcf-materials-ink) 6%, transparent);
  --dcf-materials-mute: color-mix(in oklch, var(--dcf-materials-ink) 62%, var(--dcf-materials-bg));
  --dcf-materials-faint: color-mix(in oklch, var(--dcf-materials-ink) 40%, var(--dcf-materials-bg));
  --dcf-materials-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dcf-materials-out: cubic-bezier(.16, 1, .3, 1);
  --dcf-materials-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.077 24.5%, 1.064 27.1%, 1.002 33.9%, .987 37.7%, .983 41.4%, .995 52.6%, 1.001 63.2%, 1);
  --dcf-materials-lab: 232px;
  width: 100%;
  height: var(--dcf-materials-h, 680px);
  container-type: inline-size;
  container-name: dcf-materials;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  border-radius: 18px;
  background: radial-gradient(120% 80% at 100% 0%, color-mix(in oklch, var(--dcf-materials-acc) 7%, transparent), transparent 60%), var(--dcf-materials-bg);
  color: var(--dcf-materials-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dcf-materials-acc);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dcf-materials-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, h4, p, ul, ol, dl, dd, fieldset) { margin: 0; padding: 0; }
  & fieldset { border: 0; min-width: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dcf-materials-acc); outline-offset: 2px; border-radius: 7px; }
  & [hidden] { display: none !important; }
}
.dcf-materials__ic { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.dcf-materials__cap { font-size: 10.5px; font-weight: 680; letter-spacing: .13em; text-transform: uppercase; color: var(--dcf-materials-faint); }

.dcf-materials__top { display: flex; align-items: center; flex-wrap: wrap; gap: 10px 16px; padding: 16px 18px 0; }
.dcf-materials__brand {
  display: flex; align-items: center; gap: 11px; margin-right: auto; min-width: 0;
  & svg { width: 36px; height: 36px; flex: none; padding: 7px; border-radius: 10px; background: color-mix(in oklch, var(--dcf-materials-acc) 18%, transparent); fill: none; stroke: var(--dcf-materials-acc); stroke-width: 1.6; stroke-linejoin: round; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dcf-materials-acc) 35%, transparent); }
  & b { display: block; font-size: clamp(17px, 1.9cqi, 21px); font-weight: 760; letter-spacing: -.03em; line-height: 1.1; }
  & small { display: block; font-size: 11.5px; color: var(--dcf-materials-mute); }
}
.dcf-materials__look, .dcf-materials__seg {
  display: flex; align-items: center; gap: 2px; padding: 3px; border-radius: 11px; background: var(--dcf-materials-deep); box-shadow: inset 0 0 0 1px var(--dcf-materials-hair);
  & .dcf-materials__cap { padding: 0 8px 0 6px; }
  & button { padding: 5px 11px; border-radius: 8px; font-size: 12px; font-weight: 620; color: var(--dcf-materials-mute); white-space: nowrap; transition: color .2s, background-color .2s; }
  & button:hover { color: var(--dcf-materials-ink); }
  & button[aria-checked="true"] { background: var(--dcf-materials-panel); color: var(--dcf-materials-ink); box-shadow: inset 0 0 0 1px var(--dcf-materials-line); }
  & button em { font-style: normal; margin-left: 5px; font: 650 10.5px var(--dcf-materials-mono); color: var(--dcf-materials-faint); }
  & button.late em { color: var(--dcf-materials-late); }
}

.dcf-materials__kpis {
  display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 8px; padding: 14px 18px 0;
  & > div { position: relative; padding: 10px 13px 11px; border-radius: 13px; background: var(--dcf-materials-panel); box-shadow: inset 0 0 0 1px var(--dcf-materials-hair); min-width: 0; overflow: hidden; animation: dcf-materials-rise .6s var(--dcf-materials-out) both; animation-delay: calc(var(--i) * 55ms); }
  & > div::before { content: ""; position: absolute; left: 0; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--c, transparent); }
  & dt { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dcf-materials-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font: 700 clamp(18px, 2cqi, 23px)/1.2 var(--dcf-materials-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
  & dd small { display: block; font: 500 11.5px/1.35 system-ui, sans-serif; letter-spacing: 0; color: var(--dcf-materials-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd.bump { animation: dcf-materials-bump .6s var(--dcf-materials-spring); }
}

.dcf-materials__main { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dcf-materials__body { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: 12px; min-height: 0; padding: 12px 18px 16px; }
.dcf-materials__col { display: grid; grid-template-rows: minmax(0, 1fr) 150px; gap: 12px; min-height: 0; min-width: 0; }
.dcf-materials__card {
  position: relative; min-width: 0; min-height: 0; border-radius: 15px; background: var(--dcf-materials-panel); box-shadow: inset 0 0 0 1px var(--dcf-materials-hair), 0 20px 40px -32px black;
  animation: dcf-materials-rise .7s var(--dcf-materials-out) both .1s;
}
.dcf-materials__tl { display: flex; flex-direction: column; overflow: hidden; }
.dcf-materials__bar { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px; padding: 10px 12px 8px; }
.dcf-materials__scroll { flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; }
.dcf-materials__axis {
  position: sticky; top: 0; z-index: 3; display: grid; grid-template-columns: var(--dcf-materials-lab) minmax(0, 1fr); height: 26px; padding-right: 16px;
  background: color-mix(in oklch, var(--dcf-materials-panel) 94%, transparent); border-bottom: 1px solid var(--dcf-materials-hair);
  & > div { position: relative; }
  & .m { position: absolute; top: 6px; padding-left: 5px; border-left: 1px solid var(--dcf-materials-line); font: 650 10.5px var(--dcf-materials-mono); color: var(--dcf-materials-mute); white-space: nowrap; }
  & .t { position: absolute; top: 4px; translate: -50% 0; padding: 1px 6px; border-radius: 5px; font: 750 10px var(--dcf-materials-mono); color: var(--dcf-materials-deep); background: var(--dcf-materials-acc); z-index: 1; }
  & .h { position: absolute; top: 4px; translate: -50% 0; padding: 1px 6px; border-radius: 5px; font: 650 10px var(--dcf-materials-mono); color: var(--dcf-materials-bg); background: var(--dcf-materials-ink); opacity: 0; transition: opacity .12s; z-index: 2; white-space: nowrap; }
  & .h.on { opacity: 1; }
}
.dcf-materials__ah { padding: 6px 0 0 14px; font-size: 10px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dcf-materials-faint); }
.dcf-materials__wrap { position: relative; }
.dcf-materials__rows {
  padding: 2px 0 6px;
  & li {
    --c: var(--dcf-materials-ok);
    position: relative; display: grid; grid-template-columns: var(--dcf-materials-lab) minmax(0, 1fr); align-items: center; height: 40px; padding-right: 16px; cursor: pointer;
    transition: background-color .2s, opacity .3s;
    &:hover { background: var(--dcf-materials-soft); }
    &[aria-selected="true"] { background: color-mix(in oklch, var(--dcf-materials-acc) 11%, transparent); }
    &[aria-selected="true"]::before { content: ""; position: absolute; left: 0; top: 7px; bottom: 7px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dcf-materials-acc); }
    &.late { --c: var(--dcf-materials-late); } &.tight { --c: var(--dcf-materials-tight); } &.done { --c: var(--dcf-materials-faint); } &.order { --c: var(--dcf-materials-mute); }
    &.dim { opacity: .3; }
    &:focus-visible { outline-offset: -2px; }
  }
  & .lb { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0 8px; align-items: center; padding: 0 10px 0 14px; min-width: 0; }
