const gbp = (n) => '£' + Math.round(n).toLocaleString('en-GB');
const gbpk = (n) => n >= 1e6 ? '£' + (n / 1e6).toFixed(2) + 'm' : n >= 1e4 ? '£' + Math.round(n / 1000) + 'k' : gbp(n);

/* ------------------------------------------------------------------ data
   Dates are whole days from Fri 2 Oct 2026 (day 0). Float = need-by minus ETA. A package that
