const D0 = Date.UTC(2026, 9, 2), DAY = 86400000;
const d = (y, m, dd) => Math.round((Date.UTC(y, m - 1, dd) - D0) / DAY);
const fmt = (n, o) => new Date(D0 + n * DAY).toLocaleDateString('en-GB', Object.assign({ timeZone: 'UTC', day: 'numeric', month: 'short' }, o || {}));
const STAGES = ['PO raised', 'Drawings approved', 'In production', 'Shipped', 'Delivered'];
/* po, package, supplier, programme activity, need-by, lead (weeks), PO date, ETA, stage (0-4, -1 = not ordered), value, truckloads */
const PK = [
  ['PO-3095', 'Tower-crane climbing frame', 'Halden Fabrications', 'Crane climb 3', d(2026, 9, 21), 6, d(2026, 8, 3), d(2026, 9, 21), 4, 22600, 1],
