  ['PO-3136', 'Plasterboard & metal stud', 'Harwell Building Supplies', 'Drylining L1–L3', d(2026, 12, 7), 6, d(2026, 9, 25), d(2026, 12, 4), 0, 142000, 8],
  ['PO-3115', 'Rainscreen cassettes', 'Tessel Cladding', 'Rainscreen, north & west', d(2027, 1, 25), 16, d(2026, 9, 1), d(2027, 1, 11), 1, 388000, 6],
  ['PO-3112', 'Curtain wall units CW-1', 'Velomar Façades', 'Curtain wall, south', d(2027, 1, 18), 20, d(2026, 8, 18), d(2027, 2, 1), 2, 1240000, 12],
  ['PO-3118', 'Air handling units AHU-01/02', 'Corrin Air', 'Plant room fit-out', d(2027, 2, 8), 22, d(2026, 8, 14), d(2027, 2, 15), 2, 274000, 2],
  ['PO-3124', 'LV switchgear', 'Ashcombe Electrical', 'LV room energisation', d(2027, 2, 15), 24, d(2026, 9, 10), d(2027, 3, 5), 1, 326000, 2],
  ['PO-3121', 'Chillers CH-1/2', 'Nordvik Cooling', 'Roof plant', d(2027, 3, 1), 26, d(2026, 7, 2), d(2027, 2, 8), 2, 410000, 2],
  ['PO-3130', 'Lift cars & machines (3)', 'Kessler Lifts', 'Lift installation', d(2027, 3, 1), 34, d(2026, 5, 12), d(2027, 2, 15), 2, 520000, 3],
  ['PO-3127', 'Standby generator, 800 kVA', 'Peregrine Power', 'Generator set & test', d(2027, 3, 22), 24, null, null, -1, 186000, 1],
  ['PO-3133', 'Raised access floor', 'Gridline Floors', 'Raised floors L2–L6', d(2027, 3, 29), 8, null, null, -1, 164000, 4],
  ['PO-3139', 'Doorsets & ironmongery', 'Linden Joinery', 'Doors & frames', d(2027, 4, 12), 14, null, null, -1, 212000, 3],
  ['PO-3142', 'Fume cupboards (24)', 'Labryx Systems', 'Lab fit-out', d(2027, 4, 26), 30, d(2026, 8, 28), d(2027, 4, 5), 1, 690000, 4],
  ['PO-3145', 'Lab benching', 'Labryx Systems', 'Lab fit-out', d(2027, 5, 3), 16, null, null, -1, 455000, 5]
