const P = Object.fromEntries(PK.map((p) => [p.po, p]));
const orderBy = (p) => p.need - p.lead * 7;
const projEta = (p) => (p.stage < 0 ? p.lead * 7 : p.eta);
const floatOf = (p) => (p.stage === 4 ? 0 : p.need - projEta(p));
function cls(p) {
  if (p.stage === 4) return 'done';
  if (p.stage < 0) return 'order';
  const f = floatOf(p);
  return f < 0 ? 'late' : f < 8 ? 'tight' : 'ok';
}
const STATUS = [['all', 'All'], ['late', 'Late'], ['tight', 'At risk'], ['order', 'To order'], ['done', 'Delivered']];
const inStatus = (p, s) => s === 'all' || (s === 'late' ? cls(p) === 'late' : s === 'order' ? p.stage < 0 : cls(p) === s);

/* ------------------------------------------------------------------ state */
let look = 99, filt = 'all', sortKey = 'need', sel = 'PO-3104', week = null, spent = 0;
const rowsEl = $('[data-rows]'), detail = $('[data-detail]'), tip = $('[data-tip]'), toastEl = $('[data-toast]'), ov = $('.dcf-materials__ov');
const inWindow = (p) => look === 99 || (p.need >= -14 && p.need <= look * 7) || (p.stage >= 0 && p.stage < 4 && p.eta <= look * 7 && p.eta >= -14);
let DOM = [0, 1];
function domain() {
  const list = PK.filter(inWindow);
  const a = Math.min(-7, ...list.map((p) => Math.min(p.need, p.stage >= 0 ? p.eta : p.need, p.stage < 0 ? orderBy(p) : p.need)));
  const b = look === 99 ? Math.max(...list.map((p) => Math.max(p.need, projEta(p)))) + 10 : look * 7 + 10;
  DOM = [Math.max(-21, a - 3), b];
}
const X = (n) => Math.max(0, Math.min(100, (n - DOM[0]) / (DOM[1] - DOM[0]) * 100));
const weekOf = (n) => Math.floor((n + 4) / 7);           /* Mon-based weeks: week 0 = Mon 28 Sep */
function visible() {
  let l = PK.filter((p) => inWindow(p) && inStatus(p, filt));
  if (week !== null) l = l.filter((p) => p.stage >= 0 && p.stage < 4 && arrivals(p).some((a) => a.w === week));
  const f = { need: (p) => p.need, float: (p) => (p.stage === 4 ? 999 : floatOf(p)), value: (p) => -p.value }[sortKey];
  return l.sort((a, b) => f(a) - f(b) || a.n - b.n);
}
function arrivals(p) {                                 /* big packages arrive at four loads a week */
  if (p.stage < 0 || p.stage === 4) return [];
  const out = []; let left = p.loads, w = weekOf(p.eta);
  while (left > 0) { const k = Math.min(4, left); out.push({ w, k }); left -= k; w++; }
  return out;
}

/* ------------------------------------------------------------------ KPIs */
const kprev = {};
function renderKpis() {
  const live = PK.filter((p) => inWindow(p));
  const late = live.filter((p) => cls(p) === 'late'), tight = live.filter((p) => cls(p) === 'tight'), toOrder = live.filter((p) => p.stage < 0);
  const lateOrd = toOrder.filter((p) => orderBy(p) < 15);
