    showTip('<b>Week of ' + new Date(mon).toLocaleDateString('en-GB', { timeZone: 'UTC', weekday: 'short', day: 'numeric', month: 'short' }) + '</b><span style="--c:var(--dcf-materials-' + (v > CAP ? 'late' : 'ok') + ')"><em>' + v + ' truckload' + (v === 1 ? '' : 's') + '</em> of ' + CAP + ' the yard can take</span>' + list.map((x) => '<span>' + x[1] + ' × ' + esc(x[0].name) + '</span>').join('') + (list.length ? '<span>Click to filter the timeline</span>' : ''), e.clientX, e.clientY);
    return;
  }
  tip.classList.remove('on');
});
root.addEventListener('pointerleave', hide);
$('[data-scroll]').addEventListener('scroll', hide, { passive: true });

/* mount */
buildRows(); renderAll({ wipe: true });
if (window.ResizeObserver) {
  let lw = 0, ll = '';
  const ro = new ResizeObserver(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    const w = rowsEl.clientWidth; if (w && w !== lw) { lw = w; paintAxis(); }
    const b = $('[data-lay]'), k = b.clientWidth + 'x' + b.clientHeight; if (b.clientWidth && k !== ll) { ll = k; renderLay(true); }
  });
  ro.observe(rowsEl); ro.observe($('[data-lay]'));
}

css:
.dcf-ftf {
  --dcf-ftf-bg: oklch(0.205 0.022 205);
  --dcf-ftf-ink: oklch(0.95 0.012 190);
  --dcf-ftf-acc: oklch(0.75 0.14 38);
  --dcf-ftf-good: oklch(0.81 0.12 168);
  --dcf-ftf-warn: oklch(0.84 0.13 84);
  --dcf-ftf-panel: color-mix(in oklch, var(--dcf-ftf-bg) 93%, var(--dcf-ftf-ink));
  --dcf-ftf-deep: color-mix(in oklch, var(--dcf-ftf-bg) 78%, black);
  --dcf-ftf-line: color-mix(in oklch, var(--dcf-ftf-ink) 12%, transparent);
  --dcf-ftf-hair: color-mix(in oklch, var(--dcf-ftf-ink) 6.5%, transparent);
  --dcf-ftf-soft: color-mix(in oklch, var(--dcf-ftf-ink) 6%, transparent);
  --dcf-ftf-mute: color-mix(in oklch, var(--dcf-ftf-ink) 63%, var(--dcf-ftf-bg));
  --dcf-ftf-faint: color-mix(in oklch, var(--dcf-ftf-ink) 40%, var(--dcf-ftf-bg));
  --dcf-ftf-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dcf-ftf-out: cubic-bezier(.16, 1, .3, 1);
  --dcf-ftf-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.077 24.5%, 1.064 27.1%, 1.002 33.9%, .987 37.7%, .983 41.4%, .995 52.6%, 1.001 63.2%, 1);
  --dcf-ftf-cols: 178px 48px minmax(0, 1fr) 56px;
  width: 100%;
  height: var(--dcf-ftf-h, 680px);
  container-type: inline-size;
  container-name: dcf-ftf;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  border-radius: 18px;
  background: var(--dcf-ftf-bg);
  color: var(--dcf-ftf-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dcf-ftf-acc);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dcf-ftf-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, h4, p, ul, ol, dl, dd) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dcf-ftf-acc); outline-offset: 2px; border-radius: 7px; }
  & [hidden] { display: none !important; }
}
.dcf-ftf__cap { font-size: 10.5px; font-weight: 680; letter-spacing: .13em; text-transform: uppercase; color: var(--dcf-ftf-faint); }
.dcf-ftf__top { display: flex; align-items: center; flex-wrap: wrap; gap: 10px 14px; padding: 16px 18px 0; }
.dcf-ftf__brand {
  display: flex; align-items: center; gap: 11px; margin-right: auto; min-width: 0;
  & svg { width: 36px; height: 36px; flex: none; padding: 6px; border-radius: 50%; background: var(--dcf-ftf-good); fill: none; stroke: var(--dcf-ftf-deep); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: clamp(17px, 1.9cqi, 21px); font-weight: 780; letter-spacing: -.035em; line-height: 1.1; }
  & small { display: block; font-size: 11.5px; color: var(--dcf-ftf-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}
.dcf-ftf__seg, .dcf-ftf__tabs {
  display: flex; align-items: center; gap: 2px; padding: 3px; border-radius: 11px; background: var(--dcf-ftf-deep); box-shadow: inset 0 0 0 1px var(--dcf-ftf-hair);
  & .dcf-ftf__cap { padding: 0 6px; }
  & button { padding: 5px 11px; border-radius: 8px; font-size: 12px; font-weight: 640; color: var(--dcf-ftf-mute); white-space: nowrap; transition: color .2s, background-color .2s; }
  & button:hover { color: var(--dcf-ftf-ink); }
  & button:is([aria-checked="true"], [aria-selected="true"]) { background: var(--dcf-ftf-panel); color: var(--dcf-ftf-ink); box-shadow: inset 0 0 0 1px var(--dcf-ftf-line); }
  &[aria-disabled="true"] { opacity: .4; & button { cursor: not-allowed; } }
}

.dcf-ftf__kpis {
  display: grid; grid-template-columns: 1.25fr repeat(4, minmax(0, 1fr)); gap: 0; margin: 14px 18px 0; border-radius: 14px; background: var(--dcf-ftf-panel); box-shadow: inset 0 0 0 1px var(--dcf-ftf-hair);
  & > div { position: relative; padding: 10px 14px 11px; min-width: 0; animation: dcf-ftf-rise .6s var(--dcf-ftf-out) both; animation-delay: calc(var(--i) * 55ms); }
  & > div + div::before { content: ""; position: absolute; left: 0; top: 12px; bottom: 12px; width: 1px; background: var(--dcf-ftf-line); }
  & dt { font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dcf-ftf-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font: 700 clamp(18px, 2cqi, 23px)/1.2 var(--dcf-ftf-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & dd small { display: block; font: 500 11.5px/1.35 system-ui, sans-serif; letter-spacing: 0; color: var(--dcf-ftf-mute); overflow: hidden; text-overflow: ellipsis; }
  & dd em { font-style: normal; font-size: .62em; letter-spacing: -.01em; color: var(--dcf-ftf-mute); margin-left: 6px; }
  & .good { color: var(--dcf-ftf-good); } & .bad { color: var(--dcf-ftf-acc); }
}

.dcf-ftf__scrollall { min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); }
.dcf-ftf__body { display: grid; grid-template-columns: minmax(0, 1fr) 296px; gap: 12px; min-height: 0; padding: 12px 18px 16px; }
.dcf-ftf__card { position: relative; min-width: 0; min-height: 0; border-radius: 15px; background: var(--dcf-ftf-panel); box-shadow: inset 0 0 0 1px var(--dcf-ftf-hair); animation: dcf-ftf-rise .7s var(--dcf-ftf-out) both .12s; }
.dcf-ftf__main { display: flex; flex-direction: column; overflow: hidden; }
.dcf-ftf__bar { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px; padding: 10px 12px 8px; }
.dcf-ftf__view { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.dcf-ftf__scroll { flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; }
.dcf-ftf__axis {
  position: sticky; top: 0; z-index: 3; display: grid; grid-template-columns: var(--dcf-ftf-cols); align-items: end; height: 26px; padding: 0 14px 5px;
  background: color-mix(in oklch, var(--dcf-ftf-panel) 94%, transparent); border-bottom: 1px solid var(--dcf-ftf-hair);
  font-size: 10px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dcf-ftf-faint);
  & .n, & .v { text-align: right; }
  & > div { position: relative; height: 100%; margin: 0 10px; }
  & > div span { position: absolute; bottom: 0; translate: -50% 0; font: 600 10px var(--dcf-ftf-mono); letter-spacing: 0; text-transform: none; }
  & > div span.end { translate: -100% 0; }
}
.dcf-ftf__wrap { position: relative; }
.dcf-ftf__rows {
  padding: 3px 0 6px;
  & li {
    --c: var(--dcf-ftf-good);
    position: relative; display: grid; grid-template-columns: var(--dcf-ftf-cols); align-items: center; height: 36px; padding: 0 14px; cursor: pointer; transition: background-color .2s;
    &:hover { background: var(--dcf-ftf-soft); }
    &[aria-selected="true"] { background: color-mix(in oklch, var(--dcf-ftf-acc) 11%, transparent); }
    &[aria-selected="true"]::before { content: ""; position: absolute; left: 0; top: 6px; bottom: 6px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dcf-ftf-acc); }
    &.below { --c: var(--dcf-ftf-acc); }
    &.unsure { --c: var(--dcf-ftf-warn); }
    &:focus-visible { outline-offset: -2px; }
  }
  & .nm { min-width: 0; display: flex; align-items: center; gap: 8px; white-space: nowrap; }
  & .nm b { font-weight: 620; font-size: 12.5px; overflow: hidden; text-overflow: ellipsis; }
  & .tr { flex: none; width: 22px; height: 18px; border-radius: 5px; display: grid; place-items: center; font: 700 9.5px var(--dcf-ftf-mono); color: var(--dcf-ftf-mute); background: var(--dcf-ftf-soft); }
  & .n { text-align: right; font: 600 11.5px var(--dcf-ftf-mono); color: var(--dcf-ftf-mute); font-variant-numeric: tabular-nums; }
  & .tk { position: relative; height: 100%; margin: 0 10px; }
  & .ci, & .pt { position: absolute; left: 0; right: 0; top: 50%; pointer-events: none; }
  & .ci { height: 8px; margin-top: -4px; border-radius: 4px; background: color-mix(in oklch, var(--c) 26%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 55%, transparent); transform-origin: left; transform: translateX(calc(var(--lo) * 1%)) scaleX(calc(max(var(--hi) - var(--lo), .5) / 100)); transition: transform .8s var(--dcf-ftf-spring), background-color .4s, box-shadow .4s; }
  & .pt { height: 0; translate: calc(var(--p) * 1%) 0; transition: translate .8s var(--dcf-ftf-spring); }
  & .pt i { position: absolute; left: 0; top: 0; width: 12px; height: 12px; translate: -50% -50%; border-radius: 50%; background: var(--c); box-shadow: 0 0 0 3px var(--dcf-ftf-panel); transition: background-color .4s; }
  & .v { text-align: right; font: 700 13px var(--dcf-ftf-mono); color: var(--c); font-variant-numeric: tabular-nums; }
  & .v small { display: block; font: 500 9.5px var(--dcf-ftf-mono); color: var(--dcf-ftf-faint); }
}
.dcf-ftf__ov {
  position: absolute; top: 0; bottom: 0; left: calc(14px + 178px + 48px + 10px); right: calc(14px + 56px + 10px); pointer-events: none; z-index: 1;
  & i { position: absolute; top: 0; bottom: 0; left: 0; width: 0; transition: left .8s var(--dcf-ftf-spring); }
  & .tgt { border-left: 1.5px dashed color-mix(in oklch, var(--dcf-ftf-good) 70%, transparent); }
  & .avg { border-left: 1.5px solid color-mix(in oklch, var(--dcf-ftf-ink) 40%, transparent); }
}
.dcf-ftf__key {
  display: inline-flex; align-items: center; gap: 6px; margin-right: 10px; font: 650 11px var(--dcf-ftf-mono); color: var(--dcf-ftf-ink); white-space: nowrap;
  & i { width: 14px; height: 0; border-top: 1.5px dashed var(--dcf-ftf-good); }
  & i.ka { margin-left: 6px; border-top: 1.5px solid color-mix(in oklch, var(--dcf-ftf-ink) 45%, transparent); }
}
.dcf-ftf__why { padding: 8px 14px 10px; border-top: 1px solid var(--dcf-ftf-hair); font-size: 11.5px; color: var(--dcf-ftf-mute); text-wrap: pretty; }

.dcf-ftf__trendv { padding: 0 12px 12px; gap: 10px; overflow: auto; }
.dcf-ftf__trend {
  position: relative; flex: 1 1 220px; min-height: 200px;
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  & .gl { stroke: var(--dcf-ftf-hair); }
  & .ax { font: 10px var(--dcf-ftf-mono); fill: var(--dcf-ftf-faint); }
  & .band { fill: color-mix(in oklch, var(--dcf-ftf-good) 14%, transparent); }
  & .ln { fill: none; stroke: var(--dcf-ftf-good); stroke-width: 2.4; stroke-linejoin: round; stroke-linecap: round; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dcf-ftf-draw 1.1s var(--dcf-ftf-out) .2s forwards; }
  & .tg { stroke: var(--dcf-ftf-good); stroke-dasharray: 5 5; opacity: .6; }
  & .vis { fill: color-mix(in oklch, var(--dcf-ftf-ink) 10%, transparent); }
  & .dot { fill: var(--dcf-ftf-panel); stroke: var(--dcf-ftf-good); stroke-width: 2; }
  & .xh { stroke: var(--dcf-ftf-ink); stroke-dasharray: 3 3; opacity: 0; }
  & .xh.on { opacity: .4; }
  & .hit { fill: transparent; }
  & .area { clip-path: inset(0 100% 0 0); animation: dcf-ftf-reveal 1s var(--dcf-ftf-out) .2s forwards; }
  &[data-quiet] :is(.ln, .area) { animation: none; stroke-dashoffset: 0; clip-path: none; }
}
.dcf-ftf__causes {
  & h4 { display: flex; justify-content: space-between; gap: 8px; margin-bottom: 8px; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dcf-ftf-faint); }
  & h4 span { letter-spacing: 0; text-transform: none; font-weight: 500; }
  & .stack { display: flex; height: 26px; border-radius: 8px; overflow: hidden; gap: 2px; }
  & .stack i { flex: var(--w) 1 0; min-width: 2px; background: var(--c); transform-origin: left; animation: dcf-ftf-growx .7s var(--dcf-ftf-out) both; animation-delay: calc(var(--i) * 80ms); }
  & ul { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 6px 14px; margin-top: 10px; }
  & li { display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; align-items: baseline; gap: 8px; font-size: 12px; }
  & li i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); align-self: center; }
  & li b { font: 700 12px var(--dcf-ftf-mono); }
  & li small { grid-column: 2 / -1; color: var(--dcf-ftf-mute); font-size: 11.5px; }
}

.dcf-ftf__detail {
  overflow: auto; padding: 16px; animation-delay: .2s;
  & .k { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dcf-ftf-faint); }
  & h3 { margin-top: 3px; font-size: 18px; font-weight: 780; letter-spacing: -.03em; line-height: 1.15; text-wrap: balance; }
  & .sub { font-size: 12px; color: var(--dcf-ftf-mute); }
  & .big { display: flex; align-items: baseline; gap: 10px; margin-top: 12px; }
  & .big b { font: 800 34px/1 var(--dcf-ftf-mono); letter-spacing: -.05em; color: var(--c); }
  & .big span { font-size: 12px; color: var(--dcf-ftf-mute); text-wrap: pretty; }
  & .big span strong { color: var(--dcf-ftf-ink); font-weight: 650; }
  & h4 { margin: 16px 0 7px; font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dcf-ftf-faint); display: flex; justify-content: space-between; }
  & h4 span { letter-spacing: 0; text-transform: none; font-weight: 500; }
  & .last { display: grid; grid-template-columns: repeat(12, 1fr); gap: 3px; }
  & .last i { aspect-ratio: 1; border-radius: 4px; background: var(--dcf-ftf-good); display: grid; place-items: center; font: 750 9px var(--dcf-ftf-mono); font-style: normal; color: var(--dcf-ftf-deep); animation: dcf-ftf-pop .45s var(--dcf-ftf-spring) both; animation-delay: calc(var(--i) * 28ms); }
  & .last i.r { background: var(--dcf-ftf-acc); }
  & .rs { display: grid; gap: 5px; }
  & .rs li { display: grid; grid-template-columns: 112px minmax(0, 1fr) 20px; align-items: center; gap: 8px; font-size: 12px; color: var(--dcf-ftf-mute); }
  & .rs .b { height: 8px; border-radius: 4px; background: var(--dcf-ftf-hair); overflow: hidden; }
  & .rs .b i { display: block; height: 100%; width: 100%; background: var(--c); border-radius: 4px; transform-origin: left; transform: scaleX(var(--w)); transition: transform .7s var(--dcf-ftf-out); }
  & .rs b { font: 700 12px var(--dcf-ftf-mono); color: var(--dcf-ftf-ink); text-align: right; }
  & .parts { display: grid; gap: 4px; }
  & .parts li { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 6px 8px 6px 10px; border-radius: 10px; background: var(--dcf-ftf-deep); font-size: 12px; }
  & .parts li span small { display: block; color: var(--dcf-ftf-faint); font-size: 11px; }
  & .what { margin-top: 10px; padding: 10px 12px; border-radius: 11px; font-size: 12.5px; background: color-mix(in oklch, var(--dcf-ftf-good) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dcf-ftf-good) 30%, transparent); text-wrap: pretty; }
  & .what b { font-family: var(--dcf-ftf-mono); }
  & .acts { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }
  &[data-quiet] .last i { animation: none; }
}
.dcf-ftf__btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 7px 13px; border-radius: 10px; font-size: 12.5px; font-weight: 700;
  background: var(--dcf-ftf-acc); color: var(--dcf-ftf-deep); transition: transform .25s var(--dcf-ftf-spring), filter .2s;
  &:hover { filter: brightness(1.08); }
  &:active { transform: scale(.96); }
  &.ghost { background: transparent; color: var(--dcf-ftf-ink); box-shadow: inset 0 0 0 1px var(--dcf-ftf-line); }
  &.ghost:hover { background: var(--dcf-ftf-soft); }
  &[aria-busy="true"] { cursor: progress; filter: saturate(.3); }
  &[aria-busy="true"]::before { content: ""; width: 11px; height: 11px; border-radius: 50%; border: 2px solid currentColor; border-right-color: transparent; animation: dcf-ftf-spin .7s linear infinite; }
  &.done { background: var(--dcf-ftf-soft); color: var(--dcf-ftf-mute); cursor: default; }
}
.dcf-ftf__van {
  padding: 3px 9px; border-radius: 8px; font-size: 11.5px; font-weight: 700; white-space: nowrap; color: var(--dcf-ftf-mute); box-shadow: inset 0 0 0 1px var(--dcf-ftf-line); transition: background-color .2s, color .2s;
  &:hover { color: var(--dcf-ftf-ink); }
  &[aria-pressed="true"] { background: var(--dcf-ftf-good); color: var(--dcf-ftf-deep); box-shadow: none; }
}

.dcf-ftf__tip {
  position: absolute; z-index: 30; top: 0; left: 0; max-width: 260px; padding: 8px 11px; border-radius: 10px; pointer-events: none;
  background: color-mix(in oklch, var(--dcf-ftf-deep) 92%, black); color: var(--dcf-ftf-ink); font-size: 12px; line-height: 1.45;
  box-shadow: inset 0 0 0 1px var(--dcf-ftf-line), 0 16px 32px -12px black; opacity: 0; transition: opacity .12s;
  & b { display: block; } & span { display: block; color: var(--dcf-ftf-mute); font-variant-numeric: tabular-nums; }
  &.on { opacity: 1; }
}
.dcf-ftf__toast {
  position: absolute; z-index: 40; left: 50%; bottom: 18px; width: max-content; max-width: min(460px, calc(100% - 32px)); padding: 10px 16px; border-radius: 12px; pointer-events: none;
  background: var(--dcf-ftf-good); color: var(--dcf-ftf-deep); font-size: 12.5px; font-weight: 650; text-wrap: pretty; box-shadow: 0 18px 36px -12px black;
  translate: -50% 0; opacity: 0; transform: translateY(12px); transition: opacity .25s, transform .5s var(--dcf-ftf-spring);
  &.on { opacity: 1; transform: none; }
}

@keyframes dcf-ftf-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes dcf-ftf-draw { to { stroke-dashoffset: 0; } }
@keyframes dcf-ftf-reveal { to { clip-path: inset(0 0 0 0); } }
@keyframes dcf-ftf-growx { from { transform: scaleX(0); } }
@keyframes dcf-ftf-pop { from { opacity: 0; transform: scale(.3); } }
@keyframes dcf-ftf-spin { to { transform: rotate(1turn); } }
@keyframes dcf-ftf-in { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }

@container dcf-ftf (width < 960px) {
  .dcf-ftf__scrollall { --dcf-ftf-cols: 150px 40px minmax(0, 1fr) 50px; }
  .dcf-ftf__ov { left: calc(14px + 150px + 40px + 10px); right: calc(14px + 50px + 10px); }
  .dcf-ftf__body { grid-template-columns: minmax(0, 1fr) 256px; }
  .dcf-ftf__kpis > div { padding: 9px 10px; }
  .dcf-ftf__sort .dcf-ftf__cap { display: none; }
}
@container dcf-ftf (width < 760px) {
  .dcf-ftf__top { padding: 12px 12px 10px; }
  .dcf-ftf__scrollall { display: block; overflow: auto; overscroll-behavior: contain; }
  .dcf-ftf__kpis { margin: 0 12px; grid-template-columns: repeat(3, minmax(0, 1fr)); & > div:nth-child(4)::before { display: none; } }
