const RM = !!(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches);
const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => Array.from((el || root).querySelectorAll(s));
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const pc = (v, d) => (v * 100).toFixed(d == null ? 0 : d) + '%';
function rng(a) { return function () { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const r = rng(2718);
const pois = (l) => { let k = 0, p = 1; const L = Math.exp(-l); do { k++; p *= r(); } while (p > L); return k - 1; };

/* Wilson score interval: honest bounds for a proportion from a small sample */
function wilson(k, n, z) {
  z = z || 1.96; if (!n) return [0, 0, 1];
  const p = k / n, z2 = z * z, den = 1 + z2 / n, c = (p + z2 / (2 * n)) / den, h = z * Math.sqrt(p * (1 - p) / n + z2 / (4 * n * n)) / den;
  return [p, Math.max(0, c - h), Math.min(1, c + h)];
}

/* ------------------------------------------------------------------ visits
   90 days of reactive call-outs ending Fri 2 Oct 2026. Every visit is either fixed first
   time or needed a return, with the reason the engineer logged. */
const DAY = 86400000, END = Date.UTC(2026, 9, 2), DAYS = 90, TARGET = .8, REVISIT = 128;
const TRADES = [['all', 'All trades'], ['hvac', 'HVAC'], ['heat', 'Heating'], ['fire', 'Fire & security']];
const TAB = { hvac: 'AC', heat: 'HT', fire: 'FS' };
const REASONS = [['parts', 'Part not on the van', 'var(--dcf-ftf-acc)'], ['diag', 'Misdiagnosed', 'var(--dcf-ftf-warn)'], ['spec', 'Needed a specialist', 'color-mix(in oklch, var(--dcf-ftf-ink) 55%, var(--dcf-ftf-bg))'], ['access', 'No access', 'color-mix(in oklch, var(--dcf-ftf-good) 55%, var(--dcf-ftf-bg))']];
const PARTS = {
  hvac: ['Condensate pump', 'Fan-motor capacitor', 'Expansion valve', 'Contactor, 32 A'],
  heat: ['Diverter valve', 'Boiler PCB', 'Ignition electrode', 'Pressure-relief valve'],
  fire: ['Optical smoke head', 'Sounder base', 'Call-point glass', 'Panel battery 12 V 7 Ah']
};
const SITES = ['Quayside Offices', 'Ashby Medical Centre', 'Fenwick Retail Park', 'Harbour Lofts', 'St Aldric Library', 'Mercer Court', 'Kingsmead Leisure', 'Pellbrook Depot', 'Tolland House', 'Northgate Clinic'];
/* name, trade, true FTF, visits per weekday, reason weights [parts, diag, spec, access], joined, first day on the books */
const TECHS = [
  ['Ola Nwachukwu', 'hvac', .9, 1.3, [4, 1, 2, 2], 'Senior engineer since 2016', 0],
  ['Imogen Hale', 'hvac', .85, 1.6, [5, 2, 1, 2], 'Engineer since 2020', 0],
  ['Callum Byrne', 'hvac', .81, 1.5, [5, 2, 2, 1], 'Engineer since 2021', 0],
  ['Dev Sharma', 'hvac', .73, 1.8, [8, 2, 1, 1], 'Engineer since 2022', 0],
  ['Tomasz Wilk', 'hvac', .7, 1.7, [3, 6, 2, 1], 'Engineer since 2023', 0],
  ['Sade Bello', 'heat', .88, 1.5, [4, 1, 1, 3], 'Senior engineer since 2017', 0],
  ['Rhian Evans', 'heat', .84, 1.9, [6, 2, 1, 2], 'Engineer since 2019', 0],
  ['Marcus Lowe', 'heat', .79, 2, [6, 2, 1, 2], 'Engineer since 2021', 0],
  ['Hugo Ferreira', 'heat', .72, 1.8, [9, 2, 1, 1], 'Engineer since 2022', 0],
  ['Niamh Quinn', 'heat', 1, .55, [1, 1, 1, 1], 'Apprentice, signed off 14 Sep', 76],
  ['Ewan Grant', 'fire', .91, 1.4, [3, 1, 3, 2], 'Senior engineer since 2015', 0],
  ['Priti Kaur', 'fire', .85, 1.3, [4, 1, 3, 2], 'Engineer since 2020', 0],
  ['Joel Mensah', 'fire', .77, 1.6, [5, 3, 2, 1], 'Engineer since 2022', 0],
  ['Ava Lindqvist', 'fire', .83, .55, [3, 1, 2, 2], 'Part-time engineer since 2021', 0]
].map((t, i) => ({ id: 't' + i, name: t[0], trade: t[1], p: t[2], rate: t[3], w: t[4], about: t[5], from: t[6], i }));
const T = Object.fromEntries(TECHS.map((t) => [t.id, t]));
const VISITS = [];
for (let d = 0; d < DAYS; d++) {
  const t0 = END - (DAYS - 1 - d) * DAY, wd = new Date(t0).getUTCDay();
  if (wd === 0 || wd === 6) continue;
  TECHS.forEach((t) => {
    if (d < t.from) return;
    for (let k = pois(t.rate); k > 0; k--) {
      let reason = null;
      if (r() > t.p) { const s = t.w.reduce((a, b) => a + b, 0); let x = r() * s, j = 0; while (x > t.w[j]) { x -= t.w[j]; j++; } reason = REASONS[j][0]; }
      const part = reason === 'parts' ? PARTS[t.trade][Math.floor(Math.pow(r(), 1.6) * 4)] : null;
      VISITS.push({ d, t0, tech: t.id, reason, part, site: SITES[Math.floor(r() * SITES.length)], at: 8 * 60 + Math.floor(r() * 9) * 60 + Math.floor(r() * 4) * 15 });
    }
