}

/* ------------------------------------------------------------------ state + aggregation */
let period = 90, trade = 'all', sortKey = 'lo', tab = 'tech', sel = 't9';
const stocked = new Set(), booked = {}, mentors = {};
const rowsEl = $('[data-rows]'), detail = $('[data-detail]'), tip = $('[data-tip]'), toastEl = $('[data-toast]');
const inPeriod = (v) => v.d >= DAYS - period;
const techsShown = () => TECHS.filter((t) => trade === 'all' || t.trade === trade);
function agg(list) {
  const n = list.length, fixed = list.filter((v) => !v.reason).length, rs = {}; REASONS.forEach((x) => { rs[x[0]] = 0; });
  list.forEach((v) => { if (v.reason) rs[v.reason]++; });
  const saved = list.filter((v) => v.reason === 'parts' && stocked.has(v.part)).length;
  const w = wilson(fixed, n);
  return { n, fixed, ret: n - fixed, rs, p: w[0], lo: w[1], hi: w[2], proj: n ? (fixed + saved) / n : 0, saved };
}
let S = {};
function compute() { S = {}; TECHS.forEach((t) => { S[t.id] = agg(VISITS.filter((v) => v.tech === t.id && inPeriod(v))); }); }
const teamVisits = () => VISITS.filter((v) => inPeriod(v) && (trade === 'all' || T[v.tech].trade === trade));
const X = (v) => Math.max(0, Math.min(100, (v - .4) / .6 * 100));
const klass = (s) => (s.hi < TARGET ? 'below' : s.lo >= TARGET ? '' : s.p < TARGET ? 'below' : 'unsure');

/* ------------------------------------------------------------------ KPIs + filters */
function renderKpis() {
  const tv = teamVisits(), a = agg(tv), top = REASONS.map((x) => [x, a.rs[x[0]]]).sort((p, q) => q[1] - p[1])[0];
  const k = [
    ['Team first-time fix', '<span class="' + (a.p >= TARGET ? 'good' : 'bad') + '">' + pc(a.p, 1) + '</span><em>±' + ((a.hi - a.lo) * 50).toFixed(1) + '</em>', a.fixed + ' of ' + a.n + ' visits · target ' + pc(TARGET)],
    ['Return visits', String(a.ret), '£' + (a.ret * REVISIT).toLocaleString('en-GB') + ' at £' + REVISIT + ' a return'],
    ['Top cause', a.ret ? pc(top[1] / a.ret) : '–', a.ret ? top[0][1].toLowerCase() + ' · ' + top[1] + ' returns' : 'no returns'],
    ['Van-stock what-if', stocked.size ? '<span class="good">' + pc(a.proj, 1) + '</span>' : '–', stocked.size ? '+' + ((a.proj - a.p) * 100).toFixed(1) + ' pts with ' + stocked.size + ' part' + (stocked.size > 1 ? 's' : '') + ' added' : 'add parts from a technician'],
    ['Engineers below target', String(techsShown().filter((t) => S[t.id].n && S[t.id].hi < TARGET).length), 'whole interval under ' + pc(TARGET)]
  ];
  const dl = $('[data-kpis]');
  if (!dl.children.length) dl.innerHTML = k.map((x, i) => '<div style="--i:' + i + '"><dt>' + x[0] + '</dt><dd data-k="' + i + '"></dd></div>').join('');
  k.forEach((x, i) => { dl.querySelector('[data-k="' + i + '"]').innerHTML = x[1] + '<small>' + esc(x[2]) + '</small>'; });
  $('[data-trade]').innerHTML = TRADES.map((x) => '<button type="button" role="radio" aria-checked="' + (trade === x[0]) + '" tabindex="' + (trade === x[0] ? 0 : -1) + '" data-v="' + x[0] + '">' + x[1] + '</button>').join('');
}

/* ------------------------------------------------------------------ forest plot */
function buildRows() {
  rowsEl.innerHTML = TECHS.map((t) => '<li role="option" data-id="' + t.id + '" aria-selected="false" tabindex="-1"><span class="nm"><span class="tr">' + TAB[t.trade] + '</span><b>' + esc(t.name) + '</b></span>' +
    '<span class="n" data-n></span><div class="tk"><i class="ci"></i><span class="pt"><i></i></span></div><span class="v" data-v></span></li>').join('');
}
function sorted(list) {
  const f = { rate: (t) => -S[t.id].p, lo: (t) => -S[t.id].lo, n: (t) => -S[t.id].n }[sortKey];
