  const list = sorted(techsShown()), show = new Set(list.map((t) => t.id));
  list.forEach((t) => rowsEl.appendChild(rowsEl.querySelector('[data-id="' + t.id + '"]')));
  $$('li', rowsEl).forEach((li) => {
    const t = T[li.dataset.id], s = S[t.id];
    li.hidden = !show.has(t.id) || !s.n;
