    li.style.setProperty('--lo', X(s.lo).toFixed(2)); li.style.setProperty('--hi', X(s.hi).toFixed(2)); li.style.setProperty('--p', X(s.p).toFixed(2));
    li.querySelector('[data-n]').textContent = s.n;
    li.querySelector('[data-v]').innerHTML = pc(s.p) + '<small>' + pc(s.lo).replace('%', '') + '–' + pc(s.hi) + '</small>';
    li.setAttribute('aria-label', t.name + ': ' + pc(s.p) + ' first-time fix on ' + s.n + ' visits, 95% interval ' + pc(s.lo) + ' to ' + pc(s.hi));
  });
  if (o.flip && !RM) $$('li', rowsEl).forEach((li) => {
    const y0 = first[li.dataset.id]; if (y0 == null || li.hidden) return;
    const dy = y0 - li.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) li.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 560, easing: 'cubic-bezier(.16,1,.3,1)' });
  });
  if (o.enter && !RM) $$('li:not([hidden]) .tk', rowsEl).forEach((tk, i) => tk.animate([{ clipPath: 'inset(0 100% 0 0)' }, { clipPath: 'inset(0 0 0 0)' }], { duration: 800, delay: 150 + i * 40, easing: 'cubic-bezier(.16,1,.3,1)', fill: 'backwards' }));
  const a = agg(teamVisits());
  $('[data-avg]').style.left = X(a.p).toFixed(2) + '%';
  $('[data-tgt]').style.left = X(TARGET).toFixed(2) + '%';
  const aw = $('[data-axis]').clientWidth || 400;
  $('[data-axis]').innerHTML = [.5, .6, .7, .8, .9, 1].filter((v, i) => aw > 260 || i % 2 === 1).map((v) => '<span style="left:' + X(v) + '%"' + (v === 1 ? ' class="end"' : '') + '>' + pc(v) + '</span>').join('');
  $('[data-key]').innerHTML = '<i class="kt"></i>' + pc(TARGET) + ' target <i class="ka"></i>team ' + pc(a.p, 1);
}

/* ------------------------------------------------------------------ trend + causes */
function renderTrend(quiet) {
  const box = $('[data-trend]'), W = Math.max(280, box.clientWidth), H = Math.max(180, box.clientHeight), pl = 34, pr = 10, pt = 14, pb = 24;
  const tv = teamVisits(), weeks = [];
  const nW = Math.ceil(period / 7);
  for (let k = 0; k < nW; k++) { const d1 = DAYS - (nW - k) * 7, list = tv.filter((v) => v.d >= d1 && v.d < d1 + 7); weeks.push(Object.assign({ d1, list }, agg(list))); }
  const lo = .5, Y = (v) => pt + (H - pt - pb) * (1 - (Math.max(lo, v) - lo) / (1 - lo)), bw = (W - pl - pr) / nW, XC = (k) => pl + bw * k + bw / 2;
  const vmax = Math.max(1, ...weeks.map((w) => w.n));
