  weeks.forEach((w, k) => { const h = w.n / vmax * 34; s += '<rect class="vis" x="' + (XC(k) - bw * .3).toFixed(1) + '" y="' + (H - pb - h).toFixed(1) + '" width="' + (bw * .6).toFixed(1) + '" height="' + h.toFixed(1) + '" rx="2"/>'; });
  const up = weeks.map((w, k) => XC(k).toFixed(1) + ' ' + Y(w.hi).toFixed(1)), dn = weeks.map((w, k) => XC(k).toFixed(1) + ' ' + Y(w.lo).toFixed(1)).reverse();
  s += '<g class="area"><path class="band" d="M' + up.join('L') + 'L' + dn.join('L') + 'Z"/></g>';
  s += '<line class="tg" x1="' + pl + '" x2="' + (W - pr) + '" y1="' + Y(TARGET) + '" y2="' + Y(TARGET) + '"/>';
  s += '<path class="ln" pathLength="1" d="M' + weeks.map((w, k) => XC(k).toFixed(1) + ' ' + Y(w.p).toFixed(1)).join('L') + '"/>';
  s += weeks.map((w, k) => '<circle class="dot" cx="' + XC(k).toFixed(1) + '" cy="' + Y(w.p).toFixed(1) + '" r="3.5"/>').join('');
  weeks.forEach((w, k) => { if (k % (bw < 34 ? 2 : 1) === 0) s += '<text class="ax" x="' + XC(k).toFixed(1) + '" y="' + (H - 6) + '" text-anchor="middle">' + new Date(END - (DAYS - 1 - w.d1) * DAY).toLocaleDateString('en-GB', { timeZone: 'UTC', day: 'numeric', month: 'short' }) + '</text>'; });
  s += '<line class="xh" data-xh x1="0" x2="0" y1="' + pt + '" y2="' + (H - pb) + '"/>' + weeks.map((w, k) => '<rect class="hit" data-wk="' + k + '" x="' + (pl + bw * k).toFixed(1) + '" y="' + pt + '" width="' + bw.toFixed(1) + '" height="' + (H - pt - pb) + '"/>').join('') + '</svg>';
