    REASONS.map((x, i) => a.rs[x[0]] ? '<i style="--w:' + a.rs[x[0]] + ';--c:' + x[2] + ';--i:' + i + '" data-cause="' + x[0] + '"></i>' : '').join('') + '</div><ul>' +
    REASONS.map((x) => '<li style="--c:' + x[2] + '"><i></i><span>' + x[1] + '</span><b>' + pc(a.rs[x[0]] / tot) + '</b><small>' + a.rs[x[0]] + ' returns · £' + (a.rs[x[0]] * REVISIT).toLocaleString('en-GB') + '</small></li>').join('') + '</ul>';
