/* ------------------------------------------------------------------ detail */
function renderDetail(quiet) {
  const t = T[sel], s = S[t.id], mine = VISITS.filter((v) => v.tech === t.id && inPeriod(v));
  const cls = klass(s), col = cls === 'below' ? 'var(--dcf-ftf-acc)' : cls === 'unsure' ? 'var(--dcf-ftf-warn)' : 'var(--dcf-ftf-good)';
  detail.style.setProperty('--c', col); detail.toggleAttribute('data-quiet', !!quiet);
