  let h = '<p class="k">' + esc(TRADES.find((x) => x[0] === t.trade)[1]) + '</p><h3>' + esc(t.name) + '</h3><p class="sub">' + esc(t.about) + '</p>' +
    '<div class="big"><b>' + pc(s.p) + '</b><span>95% interval <strong>' + pc(s.lo) + '–' + pc(s.hi) + '</strong> on ' + s.n + ' visits. ' + verdict + '</span></div>' +
    '<h4>Last ' + last.length + ' visits <span>oldest first</span></h4><div class="last" data-last>' + last.map((v, i) => '<i style="--i:' + i + '" class="' + (v.reason ? 'r' : '') + '" data-vi="' + VISITS.indexOf(v) + '">' + (v.reason ? v.reason[0].toUpperCase() : '') + '</i>').join('') + '</div>' +
    '<h4>Return causes <span>' + s.ret + ' return' + (s.ret === 1 ? '' : 's') + '</span></h4><ul class="rs">' + REASONS.map((x) => '<li style="--c:' + x[2] + '"><span>' + x[1] + '</span><span class="b"><i style="--w:' + (s.rs[x[0]] / maxR).toFixed(3) + '"></i></span><b>' + s.rs[x[0]] + '</b></li>').join('') + '</ul>';
