    if (s.saved) h += '<p class="what">With those parts on the van: <b>' + pc(s.proj, 1) + '</b> (+' + ((s.proj - s.p) * 100).toFixed(1) + ' pts, ' + s.saved + ' return' + (s.saved > 1 ? 's' : '') + ' avoided).</p>';
