    : s.n < 20 ? '<button type="button" class="dcf-ftf__btn ghost" data-buddy="' + t.id + '" aria-pressed="' + !!mentors[t.id] + '">' + (mentors[t.id] ? 'Buddied with a senior' : 'Buddy with a senior') + '</button>'
    : '<button type="button" class="dcf-ftf__btn ghost" data-buddy="' + t.id + '" aria-pressed="' + !!mentors[t.id] + '">' + (mentors[t.id] ? 'Mentoring this quarter' : 'Nominate as mentor') + '</button>') + '</div>';
