function setTab(t, focus) {
  tab = t;
  $$('[data-tab]').forEach((b) => { const on = b.dataset.tab === t; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; if (on && focus) b.focus(); });
  $$('[data-view]').forEach((v) => { v.hidden = v.dataset.view !== t; });
  const so = $('[data-sort]');
  if (t === 'trend') { so.setAttribute('aria-disabled', 'true'); so.title = 'Ranking applies to the technician view'; $$('button', so).forEach((b) => b.setAttribute('aria-disabled', 'true')); renderTrend(); }
  else { so.removeAttribute('aria-disabled'); so.removeAttribute('title'); $$('button', so).forEach((b) => b.removeAttribute('aria-disabled')); }
}

root.addEventListener('click', (e) => {
  const t = e.target;
  const tb = t.closest('[data-tab]'); if (tb) { setTab(tb.dataset.tab); return; }
  const pb = t.closest('[data-period] button'); if (pb) { period = +pb.dataset.v; radio(pb.parentElement, pb); renderAll({ flip: true }); return; }
  const tr = t.closest('[data-trade] button');
  if (tr) { trade = tr.dataset.v; if (trade !== 'all' && T[sel].trade !== trade) sel = TECHS.find((x) => x.trade === trade).id; renderAll({ flip: true }); const b = $('[data-trade] [data-v="' + trade + '"]'); if (b) b.focus(); return; }
  const so = t.closest('[data-sort] button');
  if (so) { if (so.getAttribute('aria-disabled') === 'true') { toast('Ranking applies to the By technician view.'); return; } sortKey = so.dataset.v; radio(so.parentElement, so); paintRows({ flip: true }); return; }
  const li = t.closest('[data-rows] li'); if (li) { select(li.dataset.id); return; }
  const pt = t.closest('[data-part]');
  if (pt) {
    const p = pt.dataset.part; if (stocked.has(p)) stocked.delete(p); else stocked.add(p);
    compute(); renderKpis(); renderDetail(true); if (tab === 'trend') renderTrend(true);
    const b = detail.querySelector('[data-part="' + CSS.escape(p) + '"]'); if (b) b.focus();
    toast(stocked.has(p) ? p + ' added to the standard van stock list.' : p + ' taken off the van stock list.');
    return;
  }
  const rd = t.closest('[data-ride]');
  if (rd) {
    const tt = T[rd.dataset.ride], lead = TECHS.filter((x) => x.trade === tt.trade).sort((a, b) => b.p - a.p)[0];
    rd.setAttribute('aria-busy', 'true'); rd.textContent = 'Checking diaries…';
    setTimeout(() => { if (!root.isConnected) return; booked[tt.id] = 'Ride-along Tue 6 Oct with ' + lead.name.split(' ')[0]; renderDetail(true); toast(tt.name + ' rides with ' + lead.name + ' on Tue 6 Oct.'); }, 650);
    return;
  }
  const bd = t.closest('[data-buddy]');
  if (bd) { const id = bd.dataset.buddy; mentors[id] = !mentors[id]; renderDetail(true); const b = detail.querySelector('[data-buddy]'); if (b) b.focus(); toast(mentors[id] ? 'Noted for the quarterly people review.' : 'Removed from the review list.'); }
});
root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (e.key === 'Escape') { tip.classList.remove('on'); return; }
  if (t.matches('[data-rows] li')) {
    const list = $$('li', rowsEl).filter((x) => !x.hidden), i = list.indexOf(t); let n = null;
    if (e.key === 'ArrowDown') n = list[Math.min(list.length - 1, i + 1)]; if (e.key === 'ArrowUp') n = list[Math.max(0, i - 1)];
    if (e.key === 'Home') n = list[0]; if (e.key === 'End') n = list[list.length - 1];
    if (n) { e.preventDefault(); select(n.dataset.id, true); return; }
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); const b = detail.querySelector('button:not([aria-disabled="true"])'); if (b) b.focus(); return; }
  }
  const grp = t.closest('[role="radiogroup"], [role="tablist"]');
  if (grp && /^Arrow(Left|Right)$/.test(e.key)) {
    e.preventDefault(); if (grp.getAttribute('aria-disabled') === 'true') return;
    const bs = $$('button', grp), i = bs.indexOf(t), n = bs[(i + (e.key === 'ArrowRight' ? 1 : -1) + bs.length) % bs.length]; n.focus(); n.click();
  }
});

/* hover */
function showTip(html, cx, cy) {
  const rr = root.getBoundingClientRect(); tip.innerHTML = html; tip.classList.add('on');
  let x = cx - rr.left + 14, y = cy - rr.top + 16; const w = tip.offsetWidth, h = tip.offsetHeight;
  if (x + w > rr.width - 8) x = cx - rr.left - w - 14; if (y + h > rr.height - 8) y = cy - rr.top - h - 12;
  tip.style.transform = 'translate(' + Math.max(6, x) + 'px,' + Math.max(6, y) + 'px)';
}
const fdate = (t) => new Date(t).toLocaleDateString('en-GB', { timeZone: 'UTC', weekday: 'short', day: 'numeric', month: 'short' });
const hm = (m) => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
root.addEventListener('pointermove', (e) => {
  const tk = e.target.closest('[data-rows] .tk');
  if (tk) { const t = T[tk.parentElement.dataset.id], s = S[t.id]; showTip('<b>' + esc(t.name) + '</b><span>' + s.fixed + ' fixed first time of ' + s.n + ' visits</span><span>' + pc(s.p, 1) + ' · 95% interval ' + pc(s.lo, 1) + '–' + pc(s.hi, 1) + '</span>', e.clientX, e.clientY); return; }
  const hit = e.target.closest('[data-trend] .hit'), box = $('[data-trend]'), xh = $('[data-xh]');
  if (hit && box._weeks) {
    const k = +hit.dataset.wk, w = box._weeks[k], x = box._xc(k);
    if (xh) { xh.setAttribute('x1', x); xh.setAttribute('x2', x); xh.classList.add('on'); }
    showTip('<b>Week of ' + fdate(END - (DAYS - 1 - w.d1) * DAY) + '</b><span>' + pc(w.p, 1) + ' first-time fix · ' + w.fixed + ' of ' + w.n + '</span><span>95% band ' + pc(w.lo, 1) + '–' + pc(w.hi, 1) + '</span>', e.clientX, e.clientY); return;
  }
  if (xh) xh.classList.remove('on');
  const vi = e.target.closest('[data-last] i');
  if (vi) { const v = VISITS[+vi.dataset.vi]; showTip('<b>' + fdate(v.t0) + ', ' + hm(v.at) + '</b><span>' + esc(v.site) + '</span><span>' + (v.reason ? REASONS.find((x) => x[0] === v.reason)[1] + (v.part ? ': ' + esc(v.part) : '') : 'Fixed first time') + '</span>', e.clientX, e.clientY); return; }
  const cz = e.target.closest('[data-cause]');
  if (cz) { const a = agg(teamVisits()), x = REASONS.find((q) => q[0] === cz.dataset.cause); showTip('<b>' + x[1] + '</b><span>' + a.rs[x[0]] + ' of ' + a.ret + ' returns (' + pc(a.rs[x[0]] / Math.max(1, a.ret)) + ')</span>', e.clientX, e.clientY); return; }
  tip.classList.remove('on');
});
root.addEventListener('pointerleave', () => { tip.classList.remove('on'); const xh = $('[data-xh]'); if (xh) xh.classList.remove('on'); });
$('[data-scroll]').addEventListener('scroll', () => tip.classList.remove('on'), { passive: true });

/* mount */
buildRows(); renderAll({ enter: true });
if (window.ResizeObserver) {
  let lk = '';
  const ro = new ResizeObserver(() => {
    if (!root.isConnected) { ro.disconnect(); return; }
    const b = $('[data-trend]'), k = b.clientWidth + 'x' + b.clientHeight;
    if (tab === 'trend' && b.clientWidth && k !== lk) { lk = k; renderTrend(true); }
  });
  ro.observe($('[data-trend]'));
}

css:
.dcf-daily {
  --dcf-daily-bg: oklch(0.972 0.006 250);
  --dcf-daily-ink: oklch(0.27 0.045 262);
  --dcf-daily-acc: oklch(0.5 0.17 263);
  --dcf-daily-warn: oklch(0.66 0.17 46);
  --dcf-daily-ok: oklch(0.6 0.13 155);
  --dcf-daily-rain: oklch(0.64 0.11 232);
  --dcf-daily-paper: color-mix(in oklch, var(--dcf-daily-bg) 25%, white);
  --dcf-daily-sunk: color-mix(in oklch, var(--dcf-daily-bg) 92%, var(--dcf-daily-ink));
  --dcf-daily-line: color-mix(in oklch, var(--dcf-daily-ink) 14%, transparent);
  --dcf-daily-hair: color-mix(in oklch, var(--dcf-daily-ink) 7.5%, transparent);
  --dcf-daily-soft: color-mix(in oklch, var(--dcf-daily-ink) 5%, transparent);
  --dcf-daily-mute: color-mix(in oklch, var(--dcf-daily-ink) 62%, var(--dcf-daily-bg));
  --dcf-daily-faint: color-mix(in oklch, var(--dcf-daily-ink) 40%, var(--dcf-daily-bg));
  --dcf-daily-margin: color-mix(in oklch, oklch(0.62 0.18 22) 45%, transparent);
  --dcf-daily-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dcf-daily-out: cubic-bezier(.2, .9, .3, 1);
  --dcf-daily-spring: linear(0, .009, .035 2.1%, .141 4.4%, .723 12.9%, .938 16.7%, 1.017 19.4%, 1.067, 1.077 24.5%, 1.064 27.1%, 1.002 33.9%, .987 37.7%, .983 41.4%, .995 52.6%, 1.001 63.2%, 1);
  width: 100%;
  height: var(--dcf-daily-h, 680px);
  container-type: inline-size;
  container-name: dcf-daily;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 18px;
  background: var(--dcf-daily-bg);
  color: var(--dcf-daily-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dcf-daily-acc);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dcf-daily-ink) 22%, transparent) transparent;
  box-shadow: inset 0 0 0 1px var(--dcf-daily-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, ul, ol, dl, dd, fieldset) { margin: 0; padding: 0; }
  & fieldset { border: 0; min-width: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dcf-daily-acc); outline-offset: 2px; border-radius: 6px; }
  & [hidden] { display: none !important; }
}
.dcf-daily__ic { width: 16px; height: 16px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }

.dcf-daily__shell { height: 100%; display: grid; grid-template-columns: 228px minmax(0, 1fr); }
.dcf-daily__strip { display: flex; flex-direction: column; gap: 10px; min-height: 0; padding: 16px 12px 12px; border-right: 1px solid var(--dcf-daily-line); background: var(--dcf-daily-sunk); }
.dcf-daily__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 4px 4px;
  & svg { width: 34px; height: 34px; flex: none; padding: 6px; border-radius: 9px; background: var(--dcf-daily-acc); fill: none; stroke: white; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 780; letter-spacing: -.025em; line-height: 1.2; }
  & small { display: block; font-size: 11.5px; color: var(--dcf-daily-mute); }
}
.dcf-daily__seg {
  display: grid; grid-template-columns: 1fr 1fr; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dcf-daily-bg); box-shadow: inset 0 0 0 1px var(--dcf-daily-hair);
  & button { padding: 5px 6px; border-radius: 7px; font-size: 12px; font-weight: 640; text-align: center; color: var(--dcf-daily-mute); transition: color .2s, background-color .2s; }
  & button:hover { color: var(--dcf-daily-ink); }
  & button[aria-checked="true"] { background: var(--dcf-daily-paper); color: var(--dcf-daily-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dcf-daily-ink) 18%, transparent); }
}
.dcf-daily__days {
  flex: 1; min-height: 0; overflow: auto; display: grid; align-content: start; gap: 4px; padding: 2px; margin: 0 -2px;
  & li {
    --c: var(--dcf-daily-ok);
    position: relative; display: grid; grid-template-columns: 40px minmax(0, 1fr) auto; align-items: center; gap: 2px 10px; padding: 8px 10px 8px 8px; border-radius: 12px; cursor: pointer;
    transition: background-color .2s, box-shadow .2s;
    animation: dcf-daily-rise .5s var(--dcf-daily-out) both; animation-delay: calc(var(--i) * 30ms);
    &:hover { background: var(--dcf-daily-soft); }
    &[aria-selected="true"] { background: var(--dcf-daily-paper); box-shadow: inset 0 0 0 1px var(--dcf-daily-line), 0 6px 16px -10px color-mix(in oklch, var(--dcf-daily-ink) 40%, transparent); }
    &.sub { --c: var(--dcf-daily-warn); } &.draft { --c: var(--dcf-daily-acc); }
    &:focus-visible { outline-offset: -2px; }
  }
  & .dt { grid-row: span 2; display: grid; justify-items: center; line-height: 1; padding: 5px 0; border-radius: 9px; background: var(--dcf-daily-paper); box-shadow: inset 0 0 0 1px var(--dcf-daily-hair); }
  & .dt small { font-size: 9.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--dcf-daily-faint); }
  & .dt b { font: 750 17px var(--dcf-daily-mono); letter-spacing: -.04em; }
  & .st { display: flex; align-items: center; gap: 6px; min-width: 0; font-size: 11.5px; font-weight: 650; color: var(--dcf-daily-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .st i { flex: none; width: 7px; height: 7px; border-radius: 50%; background: var(--c); }
  & .wx { grid-row: span 2; color: var(--dcf-daily-mute); }
  & .wx svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & .hc { display: flex; align-items: center; gap: 6px; font: 600 11px var(--dcf-daily-mono); color: var(--dcf-daily-mute); }
  & .hc span { flex: 1; height: 4px; border-radius: 2px; background: var(--dcf-daily-hair); overflow: hidden; }
  & .hc span i { display: block; height: 100%; width: calc(var(--w) * 1%); background: color-mix(in oklch, var(--dcf-daily-ink) 40%, transparent); border-radius: 2px; }
}

.dcf-daily__report { display: flex; flex-direction: column; min-width: 0; min-height: 0; }
.dcf-daily__rh {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: 10px 16px; padding: 16px 20px 0;
  & .k { font-size: 10.5px; font-weight: 700; letter-spacing: .13em; text-transform: uppercase; color: var(--dcf-daily-faint); }
  & h2 { margin-top: 2px; font-size: clamp(19px, 2.2cqi, 26px); font-weight: 780; letter-spacing: -.035em; line-height: 1.1; text-wrap: balance; }
  & .pill { display: inline-flex; align-items: center; gap: 6px; margin-left: 10px; padding: 2px 9px; border-radius: 99px; font: 700 11px system-ui, sans-serif; letter-spacing: .04em; vertical-align: 5px; color: var(--c); background: color-mix(in oklch, var(--c) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 35%, transparent); }
  & .pill i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
  & .acts { display: flex; gap: 6px; }
  & nav { grid-column: 1 / -1; display: flex; gap: 2px; overflow-x: auto; scrollbar-width: none; margin: 4px -6px 0; padding-bottom: 8px; border-bottom: 1px solid var(--dcf-daily-line); }
  & nav button { padding: 5px 10px; border-radius: 8px; font-size: 12px; font-weight: 620; color: var(--dcf-daily-mute); white-space: nowrap; transition: color .2s, background-color .2s; }
  & nav button:hover { color: var(--dcf-daily-ink); background: var(--dcf-daily-soft); }
  & nav button[aria-current="true"] { color: var(--dcf-daily-acc); background: color-mix(in oklch, var(--dcf-daily-acc) 10%, transparent); }
}
.dcf-daily__kpis {
  grid-column: 1 / -1; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0; margin-top: 10px;
  & > div { padding: 2px 14px; border-left: 1px solid var(--dcf-daily-line); min-width: 0; }
  & > div:first-child { border-left: 0; padding-left: 0; }
  & dt { font-size: 10.5px; font-weight: 680; letter-spacing: .08em; text-transform: uppercase; color: var(--dcf-daily-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd { font: 720 clamp(17px, 1.9cqi, 21px)/1.2 var(--dcf-daily-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & dd small { font: 500 11px system-ui, sans-serif; letter-spacing: 0; color: var(--dcf-daily-mute); margin-left: 4px; }
  & .warn dd { color: var(--dcf-daily-warn); }
}
.dcf-daily__body {
  position: relative; flex: 1; min-height: 0; overflow: auto; overscroll-behavior: contain; padding: 14px 20px 24px 34px; outline: none;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); align-content: start; gap: 14px;
  background: linear-gradient(90deg, transparent 21px, var(--dcf-daily-margin) 21px 22.5px, transparent 22.5px) no-repeat;
  background-attachment: local;
}
.dcf-daily__sec {
  position: relative; min-width: 0; padding: 14px 16px 15px; border-radius: 14px; background: var(--dcf-daily-paper); box-shadow: inset 0 0 0 1px var(--dcf-daily-hair), 0 10px 24px -22px color-mix(in oklch, var(--dcf-daily-ink) 60%, transparent);
  &.wide { grid-column: 1 / -1; }
  &.hl::after { content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; box-shadow: 0 0 0 2px var(--dcf-daily-acc); animation: dcf-daily-hl 1.3s var(--dcf-daily-out) forwards; }
  & h3 { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 2px 8px; margin-bottom: 10px; font-size: 13.5px; font-weight: 750; letter-spacing: -.01em; text-wrap: balance; }
  & h3 span { font-size: 11.5px; font-weight: 500; color: var(--dcf-daily-mute); }
  & .empty { font-size: 12.5px; color: var(--dcf-daily-faint); font-style: italic; }
}
@supports (animation-timeline: view()) {
  .dcf-daily__sec { animation: dcf-daily-reveal linear both; animation-timeline: view(); animation-range: entry 0% entry 55%; }
}

.dcf-daily__wx {
  position: relative; height: 170px;
  & svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
  & .gl { stroke: var(--dcf-daily-hair); }
  & .ax { font: 10px var(--dcf-daily-mono); fill: var(--dcf-daily-faint); }
  & .ax.r { fill: var(--dcf-daily-warn); }
  & .lim { stroke: var(--dcf-daily-warn); stroke-width: 1.5; stroke-dasharray: 5 4; }
  & .liml { font: 650 10px var(--dcf-daily-mono); fill: var(--dcf-daily-warn); }
  & .over { fill: color-mix(in oklch, var(--dcf-daily-warn) 14%, transparent); }
  & .gust { fill: color-mix(in oklch, var(--dcf-daily-acc) 12%, transparent); stroke: var(--dcf-daily-acc); stroke-width: 2; stroke-linejoin: round; }
  & .gfc { fill: none; stroke: var(--dcf-daily-acc); stroke-width: 2; stroke-dasharray: 3 4; opacity: .7; }
  & .rain { fill: var(--dcf-daily-rain); }
  & .temp { fill: none; stroke: var(--dcf-daily-ink); stroke-width: 1.3; stroke-dasharray: 1 3; stroke-linecap: round; }
  & .now { stroke: var(--dcf-daily-ink); stroke-width: 1.5; }
  & .nowl { font: 700 10px var(--dcf-daily-mono); fill: var(--dcf-daily-ink); }
  & .xh { stroke: var(--dcf-daily-ink); stroke-dasharray: 3 3; opacity: 0; }
  & .xh.on { opacity: .45; }
  & .hit { fill: transparent; }
  & .plot { clip-path: inset(0 100% 0 0); animation: dcf-daily-wipe 1s var(--dcf-daily-out) .15s forwards; }
  &[data-quiet] .plot { animation: none; clip-path: none; }
}
.dcf-daily__wxsum { display: flex; flex-wrap: wrap; gap: 4px 16px; margin-top: 8px; font-size: 12px; color: var(--dcf-daily-mute); & b { color: var(--dcf-daily-ink); font-family: var(--dcf-daily-mono); } & .bad b { color: var(--dcf-daily-warn); } & i { display: inline-block; width: 10px; height: 10px; margin-right: 5px; border-radius: 2px; vertical-align: -1px; background: var(--c); } }

.dcf-daily__lab {
  & .stack { display: flex; height: 14px; border-radius: 4px; overflow: hidden; gap: 2px; margin-bottom: 10px; }
  & .stack i { flex: var(--w) 1 0; background: var(--c); transition: flex-grow .5s var(--dcf-daily-out); }
  & li { display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; align-items: center; gap: 8px; padding: 4px 0; border-top: 1px solid var(--dcf-daily-hair); font-size: 12.5px; }
  & li > i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & .num { display: flex; align-items: center; gap: 4px; font: 700 13px var(--dcf-daily-mono); font-variant-numeric: tabular-nums; }
  & .num output { min-width: 24px; text-align: center; }
  & .num output.bump { animation: dcf-daily-bump .4s var(--dcf-daily-spring); }
  & .num button { display: grid; place-items: center; width: 24px; height: 24px; border-radius: 7px; box-shadow: inset 0 0 0 1px var(--dcf-daily-line); color: var(--dcf-daily-mute); transition: background-color .2s, color .2s, transform .2s var(--dcf-daily-spring); }
  & .num button:hover { color: var(--dcf-daily-ink); background: var(--dcf-daily-soft); }
  & .num button:active { transform: scale(.9); }
  & .num button[aria-disabled="true"] { opacity: .35; cursor: not-allowed; }
  & .num .dcf-daily__ic { width: 12px; height: 12px; }
  & .tot { display: flex; justify-content: space-between; padding-top: 6px; border-top: 1px solid var(--dcf-daily-line); font-size: 12px; color: var(--dcf-daily-mute); }
  & .tot b { font: 750 13px var(--dcf-daily-mono); color: var(--dcf-daily-ink); }
}
.dcf-daily__work {
  display: grid; gap: 10px;
  & li { display: grid; gap: 4px; }
  & .t { display: flex; justify-content: space-between; gap: 8px; font-size: 12.5px; }
  & .t b { font-weight: 620; }
