const LIMIT = 20, NOWH = 14, SHIFT = [7, 17];
const TRADES = [['gw', 'Groundworks', 8, 'oklch(0.62 0.09 70)'], ['br', 'Bricklayers', 14, 'oklch(0.6 0.15 32)'], ['cp', 'Carpenters', 6, 'oklch(0.72 0.12 85)'], ['sc', 'Scaffolders', 4, 'oklch(0.55 0.04 262)'], ['me', 'M&E', 7, 'oklch(0.58 0.13 250)'], ['rf', 'Roofers', 4, 'oklch(0.5 0.08 180)']];
const DATES = [[9, 17], [9, 18], [9, 21], [9, 22], [9, 23], [9, 24], [9, 25], [9, 28], [9, 29], [9, 30], [10, 1], [10, 2]];
const ACTS = [
  ['Brickwork, plots 21–24, lift 3', 'br', 0, 6.5],
  ['Drainage run D4–D7 and manholes', 'gw', 0, 9],
  ['First-fix electrics, plots 9–14', 'me', 0, 5.5],
  ['Roof trusses, block B', 'cp', 4, 11],
