const DELIV = [
  ['Harwell Building Supplies', 'Facing bricks, Wyvern Red ×9,000'], ['Brenmoor Reinforcement', 'Mesh A252, 40 sheets'], ['Kerrin Timber', 'Roof trusses, block B (set 1)'],
  ['Ashdown Readymix', 'C32/40 concrete, 6 m³'], ['Harwell Building Supplies', 'Plasterboard 12.5 mm, 2 packs'], ['Medway Drainage', '150 mm pipe & bends'], ['Kerrin Timber', 'Roof trusses, block B (set 2)'], ['Tarrant Electrical', 'Cable drums, 6 × 100 m']
];
const DAYS = DATES.map(([m, d], i) => {
  const t = Date.UTC(2026, m - 1, d), windy = i === 4, wet = i === 8, today = i === 11;
  const hours = [];
  for (let h = 6; h <= 18; h++) {
    const k = (h - 6) / 12, diurnal = Math.sin(Math.PI * Math.min(1, k * 1.15));
    let gust = 4 + diurnal * 5 + r() * 3 + (i % 3) * 1.1;
