  }
  const lab = {}; TRADES.forEach(([k, n, base]) => { lab[k] = Math.max(0, Math.round(base * (wet && k === 'br' ? .4 : 1) + (r() - .5) * 3)); });
  if (i < 4) lab.rf = 0;
  const acts = ACTS.filter((a) => i >= a[2]).map((a) => {
    const prog = (j) => Math.min(100, Math.round(a[3] * (j - a[2] + 1) * (j >= 8 && a[1] === 'br' ? .9 : 1)));
