  if (!list.some((d) => d.i === sel)) sel = list[0].i;
  daysEl.innerHTML = list.map((d, k) => '<li role="option" style="--i:' + k + '" class="' + (d.status === 'ok' ? '' : d.status === 'draft' || d.status === 'ret' ? 'draft' : 'sub') + '" data-i="' + d.i + '" aria-selected="' + (d.i === sel) + '" tabindex="' + (d.i === sel ? 0 : -1) + '" aria-label="' + fmt(d.t, { weekday: 'long', day: 'numeric', month: 'long' }) + ', ' + STAT[d.status][0] + ', ' + heads(d) + ' operatives">' +
