  else acts = '<button type="button" class="dcf-daily__btn ghost" data-share aria-pressed="' + d.shared + '">' + (d.shared ? 'On the client portal' : 'Share with client') + '</button>';
  rh.innerHTML = '<div><p class="k">' + d.no + ' · Wren &amp; Calloway · Tolland Street</p><h2>' + fmt(d.t, { weekday: 'long', day: 'numeric', month: 'long' }) + '<span class="pill" style="--c:' + st[1] + '"><i></i>' + st[0] + '</span></h2></div>' +
    '<div class="acts">' + acts + '</div>' +
    '<dl class="dcf-daily__kpis"><div><dt>Operatives</dt><dd>' + heads(d) + '</dd></div><div><dt>Hours worked</dt><dd>' + (heads(d) * 9.5).toLocaleString('en-GB') + '</dd></div>' +
    '<div class="' + (craneLost(d) ? 'warn' : '') + '"><dt>Crane stood down</dt><dd>' + craneLost(d) + '<small>h</small></dd></div><div><dt>Deliveries</dt><dd>' + dOk + '<small>of ' + d.dl.length + ' accepted</small></dd></div>' +
