css:
.dcf-subs {
  --dcf-subs-bg: oklch(0.205 0.018 38);
  --dcf-subs-ink: oklch(0.95 0.012 75);
  --dcf-subs-acc: oklch(0.81 0.12 82);
  --dcf-subs-good: oklch(0.76 0.13 150);
  --dcf-subs-bad: oklch(0.66 0.18 28);
  --dcf-subs-panel: color-mix(in oklch, var(--dcf-subs-bg) 93%, var(--dcf-subs-ink));
  --dcf-subs-deep: color-mix(in oklch, var(--dcf-subs-bg) 78%, black);
  --dcf-subs-line: color-mix(in oklch, var(--dcf-subs-ink) 12%, transparent);
