  --dcf-subs-soft: color-mix(in oklch, var(--dcf-subs-ink) 6%, transparent);
  --dcf-subs-mute: color-mix(in oklch, var(--dcf-subs-ink) 62%, var(--dcf-subs-bg));
  --dcf-subs-faint: color-mix(in oklch, var(--dcf-subs-ink) 40%, var(--dcf-subs-bg));
