  width: 100%;
  height: var(--dcf-subs-h, 680px);
  container-type: inline-size;
  container-name: dcf-subs;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  border-radius: 18px;
  background: radial-gradient(90% 70% at 0% 0%, color-mix(in oklch, var(--dcf-subs-acc) 8%, transparent), transparent 55%), var(--dcf-subs-bg);
  color: var(--dcf-subs-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  accent-color: var(--dcf-subs-acc);
  scrollbar-width: thin;
  scrollbar-color: color-mix(in oklch, var(--dcf-subs-ink) 22%, transparent) transparent;
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h3, h4, p, ul, ol, dl, dd) { margin: 0; padding: 0; }
  & :where(ul, ol) { list-style: none; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: inherit; }
  & :focus-visible { outline: 2px solid var(--dcf-subs-acc); outline-offset: 2px; border-radius: 7px; }
  & [hidden] { display: none !important; }
}
.dcf-subs__shell {
  position: relative; height: 100%; display: grid; grid-template-columns: 252px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr);
  grid-template-areas: "top top" "weights main"; gap: 12px 14px; padding: 16px 18px;
}
.dcf-subs__top { grid-area: top; display: flex; align-items: center; flex-wrap: wrap; gap: 10px 16px; }
.dcf-subs__brand {
  display: flex; align-items: center; gap: 11px; margin-right: auto; min-width: 0;
  & svg { width: 36px; height: 36px; flex: none; padding: 7px; border-radius: 10px; background: var(--dcf-subs-acc); fill: none; stroke: var(--dcf-subs-deep); stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: clamp(17px, 1.9cqi, 21px); font-weight: 780; letter-spacing: -.035em; line-height: 1.1; text-wrap: balance; }
  & small { display: block; font-size: 11.5px; color: var(--dcf-subs-mute); }
}
.dcf-subs__seg {
